INSERT INTO `t_knowledge` (`question`, `answer`, `status`, `tag`, `del_flag`, `view_count`, `last_view_time`, `add_time`) VALUES
('<p>Q201. String的intern()方法作用及底层原理？</p>', '<p>答案解析：intern()将字符串放入运行时常量池并返回池中引用。JDK6及之前常量池在永久代，intern()会把首次遇到的字符串复制到永久代；JDK7+常量池移到堆中，intern()直接在常量池记录堆中对象的引用，不再复制。常用场景：大量重复字符串通过intern()节省内存，但需注意常量池大小有限，过多intern会导致性能下降。示例：`String s1 = new String("a").intern(); String s2 = "a"; System.out.println(s1 == s2); // true`。实际项目中通过-XX:StringTableSize调大常量池大小。</p>', 1, 1, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q202. Java中深拷贝与浅拷贝的区别？如何实现深拷贝？</p>', '<p>答案解析：浅拷贝只复制对象本身，不复制其内部引用的对象，新旧对象共享内部引用，修改一个会影响另一个；深拷贝则递归复制所有引用对象，新旧对象完全独立。实现方式有三种：1、序列化方式——将对象序列化为字节流再反序列化回来，通用但性能差，要求所有引用对象实现Serializable；<br/>2、构造器方式（推荐）——定义拷贝构造器逐字段new出新对象，代码清晰可控；<br/>3、Cloneable接口——重写clone()方法手动递归克隆。实际项目中推荐MapStruct或手动构造器深拷贝，避免序列化的性能开销和Cloneable的设计缺陷。</p>', 1, 1, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q203. Java反射机制原理、应用及性能影响？</p>', '<p>答案解析：反射原理是JVM加载类时在方法区存储Class对象（包含类的完整结构信息），反射通过Class对象在运行时动态获取构造器、方法、字段等元数据并操作。获取Class对象有三种方式：Class.forName()动态加载、类名.class编译期获取、对象.getClass()实例获取。通过getDeclaredConstructor()、getDeclaredMethod()、getDeclaredField()可访问包括私有在内的所有成员，setAccessible(true)可绕过权限检查。典型应用：Spring IOC依赖注入通过反射创建Bean并注入属性，MyBatis通过反射将ResultSet映射到实体类，JUnit通过反射调用@Test方法。性能方面，反射比直接调用慢数倍到数十倍，原因是运行时需检查权限、动态解析类型签名，JIT编译器无法对内联优化。优化方案：缓存Method/Field对象、setAccessible(true)关闭安全检查、JDK7+考虑用MethodHandle替代。</p>', 1, 1, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q204. Java四种内部类的特点与使用场景？</p>', '<p>答案解析：1、成员内部类：定义在类中方法外，可访问外部类所有成员，外部类访问内部类需先创建内部类对象。适用于类与类强关联的场景，如Body类中定义Heart类。<br/>2、静态内部类：static修饰，不依赖外部类实例，只能访问外部类静态成员。最经典的用法是Builder模式：`new User.Builder().name("张三").age(25).build()`。<br/>3、局部内部类：定义在方法内部，作用域仅限于该方法，只能访问final或effectively final的局部变量。<br/>4、匿名内部类：没有类名，实例化同时定义类体，JDK8之前广泛用于事件监听和线程创建，JDK8后被Lambda表达式取代。需要注意成员内部类隐式持有外部类引用，非静态内部类的Handler持有Activity会导致内存泄漏。编译后生成Outer$Inner.class、Outer$1.class等独立字节码文件。</p>', 1, 1, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q205. Java SPI机制原理与SpringBoot自动装配的关系？</p>', '<p>答案解析：SPI（Service Provider Interface）是JDK内置的服务发现机制：在classpath的META-INF/services/目录下创建以接口全限定名命名的文件，文件内容为接口实现类的全限定名，通过ServiceLoader.load()加载并实例化所有实现。JDBC驱动加载就是典型SPI——mysql-connector的META-INF/services/java.sql.Driver文件中配置了com.mysql.cj.jdbc.Driver。SPI缺点：一次性加载所有实现、无法按需加载、无法指定顺序。SpringBoot自动装配借鉴SPI思想但做了关键改进：通过在META-INF/spring.factories（2.x）或AutoConfiguration.imports（3.x）中配置自动装配类，配合@ConditionalOnClass、@ConditionalOnBean等条件注解实现按需加载，只有classpath存在对应依赖时才装配。核心区别：SPI全量加载，SpringBoot按条件按需精准加载。</p>', 1, 1, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q206. BigDecimal使用中的常见坑点与正确用法？</p>', '<p>答案解析：四大坑：1、new BigDecimal(double)精度丢失——传入0.1会得到0.1000000000000000055511151231...，须用new BigDecimal("0.1")或BigDecimal.valueOf(0.1)。<br/>2、equals比较因scale不同返回false——new BigDecimal("1.0")和new BigDecimal("1.00")的equals为false（精度不同），数值比较必须用compareTo。<br/>3、除法产生无限小数抛ArithmeticException——10÷3必须指定精度和舍入模式：divide(divisor, 2, RoundingMode.HALF_UP)。<br/>4、不可变性——add/subtract/multiply/divide返回新对象，不接收返回值则原值不变。最佳实践：创建用String构造或valueOf、比较用compareTo、除法必指定精度和舍入模式、金额存储建议用Long以分为单位。</p>', 1, 1, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q207. Stream流的惰性求值原理及与集合操作的区别？</p>', '<p>答案解析：Stream操作分为中间操作和终止操作。中间操作（filter/map/sorted/distinct/limit/skip）是惰性的，仅构建操作流水线不立即执行；只有遇到终止操作（collect/forEach/reduce/count/findFirst/anyMatch）时，整个流水线才被触发执行。内部通过Sink接口串联各操作阶段。与集合操作的核心区别：集合是存储数据的容器，Stream是计算数据的管道；集合关注数据存储，Stream关注数据计算；集合大小固定，Stream可无限。常用操作：分组统计`users.stream().collect(groupingBy(User::getGender, counting()))`、List转Map `users.stream().collect(toMap(User::getId, identity(), (k1,k2)->k2))`、扁平化`orders.stream().flatMap(o->o.getTags().stream()).distinct().collect(toList())`。性能注意：简单for循环比Stream快（数据量小时差异明显），操作顺序很关键——先filter再map比先map再filter效率高，因为减少了后续操作的数据量。</p>', 1, 1, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q208. Comparator与Comparable的区别及排序实战？</p>', '<p>答案解析：Comparable是内部比较器（java.lang包），类自身实现compareTo(T o)方法，侵入性强，只能定义一种默认排序规则；Comparator是外部比较器（java.util包），独立实现compare(T o1, T o2)方法，非侵入，可定义多种排序规则灵活组合。返回值约定：负数表示第一个参数排在前面（升序），零表示相等，正数表示第二个参数排在前面（降序）。常用链式排序：`users.sort(Comparator.comparing(User::getAge).thenComparing(User::getName).thenComparing(User::getScore, reverseOrder()))`；null值处理：`Comparator.nullsLast(Comparator.comparing(User::getAge))`将null值排最后。避坑：compareTo中不要直接用return a - b，整数溢出会导致排序错误，用Integer.compare(a, b)。底层排序算法：基本类型数组用DualPivotQuicksort（不稳定），对象数组用TimSort（稳定）。</p>', 1, 1, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q209. Optional类的正确使用姿势与反模式？</p>', '<p>答案解析：Optional是JDK8引入的容器对象，用于包装可能为null的值，强制调用方显式处理空值。正确用法：orElse("默认值")提供兜底、orElseGet(() -> heavyCompute())惰性计算（只有空时才执行）、orElseThrow()空时抛异常、ifPresent()有值才执行、map/flatMap安全转换值。多级判空最经典：`Optional.ofNullable(user).map(User::getAddress).map(Address::getCity).map(City::getName).orElse("未知")`替代多层if嵌套。反模式（禁止）：Optional作为类的字段（序列化问题）、作为方法参数（增加调用方包装成本）、opt.get()前不判断isPresent()、Optional.of(null)直接NPE。设计原则：Optional只用于方法返回值表示"可能为null"的语义，不应滥用。</p>', 1, 1, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q210. try-with-resources原理及AutoCloseable接口的应用？</p>', '<p>答案解析：try-with-resources是JDK7引入的语法糖，编译器会在finally块中自动调用资源的close()方法。资源按声明顺序的逆序关闭（后声明先关闭）。如果业务代码和close()都抛异常，close()的异常会被抑制（suppressed），通过Throwable.getSuppressed()可获取。相比传统try-finally手动关闭，消除了遗漏关闭和异常覆盖的风险。任何实现了AutoCloseable接口的类都可以使用：文件IO（FileInputStream/BufferedReader）、数据库连接（Connection/Statement/ResultSet）、Redis连接、HTTP连接。实战中可将分布式锁包装为AutoCloseable：`try (RedisLock lock = new RedisLock(jedis, "order:123")) { // 业务 } // 自动释放锁`，极大简化资源管理代码。JDK9增强：允许在try()中直接使用已声明的effectively final变量。</p>', 1, 1, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q211. 接口的默认方法和静态方法（JDK8/9）解决了什么问题？</p>', '<p>答案解析：JDK8引入默认方法（default method）的核心动机是向后兼容——当需要在Collection接口中新增stream()方法时，如果是抽象方法，所有实现类（包括用户自定义的）都必须修改，这不可接受。默认方法在接口中提供带方法体的实现，实现类可直接继承或选择性覆写。静态方法允许在接口中定义工具方法，直接通过接口名调用。JDK9进一步引入私有方法，允许将默认方法间的公共代码抽取为private方法避免重复。默认方法冲突解决规则：类优先于接口、子接口优先于父接口、多个不相关接口的同名默认方法必须手动覆写并用`接口名.super.方法名()`指定调用哪个。Spring Data JPA的Repository接口大量使用默认方法提供通用查询逻辑。</p>', 1, 1, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q212. Java四种引用类型（强/软/弱/虚）及实际应用？</p>', '<p>答案解析：强引用（默认）：Object obj = new Object()，即使OOM也不回收。软引用（SoftReference）：内存不足时才被回收，适合做图片缓存——内存充足时缓存图片，内存紧张时自动释放。弱引用（WeakReference）：下次GC必然回收，适合解决内存泄漏的辅助结构——ThreadLocalMap的Entry.key就是弱引用，当外部没有对ThreadLocal的强引用时，key可被GC，防止ThreadLocal内存泄漏。虚引用（PhantomReference）：最弱，get()永远返回null，唯一作用是在对象被GC时收到通知，配合ReferenceQueue使用。NIO中DirectByteBuffer的Cleaner继承PhantomReference，在对象被GC时自动释放堆外内存。使用选择：核心业务对象用强引用、可选缓存用软引用、防泄漏辅助用弱引用、资源回收通知用虚引用。</p>', 1, 1, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q213. Java注解原理、元注解及自定义注解实战？</p>', '<p>答案解析：注解本质是继承Annotation接口的特殊接口，通过@标记在编译期或运行期被解析。四大元注解：@Target指定可用位置（TYPE类、METHOD方法、FIELD字段等）、@Retention指定生命周期（SOURCE源码期丢弃、CLASS字节码保留但运行不可获取、RUNTIME运行时可反射获取）、@Documented包含在Javadoc、@Inherited可被子类继承。自定义注解+AOP切片是典型实战模式：定义@OperateLog(value="", module="")注解标记Controller方法，编写@Aspect切面类配合@Around("@annotation(log)")拦截，通过反射获取注解属性值记录操作日志。常见框架注解：Spring的@Autowired/@Transactional、JUnit的@Test、Lombok的@Data、Jackson的@JsonProperty。RetentionPolicy.RUNTIME是最常用的策略，因为需要在运行时通过反射读取。</p>', 1, 1, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q214. Java IO流体系与装饰器模式的对应关系？</p>', '<p>答案解析：Java IO流体系是装饰器模式的经典实现。基础组件如FileInputStream只提供最基本的字节读取能力，装饰器如BufferedInputStream通过包装基础组件增强功能（添加缓冲）。链式装饰：`new DataInputStream(new BufferedInputStream(new FileInputStream("file.txt")))`，逐层增强——FileInputStream提供字节读取→BufferedInputStream添加缓冲→DataInputStream提供基本类型读取。字符流同样：FileReader→BufferedReader添加readLine()按行读取。装饰器模式相比继承的优势：如果每种功能组合都用继承实现（BufferedFileInputStream、DataFileInputStream、BufferedDataFileInputStream...），会产生类爆炸。装饰器通过组合替代继承，灵活叠加功能。常用装饰器：BufferedInputStream（缓冲）、DataInputStream（基本类型读写）、ObjectInputStream（对象反序列化）、GZIPInputStream（解压缩）、InputStreamReader（字节到字符的桥接转换）。</p>', 1, 1, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q215. JDK动态代理和CGLIB动态代理的区别及底层原理？</p>', '<p>答案解析：JDK动态代理基于接口实现，通过Proxy.newProxyInstance()和InvocationHandler创建代理对象。核心是JVM运行时动态生成$Proxy0.class字节码，该代理类继承Proxy并实现目标接口，在invoke()中通过反射调用目标方法。要求被代理类必须实现接口。CGLIB动态代理基于继承实现，通过Enhancer和MethodInterceptor，底层用ASM框架动态生成目标类的子类字节码，覆写父类非final方法实现代理。无需接口，但不能代理final类和方法。性能对比：CGLIB使用FastClass机制通过索引定位方法（类似直接调用），比JDK反射invoke性能更高。Spring AOP代理选择策略：有接口默认用JDK代理，无接口用CGLIB。SpringBoot 2.x开始默认配置spring.aop.proxy-target-class=true强制使用CGLIB，因为CGLIB在大多数场景下性能更优且不需要接口依赖。</p>', 1, 1, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q216. Object类的equals和hashCode方法的正确重写规则？</p>', '<p>答案解析：equals重写五步法：1、判断this == o（引用相同直接true）；<br/>2、判断o == null || getClass() != o.getClass()（null或类型不同直接false）；<br/>3、强转为目标类型；<br/>4、逐字段比较基本类型用==；<br/>5、引用类型用Objects.equals(name, user.name)防NPE。hashCode重写必须使用与equals相同的字段计算，推荐用Objects.hash(name, age)。核心契约：equals相等的两个对象hashCode必须相等（反之不必然）；重写equals必须重写hashCode，否则HashMap/HashSet会出Bug——两个equals相等的对象因为hashCode不同会存入HashMap的不同槽位。IDEA和Lombok的@Data可自动生成，但需注意Lombok默认生成的equals比较所有字段，对于JPA实体可能引起懒加载问题，需要手动排除代理相关字段。</p>', 1, 1, 0, 0, NULL, CURRENT_TIMESTAMP);-- Part 2: Java集合与数据结构 (tag=2, 17条)
INSERT INTO `t_knowledge` (`question`, `answer`, `status`, `tag`, `del_flag`, `view_count`, `last_view_time`, `add_time`) VALUES
('<p>Q217. HashMap的put方法完整执行流程（源码级）？</p>', '<p>答案解析：JDK1.8 HashMap的put执行流程：1、计算hash值 (h=key.hashCode())^(h>>>16)，混合高低16位让散列更均匀。<br/>2、判断table是否已初始化，未初始化则调用resize()初始化（默认容量16，加载因子0.75，阈值12）。<br/>3、通过(n-1)&hash计算槽位（等价hash%n的位运算优化）。<br/>4、槽位为空则直接放入新节点。<br/>5、槽位不为空时处理哈希冲突：先判断头节点key是否相同（hash相等且==或equals），相同则替换value；判断是否为红黑树节点，是则走putTreeVal；否则遍历链表，找到相同key替换value，找不到则尾插法插入，插入后检查链表长度≥8且数组容量≥64则转为红黑树；若容量<64则优先扩容。<br/>6、最后size++，超过阈值threshold则resize()扩容为2倍。设计要点：容量为2的幂使得(n-1)&hash等价取模且元素迁移只分高低位链表；树化阈值8基于泊松分布（链表≥8概率约千万分之六），本质是防御恶意哈希攻击导致链表退化。</p>', 1, 2, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q218. ConcurrentHashMap在JDK1.7和1.8中如何保证线程安全？</p>', '<p>答案解析：JDK1.7采用分段锁（Segment）机制——默认16个Segment，每个Segment内部是独立的HashEntry数组+ReentrantLock，并发度=Segment数量。put时定位Segment后lock()，扩容只扩容当前Segment。问题：粒度仍较粗，一个Segment内所有操作互斥。JDK1.8彻底重构，取消Segment，改用CAS+synchronized：槽位为空时用CAS自旋插入（零锁竞争）；槽位正在扩容则调用helpTransfer()多线程协同迁移数据；槽位有数据时synchronized只锁该槽位的头节点（不同槽位完全并发）。get()全程无锁，因为Node的val和next被volatile修饰保证可见性。size()使用baseCount+CounterCell数组（类似LongAdder），减少并发计数竞争。JDK1.8的核心进步：锁粒度从Segment缩小到头节点、CAS无锁化、多线程协同扩容、链表→红黑树优化查询。</p>', 1, 2, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q219. HashMap在多线程下会出现什么严重问题？</p>', '<p>答案解析：HashMap不是线程安全的，多线程并发put会导致三大问题：1、数据丢失——多线程同时put到同一槽位时，链表的next指针可能被错误覆盖，导致部分Entry永久丢失。<br/>2、JDK1.7死循环——扩容时使用头插法转移链表，多线程并发扩容可能将链表倒序两次形成环形链表，后续get()遍历时陷入死循环CPU 100%。JDK1.8改用尾插法解决死循环问题，但HashMap整体仍不是线程安全的。<br/>3、数据不一致——size字段的++操作非原子操作，多线程计数错乱。验证代码：两个线程各put 10000条数据到HashMap，用CountDownLatch等待完成后，size()几乎总是小于20000。正确替代方案：ConcurrentHashMap是唯一正确答案；Collections.synchronizedMap全锁性能差；Hashtable已废弃。</p>', 1, 2, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q220. ArrayList和LinkedList的性能差异及底层实现？</p>', '<p>答案解析：ArrayList底层是Object[]动态数组，默认容量10，扩容时增长为原来的1.5倍（oldCapacity + oldCapacity>>1），通过Arrays.copyOf()复制到新数组。get(index)直接数组下标访问O(1)，add到末尾O(1)（摊销），add到中间O(n)因为需要移动后续元素。LinkedList底层是双向链表Node（prev/item/next三个字段），get(index)需要从头/尾遍历O(n)，add到首尾O(1)，add到中间需要先遍历到该位置O(n)。内存占用：ArrayList在数组未满时有预留空间浪费，LinkedList每个元素额外占用两个指针（约24字节）开销。选型原则：查询多、增删少、按索引访问→ArrayList；频繁在首尾增删、遍历多的场景→LinkedList；大多数业务场景ArrayList是更好的默认选择。ArrayList遍历用for-i最快（避免Iterator开销），LinkedList遍历必须用foreach或Iterator（for-i会导致每次O(n)定位）。</p>', 1, 2, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q221. EnumMap和EnumSet的原理和性能优势？</p>', '<p>答案解析：EnumMap是专门为枚举Key设计的Map，内部用数组存储（容量=枚举常量个数），通过key.ordinal()作为数组下标直接存取，O(1)恒定时间，无哈希计算、无碰撞、无扩容。比HashMap快3~5倍。EnumSet是专门为枚举设计的Set，内部用位向量（bit vector）存储——枚举≤64个用单个long的64位表示每个枚举是否存在，超64个用long数组。位运算实现add/remove/contains/allOf/complementOf等操作，比HashSet快10倍以上。使用限制：两者都要求元素是枚举类型；EnumMap允许null value但不允许null key；迭代顺序始终是枚举声明顺序。最佳实践：只要Key是枚举就用EnumMap替代HashMap，只要用Set存枚举必须用EnumSet。Dubbo用EnumMap管理RPC调用状态，MyBatis用EnumSet配置特性开关。性能优势来源：枚举类型编译时确定，用数组/位向量替代哈希表，零开销的存取。</p>', 1, 2, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q222. Arrays.asList返回的List有什么坑？如何正确转换？</p>', '<p>答案解析：Arrays.asList()返回的是Arrays内部类ArrayList（java.util.Arrays$ArrayList），不是java.util.ArrayList。它继承了AbstractList但没有覆写add()和remove()方法，所以add/remove会抛UnsupportedOperationException。该List与原始数组共享同一块内存——修改数组会影响List，反之亦然。最大的坑是基本类型数组：`int[] arr = {1,2,3}; Arrays.asList(arr)`得到size=1的List（整个int[]被当作一个元素），因为Java泛型不支持基本类型。正确转换方式：可变List用`new ArrayList<>(Arrays.asList(arr))`或`Arrays.stream(arr).boxed().collect(toList())`（特别适用于int[]）；不可变List用`List.of(arr)`（JDK9+，null安全）；Guava用`Lists.newArrayList(arr)`。该陷阱在很多项目中造成Bug——从配置文件读取数组后用Arrays.asList然后add，抛异常才发现。</p>', 1, 2, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q223. Collections.unmodifiableList与List.of的区别？</p>', '<p>答案解析：Collections.unmodifiableList()返回的是原始List的只读视图包装（UnmodifiableList），读操作委托给原始List，写操作抛异常。关键缺陷：不是真正不可变——原始List仍可修改，修改后视图也能看到变化，且内部元素如果是可变对象，修改该对象的属性不受限制。JDK9的List.of()返回真正不可变集合：数据完全独立于原始数据、禁止包含null、任何修改操作抛异常、内存更紧凑。其他创建不可变集合方式：Collectors.toUnmodifiableList()（JDK10+，Stream收集）、Guava的ImmutableList（JDK8项目首选，Builder模式支持）。最佳实践：API返回不希望被外部修改的集合时，先防御性拷贝`new ArrayList<>(origin)`再包装或直接用List.copyOf(origin)（JDK10+）；内部使用的常量集合用List.of()，确保不会被意外修改。</p>', 1, 2, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q224. IdentityHashMap和HashMap的核心区别与使用场景？</p>', '<p>答案解析：IdentityHashMap用==（引用比较）判断key是否相等，HashMap用equals()（值比较）。验证示例：两个内容相同的String对象（通过new创建，不在常量池），HashMap会把它们当作同一个key（equals相等），IdentityHashMap会把它们当作不同的key（==不同）。底层实现也不同：IdentityHashMap用Object[]数组，key和value交替存储在数组相邻位置（table[i]=key, table[i+1]=value），不使用链表或红黑树。通过System.identityHashCode()（基于对象内存地址的哈希，不受hashCode()重写影响）计算存储位置。使用场景：序列化框架中追踪已处理的对象（需要对象引用级别去重）、代理对象映射、需要区分对象身份而非对象值的场景。注意事项：IdentityHashMap不完全遵循Map的equals-hashCode契约，是一个"非标准"Map实现，仅用于特定场景。</p>', 1, 2, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q225. Java中栈（Stack）为何不推荐？Deque替代方案？</p>', '<p>答案解析：java.util.Stack继承自Vector，而Vector已过时（所有方法全锁synchronized，性能极差）。更严重的是，继承破坏了栈的封装——可以调用Vector的add(index)/remove(index)等非栈操作在任意位置增删，违背栈LIFO语义。JDK官方文档明确建议用Deque替代。推荐ArrayDeque作栈：push()=addFirst()压栈，pop()=removeFirst()出栈，peek()=peekFirst()查看栈顶。ArrayDeque基于循环数组实现，无Node节点开销，比LinkedList性能更好。ArrayDeque也可以作队列：offer()=addLast()入队，poll()=removeFirst()出队，FIFO先进先出。主要限制：ArrayDeque不允许null元素（LinkedList允许），因为null被用作poll/peek返回空时的标记值。线程安全场景用ConcurrentLinkedDeque（无锁CAS实现）或LinkedBlockingDeque（阻塞实现）。</p>', 1, 2, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q226. PriorityQueue堆排序原理与TopK问题实现？</p>', '<p>答案解析：PriorityQueue底层是二叉堆（默认小顶堆），用Object[]数组存储，父子节点通过下标关系定位（父(i-1)/2、左子2i+1、右子2i+2）。入队offer()和出队poll()都是O(log n)，堆顶peek()是O(1)。TopK问题的最优解——用一个大小为k的堆实现O(n log k)复杂度，比全排序O(n log n)更优。找最大的k个数用小顶堆（堆顶是k个中最小即"阈值"），遍历新元素时大于堆顶则替换；找最小的k个数用大顶堆（堆顶是k个中最大）。关键技巧：`PriorityQueue<Integer> heap = new PriorityQueue<>(k); for (int num : nums) { heap.offer(num); if (heap.size() > k) heap.poll(); }`——最终堆中保留了最大的k个无序。注意事项：PriorityQueue非线程安全（并发用PriorityBlockingQueue），迭代器iterator()不保证顺序（必须poll()才能按优先级取），不能存null元素（poll()返回null表示队列空的标记）。</p>', 1, 2, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q227. CopyOnWriteArrayList的读写分离原理与适用场景？</p>', '<p>答案解析：COWList实现读写分离的核心是"写时复制"机制。读操作（get/iterator/size）完全无锁，直接访问当前数组。写操作（add/set/remove）先加ReentrantLock，然后复制整个数组副本（Arrays.copyOf），在副本上完成修改，最后将内部数组引用指向新数组。优点：读并发极高（无锁），遍历过程中修改数据不会抛ConcurrentModificationException（迭代器持有的是旧数组快照）。缺点：写操作需要复制整个数组——数据量越大、写越频繁成本越高；内存开销大（写时同时存在新旧两份数组）；读到的是弱一致性数据（写操作完成前的读看不到新数据）。适用场景：读多写少，如白名单、黑名单、配置信息等基本不会变的数据。不适用：写操作频繁的大数据量列表。与Collections.synchronizedList对比——syncList读写都加锁强一致性，COW读无锁弱一致性。</p>', 1, 2, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q228. LinkedHashMap实现LRU缓存的具体原理？</p>', '<p>答案解析：LinkedHashMap继承HashMap，内部额外维护一个双向链表记录entry的插入顺序或访问顺序。构造函数中accessOrder参数决定模式：false（默认）按插入顺序排序，true按访问顺序排序（get/put操作会把该entry移到链表末尾）。LRU缓存实现：继承LinkedHashMap并重写removeEldestEntry()方法，该方法在每次put后调用，返回true则删除链表头部（最老）的entry。示例：`new LinkedHashMap<String,Integer>(16,0.75f,true){ protected boolean removeEldestEntry(Entry e){ return size()>3; }}`，当size超过3时，每次put会自动淘汰最久未被访问的entry，get操作会把访问的entry移到末尾（变为最新）。实际项目中用于本地缓存有限数量的热点数据。注意：这是简化版LRU，未考虑过期时间；生产级LRU缓存推荐用Caffeine或Guava Cache，它们提供过期策略、容量控制、统计监控等完整功能。</p>', 1, 2, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q229. HashMap的hash()函数为何要高16位和低16位做异或？</p>', '<p>答案解析：源码 `(h = key.hashCode()) ^ (h >>> 16)`。定位槽位用的是(n-1)&hash，当HashMap容量较小（如默认16，n-1=15即0b00001111），只有hash的低4位参与槽位计算，高位完全被屏蔽。如果直接使用hashCode()的低位，不同对象可能恰好低位相同而高位不同，造成严重哈希碰撞。扰动函数将高16位的特征通过异或运算传播到低16位，让高位信息也参与定位计算，使散列分布更加均匀。JDK7做了4次移位+异或（更复杂），JDK8简化为1次——因为JDK8引入了红黑树，即使哈希碰撞导致链表变长也能通过树化保证查询效率，所以简化扰动函数换取计算速度。key为null时hash直接返回0，存储在table[0]位置，这也是HashMap允许null key的原因。</p>', 1, 2, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q230. WeakHashMap的原理、使用场景及注意事项？</p>', '<p>答案解析：WeakHashMap的Entry的key被WeakReference包装，当key对象不再被其他强引用引用时，GC自动回收key，对应的Entry在后续的get/put/size操作中通过expungeStaleEntries()自动清除（检查ReferenceQueue中已被GC的弱引用）。与HashMap的对比验证：HashMap的key就算外部设为null，Map内部强引用仍然阻止GC；WeakHashMap的key外部无强引用时可被GC。使用场景：ThreadLocal的ThreadLocalMap——Entry的key（ThreadLocal）用弱引用，当ThreadLocal没有再被外部引用时可以回收，防止内存泄漏。监听器注册表——观察者被GC后自动从注册表移除。注意事项：不要用String字面量做key（常量池有强引用，永远不会被回收）；WeakHashMap非线程安全；value持有强引用会自动跟着key释放（key回收后value的强引用也断了）；整个机制依赖GC时机，不是即时的。</p>', 1, 2, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q231. TreeMap的底层红黑树与HashMap的对比？</p>', '<p>答案解析：TreeMap底层是红黑树（自平衡二叉搜索树），所有key自动按照Comparable自然顺序或Comparator指定顺序排序。增删查时间复杂度O(log n)，而HashMap的O(1)是平均值（最坏退化到O(n)）。TreeMap特有功能：范围查询——subMap(from, to)获取子Map、headMap(to)获取头部、tailMap(from)获取尾部；邻近查找——ceilingKey(k)≥k的最小key、floorKey(k)≤k的最大key、higherKey(k)>k的最小key、lowerKey(k)<k的最大key；极值——firstKey()/lastKey()获取最小/最大key。HashMap优势：O(1)存取，适合绝大多数查询场景。选型：需要范围查询、排名、有序遍历、找前后邻近元素→TreeMap；一般键值存取→HashMap；需要保持插入顺序→LinkedHashMap。TreeMap不允许null key（因为需要比较），HashMap允许一个null key。实际项目中统计报表按时间段排序、价格区间匹配、排名功能都适合用TreeMap。</p>', 1, 2, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q232. Java中BitSet的原理及高性能场景？</p>', '<p>答案解析：BitSet用long数组按位存储true/false，每个long存64位，通过位运算实现set/get/and/or/xor/cardinality（统计true位数）等操作。内存节省：存储10亿个布尔值用BitSet只需约125MB，用boolean[]需要1000MB。核心操作：set(from, to)将连续范围置为true、get(i)获取第i位、cardinality()统计true总数、and/or/xor实现交集/并集/对称差集。典型场景：1、用户签到统计——365天签到记录仅需约46字节；<br/>2、海量数据去重——ID范围明确时比HashSet省内存几十倍；<br/>3、布隆过滤器底层位数组；<br/>4、权限掩码——每个权限对应一个bit，用位或合并权限，用位与判断权限。Redis的BitMap（SETBIT/GETBIT/BITCOUNT命令）是同样的思想，适合二值状态大数据量统计。限制：只能存boolean值，不支持对象；需要预先知道数据范围。</p>', 1, 2, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q233. Java中BlockingQueue的生产者-消费者实现及选型？</p>', '<p>答案解析：BlockingQueue是生产者-消费者模式的基础组件，线程安全、支持阻塞操作。put(e)队列满时阻塞生产者直到有空间；take()队列空时阻塞消费者直到有元素；offer(e, time, unit)和poll(time, unit)支持超时机制。实现类选型：ArrayBlockingQueue——数组有界，一把锁控制put和take（锁竞争严重），适合固定容量小型缓冲区；LinkedBlockingQueue——链表可指定容量（不指定则Integer.MAX_VALUE近似无界），putLock和takeLock两把锁分离，吞吐量更高，是线程池（FixedThreadPool等）的默认队列；SynchronousQueue——无存储空间，生产者必须等待消费者取走，用于CachedThreadPool实现来者不拒创建线程；DelayQueue——元素需实现Delayed接口，到期后才能取出，用于订单超时取消、延时任务调度。线程池最佳实践：始终使用有界队列+合理拒绝策略，避免LinkedBlockingQueue的无界默认值导致OOM。</p>', 1, 2, 0, 0, NULL, CURRENT_TIMESTAMP);-- Part 3: Java多线程与JUC深入 (tag=3, 20条)
INSERT INTO `t_knowledge` (`question`, `answer`, `status`, `tag`, `del_flag`, `view_count`, `last_view_time`, `add_time`) VALUES
('<p>Q234. 线程池核心参数及任务执行流程？自定义线程池如何合理配置参数？</p>', '<p>答案解析：ThreadPoolExecutor七大参数：corePoolSize核心线程数、maximumPoolSize最大线程数、keepAliveTime空闲非核心线程存活时间、unit时间单位、workQueue阻塞任务队列、threadFactory线程工厂、handler拒绝策略。任务执行流程：提交任务→核心线程有空则执行→核心线程满了进队列排队→队列满了创建非核心线程→达到最大线程数触发拒绝策略。参数配置原则：CPU密集型任务corePoolSize=CPU核数+1；IO密集型任务corePoolSize=CPU核数×2（阻塞等待时不占CPU）；混合型需压测确定。队列选择：用有界ArrayBlockingQueue（默认LinkedBlockingQueue无界会导致OOM）。生产最佳实践：必须通过new ThreadPoolExecutor()手动创建，严禁用Executors工具类。</p>', 1, 3, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q235. 为什么阿里规约禁止使用Executors创建线程池？</p>', '<p>答案解析：Executors创建的线程池存在严重隐患。newFixedThreadPool和newSingleThreadExecutor使用的LinkedBlockingQueue默认容量是Integer.MAX_VALUE（约21亿），任务堆积会导致OOM内存溢出。newCachedThreadPool的maximumPoolSize设为Integer.MAX_VALUE，允许创建无限数量的线程，高并发下线程爆炸导致CPU占满甚至系统崩溃。newScheduledThreadPool同样使用无界队列。正确做法是手动通过ThreadPoolExecutor构造器创建：明确指定核心线程数、最大线程数、有界队列（如ArrayBlockingQueue(100)）、合理的拒绝策略。例如高并发订单处理线程池：`new ThreadPoolExecutor(10, 20, 60L, TimeUnit.SECONDS, new ArrayBlockingQueue<>(200), new NamedThreadFactory("order"), new ThreadPoolExecutor.CallerRunsPolicy())`，其中CallerRunsPolicy让调用者线程执行任务，既不会丢任务也不会OOM。</p>', 1, 3, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q236. 线程池四种拒绝策略的区别和适用场景？</p>', '<p>答案解析：1、AbortPolicy（默认）：直接抛出RejectedExecutionException，阻止系统正常运行，适合必须成功不能丢的任务；<br/>2、CallerRunsPolicy：由提交任务的调用者线程来执行，既不会丢任务也不会OOM，缺点是可能阻塞主线程或降低提交速度，适合不能丢任务但对延迟不太敏感的场景；<br/>3、DiscardPolicy：静默丢弃新任务，不抛异常，适合允许丢失的非关键任务（如埋点日志）；<br/>4、DiscardOldestPolicy：丢弃队列中最老的未处理任务，然后重试提交，适合"新任务比老任务重要"的场景（如实时数据优先于历史数据）。实际项目中最常用CallerRunsPolicy——任务不会丢失，由调用者线程慢慢消化，配合监控告警。也可自定义拒绝策略将任务持久化到数据库或MQ后续补偿处理，保证任务最终被执行。</p>', 1, 3, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q237. synchronized锁升级的完整过程是怎样的？</p>', '<p>答案解析：synchronized的锁状态记录在Java对象头的MarkWord中，锁升级过程不可逆。1、无锁状态：对象刚创建，MarkWord存储hashCode和分代年龄。<br/>2、偏向锁：当只有一个线程访问同步块时，MarkWord记录该线程ID，后续该线程进入无需CAS操作，只检查线程ID是否匹配。偏向锁延迟生效（JVM启动后约4秒才开启），可通过-XX:-UseBiasedLocking关闭。<br/>3、轻量级锁：当有其他线程尝试获取偏向锁时，偏向锁撤销升级为轻量级锁。获取锁的线程在栈帧中创建LockRecord，通过CAS将MarkWord替换为指向LockRecord的指针。未获取到锁的线程自旋等待（自适应自旋），不阻塞。<br/>4、重量级锁：自旋超过一定次数（默认10次）或自旋线程数超过CPU核数一半时，升级为重量级锁，未获取锁的线程阻塞进入等待队列，由操作系统调度。锁升级的核心思想是：大多数情况下锁竞争不激烈，用轻量级手段（偏向/自旋）即可，只有真正激烈时才动用重量级阻塞。</p>', 1, 3, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q238. synchronized和ReentrantLock的核心区别及如何选型？</p>', '<p>答案解析：五大核心区别：1、锁的获取与释放——synchronized由JVM自动管理（进入同步块加锁，退出同步块释放，异常也自动释放），ReentrantLock需要手动lock()和unlock()，必须放在finally中确保释放。<br/>2、可中断性——synchronized阻塞时不可中断，ReentrantLock的lockInterruptibly()支持中断响应。<br/>3、超时机制——synchronized无超时，ReentrantLock的tryLock(time, unit)支持尝试获取锁一段时间。<br/>4、公平性——synchronized非公平，ReentrantLock可指定公平锁（new ReentrantLock(true)），公平锁按等待队列顺序获取。<br/>5、条件唤醒——ReentrantLock可通过newCondition()创建多个Condition精确唤醒特定线程，synchronized只有一个等待队列，只能随机唤醒。选型：简单场景用synchronized（JDK6后性能差距已很小），需要中断/超时/公平/多条件唤醒等高级特性时用ReentrantLock。实际项目中90%场景synchronized足够。</p>', 1, 3, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q239. volatile的可见性和有序性是如何保证的？为什么不保证原子性？</p>', '<p>答案解析：volatile通过JMM的两个规则保证可见性和有序性：1、写volatile变量时，JVM强制将线程本地工作内存的值刷新到主内存。<br/>2、读volatile变量时，JVM强制线程从主内存重新读取，使本地工作内存的值失效。底层通过CPU的内存屏障指令实现：StoreStoreBarrier→volatile写→StoreLoadBarrier（禁止写与后续读写重排序）；volatile读→LoadLoadBarrier+LoadStoreBarrier（禁止后续读写与volatile读重排序）。不保证原子性的原因：i++是三个操作（读、增、写），volatile只保证每次读的值是最新的，不能保证读之后到写之前其他线程不修改。比如线程A读到i=0要自增时，线程B可能同时读到i=0也自增，两个线程各自写回i=1，丢失了一次自增。解决方案：简单计数器用AtomicInteger的incrementAndGet()（CAS实现真原子性）。</p>', 1, 3, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q240. CAS是什么？ABA问题如何产生和解决？</p>', '<p>答案解析：CAS（Compare And Swap，比较并交换）是无锁乐观锁的核心操作，由CPU的cmpxchg指令硬件支持。操作逻辑：比较内存当前值V与预期值E，相等则更新为新值N，返回true；不相等说明被其他线程修改了，返回false，调用方通常循环重试直到成功。优点：无锁阻塞、不会线程切换、并发效率高。缺点：自旋循环空耗CPU（高竞争场景反而不如锁）、只能保证单个变量原子性、ABA问题。ABA问题：线程1将值从A改为B再改回A，线程2的CAS看到值还是A认为没变化，但实际上中间经历过B状态。对于基本数据类型（如递增计数）无所谓，但对于引用类型（如链表头指针）可能导致逻辑错误。解决方案：加版本号——AtomicStampedReference同时维护引用和版本号stamp，CAS时同时比较引用和版本号，即使引用值相同但版本号不同也认为被修改过。</p>', 1, 3, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q241. ThreadLocal的原理、应用场景及内存泄漏原因？</p>', '<p>答案解析：每个Thread对象内部维护一个ThreadLocalMap（类似定制HashMap），key是ThreadLocal对象的弱引用，value是线程私有的数据副本。set(T value)时以当前线程为入口获取ThreadLocalMap，以ThreadLocal对象为key存储value；get()同理。这样不同线程访问同一个ThreadLocal对象时，实际访问的是各自线程内部的数据副本，天然线程隔离。典型场景：Spring的@Transactional用ThreadLocal存储当前事务的数据库连接（保证同一事务使用同一连接）、Web开发中的RequestContextHolder用ThreadLocal存储当前请求的HttpServletRequest、日志框架的MDC用ThreadLocal存储链路追踪traceId。内存泄漏原因：ThreadLocalMap的Entry的key是WeakReference<ThreadLocal>，当ThreadLocal没有外部强引用时，key被GC回收变为null，但value还是强引用（Entry->value），只要线程不销毁（线程池线程可存活很久），value永远无法释放。解决方案：使用完后必须调用ThreadLocal.remove()手动清除。阿里规约明确要求：ThreadLocal使用完后必须在finally中remove()。</p>', 1, 3, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q242. 死锁的四个必要条件及如何预防和排查？</p>', '<p>答案解析：四个必要条件缺一不可：1、互斥条件——资源某一时刻只能被一个线程占用。<br/>2、请求与保持——线程已持有资源的同时请求新资源，不释放已有资源。<br/>3、不可剥夺——线程持有的资源不能被强制抢夺。<br/>4、循环等待——线程之间形成头尾相接的循环资源等待链。预防方案（破坏任一条件即可）：破坏请求与保持——一次性申请所有需要的资源；破坏不可剥夺——获取不到资源时主动释放已持有资源；破坏循环等待——统一资源获取顺序（最简单可行，如所有线程都按lock1→lock2的顺序加锁）。排查手段：jstack pid导出线程堆栈，查找"deadlock"或"waiting to lock"关键字，会明确列出死锁的线程和锁。编码规范：避免嵌套锁、设置锁超时时间（ReentrantLock.tryLock(timeout)）、使用try-finally确保锁一定释放。</p>', 1, 3, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q243. CountDownLatch、CyclicBarrier、Semaphore的区别？</p>', '<p>答案解析：三者纵览——CountDownLatch：倒计数门闩，主线程await()等待，子线程完成任务后countDown()递减计数，减到0后释放所有等待线程，一次性使用不可重置。典型场景：主线程等待多个子线程并行加载数据完成后组装结果。CyclicBarrier：循环栅栏，所有线程互相等待，到达栅栏数量后一起释放继续执行，可重复使用。典型场景：多线程分片处理大数据，每个线程处理自己分片后到达barrier等待，所有线程完成后合并结果进入下一阶段。Semaphore：信号量，维护permits许可数，acquire()获取许可（计数减1），release()释放许可（计数加1），许可不足时阻塞。典型场景：数据库连接池限制、接口限流（限制同时处理请求的线程数）。三者核心区别：CountDownLatch是"等待他人"、CyclicBarrier是"互相等待"、Semaphore是"资源控制"。</p>', 1, 3, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q244. sleep()和wait()的本质区别？</p>', '<p>答案解析：六点核心区别：1、所属类——sleep是Thread类的静态方法，wait是Object类的实例方法。<br/>2、锁释放——sleep不会释放持有的锁（抱着锁睡），wait会释放持有的锁（暂时交出锁）。<br/>3、使用位置——sleep任何地方都可调用，wait必须在synchronized同步块中调用（否则抛IllegalMonitorStateException）。<br/>4、唤醒方式——sleep到时自动醒来或被interrupt，wait需被notify/notifyAll唤醒或超时自动醒来。<br/>5、线程状态——sleep进入TIMED_WAITING超时等待状态，wait进入WAITING等待状态。<br/>6、用途——sleep用于让线程暂停执行一段时间，wait用于线程间通信协调。典型场景：生产者-消费者中消费者调用wait()释放锁等待数据，生产者生产后notify唤醒消费者；sleep仅用于简单延时或限速。</p>', 1, 3, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q245. notify()和notifyAll()的区别及使用建议？</p>', '<p>答案解析：notify()随机唤醒一个在该对象监视器上等待的线程，notifyAll()唤醒所有等待线程。如果用notify()只唤醒一个线程，万一被唤醒的不是应该继续执行的线程（如消费者唤醒了另一个消费者而非生产者），而生产者仍在等待，可能导致所有线程陷入永久等待（信号丢失问题）。notifyAll()唤醒所有线程后，正确的线程获取锁继续执行，不正确的线程再次检查条件后重新wait()。虽然notifyAll()开销更大（所有线程被唤醒竞争锁），但保证了正确性。最佳实践：除非明确知道只有一个等待线程且确定它一定能执行（如一次性任务），否则始终用notifyAll()。实际上，现代并发编程很少直接使用wait/notify/notifyAll，推荐用JUC的高级工具如Condition、CountDownLatch、BlockingQueue代替，更安全且代码更清晰。</p>', 1, 3, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q246. 乐观锁与悲观锁的区别？数据库和代码层面如何实现？</p>', '<p>答案解析：悲观锁：假定并发冲突一定会发生，操作数据前先加锁阻塞其他访问。数据库实现：`SELECT ... FOR UPDATE`行锁（必须在事务中，否则锁不生效），InnoDB行锁基于索引，无索引会升级为表锁。代码实现：synchronized、ReentrantLock。适合冲突多、写入频繁的场景。乐观锁：假定并发冲突不会发生，操作时不加锁，更新时检查数据是否被其他事务修改。数据库实现：version版本号字段+UPDATE时校验version（`UPDATE ... SET version=version+1 WHERE version=原version`），影响行数为0说明被修改过需重试。代码实现：CAS（AtomicInteger等）。适合读多写少、冲突概率低的场景，避免锁竞争提升并发能力。选择策略：冲突概率低（<20%）用乐观锁，冲突概率高用悲观锁，不确定时用乐观锁先试。</p>', 1, 3, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q247. 多线程中指令重排序是什么？Java如何禁止？</p>', '<p>答案解析：指令重排序是CPU和编译器为了提升执行效率打乱代码执行顺序的优化手段，在单线程中保证最终结果不变（遵循as-if-serial语义），但多线程环境下会出现意想不到的问题。经典案例——双重校验锁单例：instance = new Singleton()不是原子操作（分配内存→初始化对象→赋值引用），如果重排序为分配内存→赋值引用→初始化对象，另一个线程在第一个线程赋值引用后但初始化前访问instance，会拿到未初始化的对象。解决方案：1、volatile禁止指令重排序——volatile变量的读写会插入内存屏障，保证它之前的操作不会重排到它之后，它之后的操作不会重排到它之前；<br/>2、synchronized——同步块内的操作在单线程中串行执行，退出同步块时刷新到主内存对后续线程可见；<br/>3、final——final字段的写入保证在构造器完成之前完成，不会重排到构造器之外。</p>', 1, 3, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q248. Java内存模型（JMM）中的可见性、原子性、有序性？</p>', '<p>答案解析：JMM是Java并发编程的底层规范，定义了线程与主内存之间的抽象关系。可见性：一个线程对共享变量的修改，其他线程能否立即看到。volatile保证可见性——写volatile变量强制刷新到主内存，读volatile变量强制从主内存重新读取。synchronized和Lock的unlock也会刷新。原子性：一个操作不可分割、不可被中断。synchronized代码块保证原子性，volatile不保证（i++不是原子的）。JUC原子类（AtomicInteger）通过CAS保证原子性。有序性：程序执行的顺序按照代码先后。volatile禁止指令重排序、synchronized保证块内代码串行执行（块间可重排）、happens-before原则定义操作间的偏序关系（锁释放happens-before锁获取、volatile写happens-before volaile读、线程start() happen-before线程内所有操作）。理解JMM是使用volatile、synchronized、Lock、原子类的基础。</p>', 1, 3, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q249. 线程池的核心线程和最大线程的区别？线程如何存活和回收？</p>', '<p>答案解析：核心线程（corePoolSize）：线程池维护的最小线程数，即使这些线程空闲也不会被回收（除非allowCoreThreadTimeOut设置为true）。最大线程（maximumPoolSize）：线程池允许创建的最大线程数。两者之间的差额是"非核心线程"。线程创建时机：任务来了→核心线程有空闲则分配→核心线程忙且队列满才创建非核心线程→达到max则拒绝。线程回收：非核心线程在空闲时间超过keepAliveTime后被销毁；核心线程默认永不被销毁（但设置allowCoreThreadTimeOut(true)可让核心线程在空闲超时后也被回收）。配置建议：CPU密集型任务核心线程=最大线程=CPU核数+1（避免线程切换开销）；IO密集型任务核心线程数较小、最大线程数较大（阻塞等待时不占CPU）；核心线程一般保持常驻避免频繁创建销毁开销。</p>', 1, 3, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q250. Future模式是什么？CompletableFuture解决了什么问题？</p>', '<p>答案解析：Future是JDK5引入的异步计算结果容器——提交任务后立即返回Future，后续通过get()阻塞获取结果。核心问题：get()是阻塞的，多个Future之间无法组合（不能等A完成后执行B）、无法异步回调（不能完成后自动通知）、没有异常处理机制。CompletableFuture（JDK8）彻底解决了这些痛点：1、supplyAsync()异步执行有返回值的任务；<br/>2、thenApply/thenAccept/thenRun系列方法实现任务链式串联（前一个完成后自动执行下一个）；<br/>3、thenCombine/allOf/anyOf组合多个异步任务的结果；<br/>4、exceptionally/handle处理异常；<br/>5、回调异步不阻塞主线程。示例：`CompletableFuture.supplyAsync(()->查商品).thenApply(商品->算价格).thenAccept(价格->返回结果).exceptionally(e->兜底)`。实际项目中的并行查询优化——同时调用三个服务，用allOf等待全部完成再合并结果，将串行500ms优化到并行200ms。</p>', 1, 3, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q251. Fork/Join框架的设计思想和适用场景？</p>', '<p>答案解析：Fork/Join是JDK7引入的并行计算框架，核心思想是"分而治之"——将大任务递归拆分为足够小的子任务（fork），子任务并行执行后合并结果（join）。核心组件：ForkJoinPool（共享线程池，默认线程数=CPU核数）、ForkJoinTask（RecursiveTask有返回值，RecursiveAction无返回值）。核心优化——工作窃取算法：每个线程维护自己的双端任务队列（LIFO取自己任务），当自己队列空时就随机从其他线程队列的尾部偷取任务（FIFO），最大化线程利用率，减少空闲等待。适用场景：CPU密集型的大数据量计算，如数组排序、大文件处理、树结构遍历等可递归分解的任务。不适用：IO密集型任务（阻塞浪费线程）、任务粒度太小（fork/join开销大于计算本身）。JDK8的parallelStream底层就是ForkJoinPool，所有并行流共享同一个commonPool（共n-1个线程）。</p>', 1, 3, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q252. AQS（AbstractQueuedSynchronizer）的设计思想和核心原理？</p>', '<p>答案解析：AQS是JUC包下几乎所有同步工具（ReentrantLock、CountDownLatch、Semaphore、ReentrantReadWriteLock）的底层实现框架。核心思想：用一个volatile int的state变量表示同步状态，配合CLH变体队列（双向链表）管理等待线程。获取锁失败时，线程被包装为Node节点加入队列尾部，通过CAS+自旋尝试获取。当state变为可用时，队列头部节点出队获取锁。模板方法设计：AQS定义acquire()/release()/tryAcquire()/tryRelease()等方法骨架，子类只需重写tryAcquire/tryRelease实现自己的获取释放逻辑（独占或共享模式）。ReentrantLock实现独占模式——state=0表示未锁定，state>0表示锁定次数（可重入）；CountDownLatch实现共享模式——state=倒数值，countDown()递减，为0时释放所有等待者；Semaphore也是共享模式——state=剩余许可数。深入理解AQS是掌握并发编程的钥匙——所有JUC同步工具本质上都是对AQS state操作的不同实现。</p>', 1, 3, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q253. ReentrantReadWriteLock读写锁的原理和锁降级？</p>', '<p>答案解析：读写锁将锁分为读锁（共享锁）和写锁（排他锁），实现读读不互斥、读写互斥、写写互斥。读锁：多个线程可同时持有读锁（state高16位=读锁计数）。写锁：同一时刻只有一个线程持有写锁（state低16位=写锁重入次数）。获取写锁前需等所有读锁释放，获取读锁前需等写锁释放（防止读到写了一半的脏数据）。适用场景：读多写少（如配置缓存），读操作可完全并发，大幅提升吞吐量。锁降级：持有写锁的线程可以获取读锁，然后释放写锁，降级为只持有读锁（写→读），数据一致性要求先获取读锁再释放写锁。锁升级（读→写）不允许，因为多个读锁同时尝试升级会造成死锁。StampedLock（JDK8）是读写锁的优化版本——提供乐观读模式（读时不加锁+版本戳校验），性能更高但使用更复杂。</p>', 1, 3, 0, 0, NULL, CURRENT_TIMESTAMP);-- Part 4: JVM与性能调优 (tag=4, 19条)
INSERT INTO `t_knowledge` (`question`, `answer`, `status`, `tag`, `del_flag`, `view_count`, `last_view_time`, `add_time`) VALUES
('<p>Q254. JVM运行时数据区的详细划分及各区域作用？</p>', '<p>答案解析：JVM内存分为两大块：线程私有区和线程共享区。线程私有区（随线程生灭）：程序计数器——记录当前线程执行的字节码行号，唯一不会OutOfMemoryError的区域，分支、循环、跳转都依赖它。虚拟机栈——每个方法执行时创建栈帧（存储局部变量表、操作数栈、动态链接、方法出口），栈深度超过限制抛StackOverflowError（如递归死循环），无法申请到内存抛OOM。本地方法栈——为Native方法服务，HotSpot中与虚拟机栈合二为一。线程共享区（全局）：堆内存——存放对象实例和数组，GC回收的主要区域，分新生代（Eden+两个Survivor）和老年代。方法区（元空间）——JDK8后用本地内存中的元空间替代永久代，存储类的元信息、运行时常量池、静态变量、JIT编译的代码缓存。直接内存——NIO的ByteBuffer分配的堆外内存，不受GC管理但有大小限制。</p>', 1, 4, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q255. JVM判断对象是否可回收的两种方法及哪种是主流？</p>', '<p>答案解析：1、引用计数法：每个对象维护一个引用计数器，被引用+1，引用失效-1，计数为0即可回收。优点：实时性高，实现简单。致命缺点：无法解决循环引用问题（两个对象互相引用但外部已不可达，引用计数永远为1永远不会被回收）。Python使用引用计数为主、标记清除为辅的方案。<br/>2、可达性分析法（Java/C#主流）：以GC Roots对象集合为起点，从这些节点向下搜索，搜索走过的路径称为引用链。如果一个对象到任何GC Roots都没有引用链相连，则判定为不可达、可回收。GC Roots包括：虚拟机栈（栈帧中本地变量表）引用的对象、方法区中静态属性/常量引用的对象、本地方法栈中JNI引用的对象、活跃线程对象、被系统类加载器加载的类对象。可达性分析能解决循环引用问题，但需要Stop-The-World暂停所有用户线程，保证分析期间引用关系不变（这个过程叫"根节点枚举"）。</p>', 1, 4, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q256. 强、软、弱、虚四种引用在GC时的回收规则？</p>', '<p>答案解析：强引用（默认）：任何情况下都不会被回收，即使OOM。要想回收必须将引用显式设置为null。强引用是造成内存泄漏的常见原因（集合中存储了大量不再使用的对象但引用还在）。软引用（SoftReference）：内存空间足够时不被回收，只有在将要发生OOM时，JVM会尝试回收软引用指向的对象。适合做内存敏感的缓存——内存够就用缓存，不够就自动释放。弱引用（WeakReference）：下一次GC时必被回收，不管内存是否足够。WeakHashMap的Entry key用弱引用，ThreadLocal的key也用弱引用。虚引用（PhantomReference）：最弱的引用，无法通过get()获取对象实例，唯一作用是在对象被GC回收时收到一个系统通知，常用于NIO的Cleaner管理直接内存释放。软引用和弱引用都可以配合ReferenceQueue使用——对象在被回收时会被加入ReferenceQueue，可以在代码中处理后续清理工作。</p>', 1, 4, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q257. Minor GC、Major GC、Full GC的区别与触发条件？</p>', '<p>答案解析：Minor GC（Young GC）：只回收新生代，当Eden区满时触发。特点：频率高（对象大多朝生夕死）、速度快、STW时间短（毫秒级）、使用复制算法。大对象（-XX:PretenureSizeThreshold指定阈值）直接进入老年代，避免在新生代来回复制。Major GC（Old GC）：回收老年代，通常与Minor GC一起触发（CMS收集器老年代单独回收是特例）。速度比Minor GC慢10倍以上，STW时间长。Full GC：整堆回收（新生代+老年代+元空间），是所有GC中STW最长、对性能影响最大的。触发条件：①调用System.gc()（建议但不保证执行）；<br/>②老年代空间不足；<br/>③元空间空间不足；<br/>④Minor GC后平均晋升老年代大小>老年代剩余空间；<br/>⑤CMS的Concurrent Mode Failure。生产环境应尽一切可能避免Full GC——通过合理分配堆大小、减少大对象、优化代码减少对象创建。</p>', 1, 4, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q258. CMS垃圾收集器的工作流程、优缺点和适用场景？</p>', '<p>答案解析：CMS（Concurrent Mark Sweep）目标是"最短回收停顿时间"，适合对响应时间要求高的B/S系统。四阶段流程：1、初始标记（STW很短）——标记GC Roots能直接关联到的对象。<br/>2、并发标记（与用户线程并发）——从GC Roots开始做可达性分析，耗时最长但不STW。<br/>3、重新标记（STW较长但比初始标记短）——修正并发标记期间因用户线程运行而变化的标记。<br/>4、并发清除（与用户线程并发）——清理垃圾对象。三个致命缺点：①产生内存碎片——标记-清除算法不整理内存，长时间运行后碎片严重，可能提前触发FullGC；<br/>②浮动垃圾——并发清除时用户线程产生的新垃圾本次无法清理，留待下次GC；<br/>③对CPU资源敏感——并发阶段占用CPU线程，降低用户线程吞吐量。JDK14中CMS已被移除，建议用G1或ZGC替代。</p>', 1, 4, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q259. G1垃圾收集器相比CMS的核心改进是什么？</p>', '<p>答案解析：G1（Garbage First）将整个堆划分为多个大小相等的Region（默认约2048个，每个1~32MB），彻底改变了CMS的连续分代布局。G1的核心改进：1、无内存碎片——采用"标记-整理+复制"算法，回收时把存活对象复制到其他Region然后整体清理当前Region，不产生碎片（CMS最大痛点）。<br/>2、可预测的停顿——用户可以指定期望停顿时间（-XX:MaxGCPauseMillis），G1会优先回收垃圾最多的Region（Garbage First名字由来），在预期时间内完成最有价值的回收。<br/>3、混合回收（Mixed GC）——不仅回收新生代也扫描部分老年代Region，比CMS的全量老年代回收更灵活。<br/>4、写屏障+SATB（Snapshot At The Beginning）解决并发标记期间对象变化问题，比CMS的增量更新方案更高效。G1已成为JDK9~JDK16的默认垃圾收集器。适合堆内存4GB~64GB、要求低延迟的场景。</p>', 1, 4, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q260. JVM类加载过程分几个阶段？每个阶段做什么？</p>', '<p>答案解析：类加载分为五个阶段：1、加载——通过类的全限定名获取定义此类的二进制字节流（可从class文件、jar包、网络、动态生成等来源），将字节流转化为方法区的运行时数据结构，在堆中生成java.lang.Class对象作为入口。<br/>2、验证——确保Class文件字节流符合JVM规范，包括文件格式验证、元数据验证（是否有父类、是否继承了final类等）、字节码验证（方法体代码合法）、符号引用验证。<br/>3、准备——为类变量（static变量）分配内存并设置默认初始值（int=0, boolean=false, 引用=null），注意这里是零值而非赋值表达式指定的值。但static final常量在此阶段直接赋值为ConstantValue属性指定的值。<br/>4、解析——将常量池中的符号引用（"com.xxx.User"字符串）替换为直接引用（内存地址或偏移量）。<br/>5、初始化——执行类构造器<clinit>()方法，包含static变量赋值和static代码块，按父类→子类的顺序执行。</p>', 1, 4, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q261. 双亲委派模型的工作原理、作用和如何打破？</p>', '<p>答案解析：双亲委派模型规定：类加载器在收到类加载请求时，不会自己先尝试加载，而是将请求委托给父类加载器，层层向上直到顶层的启动类加载器（Bootstrap ClassLoader）。只有当父加载器无法加载时（在它的搜索范围内找不到），子加载器才尝试自己加载。层级关系：启动类加载器（加载Java核心类rt.jar/lib）→扩展类加载器（加载lib/ext）→应用类加载器（加载classpath下用户类）→自定义类加载器。三大作用：①避免核心类被篡改（用户自定义的和核心类同名的类不会被加载）；<br/>②避免类重复加载（同一个类只被最合适的加载器加载一次）；<br/>③保证核心类的安全性。打破双亲委派的场景：1、JDBC DriverManager——SPI机制通过线程上下文类加载器加载第三方JDBC驱动；<br/>2、Tomcat的WebappClassLoader——每个Web应用有自己独立的类加载器实现隔离；<br/>3、OSGI的模块化类加载——网状结构而非层次结构。</p>', 1, 4, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q262. OOM内存溢出有哪些常见类型？如何排查定位？</p>', '<p>答案解析：常见OOM类型：1、java.lang.OutOfMemoryError: Java heap space——堆内存溢出，对象过多或存在内存泄漏。<br/>2、java.lang.OutOfMemoryError: Metaspace——元空间溢出，动态生成类过多（如CGLIB代理类、大量JSP页面编译类）。<br/>3、java.lang.StackOverflowError——栈溢出，递归调用过深。<br/>4、java.lang.OutOfMemoryError: Direct buffer memory——NIO直接内存溢出，ByteBuffer.allocateDirect()分配了大量堆外内存。排查流程：1、添加JVM参数-XX:+HeapDumpOnOutOfMemoryError自动导出dump文件；<br/>2、用MAT或JProfiler分析dump文件：查看Histogram找出占内存最大的对象、查看Dominator Tree找出持有大量对象的根、查看Leak Suspects让工具自动分析泄漏嫌疑；<br/>3、分析GC日志（-Xloggc）查看各代内存变化趋势；<br/>4、结合代码检查：集合未清理、ThreadLocal未remove、静态集合持续增长（如缓存无上限）、连接未关闭。预防：合理设置堆大小、及时清理不需要的引用、缓存设置容量上限和过期时间。</p>', 1, 4, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q263. JVM调优的核心目标是什么？常用参数有哪些？</p>', '<p>答案解析：调优三大目标：1、减少Full GC次数和持续时间（Full GC是性能杀手）；<br/>2、降低Minor GC引发的STW停顿时间；<br/>3、提升系统吞吐量（用户代码执行时间/总时间）。常用参数分类：堆内存设置——`-Xms`初始堆大小、`-Xmx`最大堆大小（通常设为相同值避免内存扩缩）、`-Xmn`新生代大小（一般占堆1/3~1/2）、`-Xss`线程栈大小（默认1MB）。元空间——`-XX:MetaspaceSize`初始、`-XX:MaxMetaspaceSize`上限。GC选择——`-XX:+UseG1GC`使用G1、`-XX:MaxGCPauseMillis=200`目标停顿时间、`-XX:+UseZGC`低延迟场景、`-XX:+UseParallelGC`吞吐量优先场景。日志与调试——`-XX:+PrintGCDetails`、`-XX:+HeapDumpOnOutOfMemoryError`。调优不是调参数，重要的是优化代码：减少对象创建、重用对象、合适的数据结构（ArrayList vs LinkedList）、减少同步范围。一定要压测验证，参数调整要基于数据而非猜测。</p>', 1, 4, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q264. 逃逸分析是什么？它带来哪些优化？</p>', '<p>答案解析：逃逸分析是JVM的编译优化技术，分析对象的作用域：如果一个对象只在当前方法内创建和使用、不会被方法外部引用，则称该对象"不逃逸"。逃逸分析带来三大优化：1、栈上分配——不逃逸的对象可以在栈上分配内存（随栈帧销毁自动释放），无需在堆上分配+GC回收，极大减少堆压力和GC频率。<br/>2、标量替换——将不逃逸的对象拆解为基本类型成员变量（标量），直接在栈帧上用局部变量替代对象，完全消除对象的创建开销。<br/>3、同步消除——如果确定一个锁对象只会被一个线程访问（线程不逃逸），JVM会消除该锁对象的同步操作（synchronized代码块直接去掉锁）。逃逸分析默认开启，但分析过程需要计算开销，对于简单方法JVM可能直接放弃分析。HotSpot直到JDK6u23才默认开启，且栈上分配在HotSpot中主要通过标量替换间接实现。</p>', 1, 4, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q265. 类加载器有哪些？自定义类加载器有什么用途？</p>', '<p>答案解析：JDK内置三类加载器：1、Bootstrap ClassLoader（启动类加载器）——C/C++实现，加载JAVA_HOME/lib下的核心类（rt.jar等），是JVM的一部分，无法在Java代码中直接获取引用。<br/>2、Extension ClassLoader（扩展类加载器）——由sun.misc.Launcher$ExtClassLoader实现，加载JAVA_HOME/lib/ext目录下的类，JDK9后被Platform ClassLoader取代。<br/>3、Application ClassLoader（应用类加载器）——由sun.misc.Launcher$AppClassLoader实现，加载classpath下的用户类，ClassLoader.getSystemClassLoader()返回的就是它。自定义类加载器的典型用途：①从网络、数据库等非文件系统来源加载类；<br/>②对字节码加密解密（防止反编译）——加密class文件→自定义加载器解密后defineClass；<br/>③实现类隔离——同一类不同版本同时运行（如Tomcat允许不同Web应用使用不同版本的jar）；<br/>④热部署——动态加载新版本class替换旧版本。</p>', 1, 4, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q266. JVM中内存分配与回收策略是怎样的？</p>', '<p>答案解析：对象分配优先在新生代的Eden区进行——绝大多数对象在Eden区诞生。Eden区满时触发Minor GC：存活对象复制到Survivor区（S0或S1，两个Survivor区交替使用），每次Minor GC存活对象在两个Survivor之间复制一次，年龄Age+1（对象头中记录）。当Age达到阈值（默认15，通过-XX:MaxTenuringThreshold设置）时，对象晋升到老年代。特殊分配规则：1、大对象直接进入老年代——通过-XX:PretenureSizeThreshold设置阈值（仅Serial和ParNew有效），避免大对象在新生代频繁复制。<br/>2、Survivor空间不足——Minor GC时如果Survivor区放不下存活对象，多余的对象直接进入老年代（通过分配担保机制）。<br/>3、动态年龄判定——如果Survivor区中相同年龄的所有对象大小之和超过Survivor空间的一半，大于等于该年龄的对象直接进入老年代。GC采用复制算法（新生代）：Eden+一个Survivor存活对象→另一个Survivor，然后清空前两个区。</p>', 1, 4, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q267. finalize()方法为什么不推荐使用？有什么替代方案？</p>', '<p>答案解析：finalize()是Object类的方法，在对象被GC回收前由垃圾收集线程调用。不推荐原因（已从JDK9标记为@Deprecated）：1、执行时机不可控——finalize()的执行由GC线程决定，可能很久后才执行（甚至永远不执行，因为对象可能逃过GC）。<br/>2、性能开销极大——重写finalize()的对象GC时需要至少两次GC才能回收（第一次GC后放入队列，等待finalize线程执行完后第二次GC才真正回收）。<br/>3、finalize线程优先级低——可能导致finalize队列积压。<br/>4、如果在finalize()中又让对象"复活"（将自身重新赋值给静态变量），该对象将永久不会被回收。替代方案：1、try-with-resources或显式的close()方法配合finally（确定性的资源释放）。<br/>2、Cleaner+PhantomReference（JDK9引入的Cleaner替代finalize，如NIO直接内存的释放）。<br/>3、AutoCloseable接口规范资源生命周期。最好忘记Java有finalize()这个方法。</p>', 1, 4, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q268. 对象在堆内存中的内存布局是怎样的？</p>', '<p>答案解析：HotSpot中对象在堆内存中的内存布局分为三部分：1、对象头（Object Header）：MarkWord（标记字）+类型指针+（如果是数组）数组长度。MarkWord占用8字节（64位JVM），存储对象的hashCode、GC分代年龄、锁状态标志、偏向锁线程ID等信息——同一块MarkWord在不同锁状态下存储不同内容，复用空间。类型指针（Klass Pointer）指向方法区中该类的Class对象，默认占8字节（压缩后4字节）。<br/>2、实例数据（Instance Data）：对象真正存储的有效信息，包括父类和子类所有字段。字段排列顺序受JVM优化影响（相同宽度的字段分配在一起，如long/double优先，int/float次之，引用最后），目的是内存对齐提高访问效率。<br/>3、对齐填充（Padding）：对象大小必须是8字节的整数倍，不足则对齐填充。这个设计是为了CPU缓存行对齐，提升内存访问效率（CPU一次读取一个缓存行64字节）。使用JOL（Java Object Layout）工具可直接查看对象内存布局。</p>', 1, 4, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q269. 内存泄漏和内存溢出有何区别？如何预防？</p>', '<p>答案解析：内存泄漏（Memory Leak）是对象不再被业务使用但一直被强引用持有，无法被GC回收，导致可用内存逐渐减少。内存溢出（OutOfMemoryError）是内存消耗达到上限，无法分配新内存，程序崩溃抛异常。两者关系：短期小规模泄漏不一定会OOM，但长期持续的内存泄漏最终一定会导致内存溢出。常见泄漏场景：1、静态集合（如static List）不断添加对象从不清理；<br/>2、ThreadLocal用后未remove()（线程池复用线程导致Value不释放）；<br/>3、数据库/网络连接未关闭（物理连接占用内存）；<br/>4、监听器/Observer注册后未取消注册；<br/>5、内部类持有外部类引用导致外部类无法回收（如非静态Handler持有Activity）；<br/>6、缓存无容量上限无限增长。预防措施：使用有界缓存（Caffeine/Guava Cache配置maxSize）、ThreadLocal用后finally remove()、资源统一用try-with-resources、使用WeakHashMap存储临时映射、定期通过监控工具检查堆内存趋势。</p>', 1, 4, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q270. 常用的GC日志参数和如何分析GC日志？</p>', '<p>答案解析：JDK8 GC日志参数：`-XX:+PrintGCDetails -XX:+PrintGCDateStamps -Xloggc:gc.log`。JDK9+统一日志：`-Xlog:gc*=info:file=gc.log:time,level,tags`。GC日志关键信息：每行日志包含发生时间、GC类型（Minor GC会显示Young/DefNew，Full GC会显示Full/Allocation Failure）、回收前内存占用→回收后内存占用（该区域总大小）、以及GC耗时（real=系统时间，user=CPU用户态，sys=内核态）。重点关注：1、Full GC的触发频率和原因（"Allocation Failure"分配失败、"Ergonomics"自适应策略、"Metadata GC Threshold"元空间不足）；<br/>2、GC耗时——Minor GC应<50ms，Full GC应<1s，否则需要调优；<br/>3、各区域内存使用趋势——判断堆大小是否合理。推荐GCEasy、GCViewer等可视化工具分析GC日志，生成报告展示吞吐量、停顿时间分布、各代内存曲线。日常监控中Full GC频率上升是最危险的信号。</p>', 1, 4, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q271. JIT编译器的工作原理和分层编译？</p>', '<p>答案解析：JIT（Just In Time）编译器将热点字节码编译为本地机器码，替代解释执行，大幅提升执行速度。热点探测：方法调用计数器+回边计数器（循环），当计数器超过阈值（Client模式1500次，Server模式10000次，通过-XX:CompileThreshold设置）时触发JIT编译。编译后的机器码存储在代码缓存（Code Cache）中，后续调用直接执行机器码。分层编译（JDK8默认开启）：C1编译器（Client Compiler）快速编译+较低优化，响应快；C2编译器（Server Compiler）深度优化+编译慢，执行效率最高。JVM根据方法热度动态在C1/C2之间切换：Level 0解释执行→Level 1 C1无profiling编译→Level 2 C1带简单profiling→Level 3 C1带完整profiling→Level 4 C2深度优化编译。C1主要优化：方法内联、常量折叠、公共子表达式消除；C2额外优化：逃逸分析、标量替换、循环展开、自动向量化。可通过-XX:+PrintCompilation查看编译日志。</p>', 1, 4, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q272. 什么是STW（Stop The World）？哪些操作会触发？</p>', '<p>答案解析：STW即JVM暂停所有用户线程（应用完全停顿），只保留GC线程工作，用于执行那些"必须在一致性快照上执行"的GC阶段。总结：所有垃圾收集器都会发生STW（只是时长不同），所有枚举GC Roots的操作都需要STW。触发STW的常见场景：1、Minor GC的初始标记和对象复制（几十ms）；<br/>2、Full GC的全过程（可达秒级甚至分钟级）；<br/>3、CMS的初始标记+重新标记；<br/>4、G1的初始标记+最终标记+筛选回收；<br/>5、Thread Dump（jstack）、Heap Dump（jmap）等命令行工具也会触发STW；<br/>6、偏向锁撤销（涉及安全点）；<br/>7、类加载的某些阶段。虽然ZGC和Shenandoah号称停顿时间<10ms，但仍有极短的STW。生产环境如果频繁出现长STW，首先排查是否频繁FullGC，然后检查大对象分配、元空间是否充足、是否有代码显式调用System.gc()。</p>', 1, 4, 0, 0, NULL, CURRENT_TIMESTAMP);-- Part 5: Spring全家桶框架 (tag=5, 20条)
INSERT INTO `t_knowledge` (`question`, `answer`, `status`, `tag`, `del_flag`, `view_count`, `last_view_time`, `add_time`) VALUES
('<p>Q273. Spring三级缓存是如何解决循环依赖的？为什么构造器注入不能解决？</p>', '<p>答案解析：Spring三级缓存分别是：一级缓存singletonObjects（存放完全初始化好的单例Bean）、二级缓存earlySingletonObjects（存放早期暴露的半成品Bean，即已实例化但未属性填充）、三级缓存singletonFactories（存放能生成半成品Bean的ObjectFactory工厂）。解决循环依赖的核心流程：A和B互相依赖，Spring先创建A→实例化A（构造器）→将A的ObjectFactory放入三级缓存→填充A的属性，发现需要B→去创建B→实例化B→将B的ObjectFactory放入三级缓存→填充B的属性，发现需要A→从三级缓存获取A的ObjectFactory→生成A的提前引用→放入二级缓存→B拿到A的引用完成初始化→回到A继续完成初始化。关键：三级缓存存的是ObjectFactory而非直接存Bean，目的是为AOP代理留后门（如果Bean需要AOP，ObjectFactory返回代理对象而非原始对象）。构造器注入无法解决循环依赖的原因：构造器注入在实例化阶段就需要依赖，而三级缓存是在实例化之后、属性填充之前才放入，此时Bean还没进缓存，构造器无法拿到半成品引用。</p>', 1, 5, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q274. Spring事务失效的常见场景有哪些？如何排查？</p>', '<p>答案解析：七种常见失效场景：1、方法非public——Spring事务通过AOP动态代理实现，JDK/CGLIB代理只能代理public方法，private/protected方法事务不生效。<br/>2、同类内部调用——在同一个类中方法A（有事务）调用方法B（有事务），B的事务不会生效。因为调用是this.B()直接调用目标对象而非代理对象，跳过了AOP代理。解决方法：将B抽到另一个Service中或用AopContext.currentProxy()获取代理对象调用。<br/>3、异常被try-catch吞掉——事务回滚的触发条件是抛出未被捕获的RuntimeException或Error，如果catch后没再抛出，事务认为正常提交。<br/>4、rollbackFor配置错误——默认只回滚RuntimeException和Error，受检异常不回滚。需配置@Transactional(rollbackFor = Exception.class)。<br/>5、数据库引擎不支持事务（MyISAM）。<br/>6、多线程——事务绑定在线程上（ThreadLocal），新线程无法获取原事务。<br/>7、传播机制配置不当——如本应REQUIRED却配成NOT_SUPPORTED。</p>', 1, 5, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q275. Spring事务的传播行为有哪些？REQUIRED和REQUIRES_NEW的区别？</p>', '<p>答案解析：七种传播行为：1、REQUIRED（默认）——有事务则加入，无事务则新建。最常用，适合大多数增删改操作。<br/>2、REQUIRES_NEW——总是新建独立事务，当前事务存在则挂起。内外事务完全独立，各自提交或回滚互不影响。适合需要独立提交的子操作（如记录日志、发送通知不因主业务回滚而丢失）。<br/>3、SUPPORTS——有事务则加入，无事务则非事务运行。适合查询操作。<br/>4、NOT_SUPPORTED——非事务运行，有事务则挂起。适合不需要事务的耗时操作，避免长时间占用数据库连接。<br/>5、MANDATORY——必须在事务中运行，无事务抛异常。<br/>6、NEVER——必须非事务运行，有事务抛异常。<br/>7、NESTED——嵌套事务，外部事务回滚时内部也回滚，但内部回滚不影响外部（通过savepoint实现，仅JDBC单个连接支持）。REQUIRED vs REQUIRES_NEW关键区别：REQUIRED内外共用同一事务（同生共死），REQUIRES_NEW内外独立（各自提交各自回滚）。</p>', 1, 5, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q276. Spring AOP的JDK动态代理和CGLIB代理适用场景及如何选择？</p>', '<p>答案解析：JDK动态代理要求被代理类实现至少一个接口，JVM运行时动态生成$Proxy0.class字节码（继承Proxy类+实现目标接口），通过反射InvocationHandler.invoke()调用。CGLIB代理无需接口，底层通过ASM字节码框架动态生成目标类的子类，覆写父类非final方法实现增强，通过FastClass索引定位方法（比反射更快）。Spring的代理选择策略：默认有接口用JDK代理，无接口用CGLIB代理。可通过@EnableAspectJAutoProxy(proxyTargetClass=true)或配置spring.aop.proxy-target-class=true强制使用CGLIB。SpringBoot 2.x开始默认启用CGLIB代理（spring.aop.proxy-target-class默认为true），因为CGLIB不需要接口依赖且性能更高。CGLIB的限制：不能代理final类和方法（无法继承/覆写），目标类必须有无参构造器（或默认构造器）。实际项目中大多数Service类不实现接口，默认走CGLIB代理。</p>', 1, 5, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q277. Spring MVC的完整请求处理流程是怎样的？</p>', '<p>答案解析：客户端请求→1、DispatcherServlet前端控制器接收请求（Servlet规范入口）。<br/>2、DispatcherServlet调用HandlerMapping处理器映射器，根据请求URL找到对应的Handler（Controller方法）和Interceptor拦截器链。<br/>3、DispatcherServlet调用HandlerAdapter处理器适配器，适配不同类型的Handler（如@RequestMapping方法、HttpRequestHandler等），执行拦截器的preHandle。<br/>4、HandlerAdapter调用参数解析器（HandlerMethodArgumentResolver）将请求参数转换为Controller方法参数（@RequestParam、@RequestBody、@PathVariable等）。<br/>5、执行Controller目标方法，返回ModelAndView或@ResponseBody直接写响应。<br/>6、如果有返回值需要处理，调用返回值处理器（HandlerMethodReturnValueHandler），如@ResponseBody通过HttpMessageConverter将对象序列化为JSON。<br/>7、执行拦截器的postHandle和afterCompletion。<br/>8、DispatcherServlet将响应返回给客户端。核心组件一览：HandlerMapping找处理器、HandlerAdapter执行处理器、HandlerInterceptor拦截器、ViewResolver视图解析、HttpMessageConverter消息转换。</p>', 1, 5, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q278. 过滤器和拦截器的区别？各自适用什么场景？</p>', '<p>答案解析：六大核心区别：1、依赖容器——Filter是Servlet规范的一部分，依赖Servlet容器（Tomcat），不依赖Spring；Interceptor是Spring MVC组件，由Spring容器管理。<br/>2、执行顺序——Filter先于Interceptor执行（Filter在DispatcherServlet之前，Interceptor在DispatcherServlet之后到达Controller之前）。<br/>3、拦截范围——Filter拦截所有进入Servlet容器的请求（包括静态资源）；Interceptor只拦截经过DispatcherServlet的Controller请求（不拦静态资源除非配置）。<br/>4、精细度——Filter只能获取request/response，不知道具体是哪个Controller方法；Interceptor可以通过HandlerMethod获取到具体的Controller类、方法、参数等详细信息。<br/>5、执行次数——Filter在请求和响应阶段各执行一次；Interceptor的preHandle、postHandle、afterCompletion在请求不同阶段分别执行。<br/>6、适用场景——Filter：编码设置、XSS过滤、跨域CORS、权限验证原始URL；Interceptor：登录校验（获取Controller注解判断是否需要登录）、权限细粒度控制、操作日志记录（能拿到方法名和参数）。</p>', 1, 5, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q279. SpringBoot自动配置原理？@SpringBootApplication做了什么？</p>', '<p>答案解析：@SpringBootApplication是一个组合注解，包含@SpringBootConfiguration（等价@Configuration）、@EnableAutoConfiguration（核心）、@ComponentScan（组件扫描）。自动配置核心流程：1、启动类上的@EnableAutoConfiguration通过@Import导入AutoConfigurationImportSelector。<br/>2、AutoConfigurationImportSelector读取META-INF/spring.factories（SpringBoot 2.x）或META-INF/spring/org.springframework.boot.autoconfigure.AutoConfiguration.imports（SpringBoot 3.x）中配置的所有自动配置类全限定名（共100+个）。<br/>3、每个自动配置类都使用了@Conditional系列条件注解进行过滤，如@ConditionalOnClass（classpath存在某类才加载）、@ConditionalOnMissingBean（容器中不存在某Bean才创建）、@ConditionalOnProperty（配置项匹配才生效）。<br/>4、只有条件满足的自动配置类才被加载并创建对应的Bean。举例：classpath有spring-boot-starter-web则加载WebMvc自动配置（内置Tomcat、DispatcherServlet等）；有mybatis-spring-boot-starter则加载MyBatis自动配置（SqlSessionFactory、MapperScanner）。自动配置的本质就是"约定大于配置"——引入依赖即自动完成配置，同时保留覆盖能力。</p>', 1, 5, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q280. SpringBoot Starter机制的作用及自定义Starter？</p>', '<p>答案解析：Starter是SpringBoot的依赖整合组件，封装了特定功能所需的所有Jar包依赖和自动配置类。开发者只需引入一个starter依赖，无需关心版本冲突和配置细节。核心组成：1、pom.xml——声明该功能模块所需的所有依赖（包括版本由spring-boot-dependencies统一管理）。<br/>2、自动配置类——在spring.factories中注册，通过@Configuration+@ConditionalOnXxx按条件创建Bean。<br/>3、配置属性类——@ConfigurationProperties(prefix="xxx")映射application.yml中的配置项。自定义Starter步骤：创建autoconfigure模块（含自动配置类+配置属性类+spring.factories）和starter模块（空模块，仅pom.xml依赖autoconfigure模块）。命名规范：官方starter为spring-boot-starter-xxx，第三方为xxx-spring-boot-starter。常见Starter：spring-boot-starter-web（Web应用）、spring-boot-starter-data-redis（Redis集成）、mybatis-spring-boot-starter（MyBatis集成）。</p>', 1, 5, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q281. @Autowired和@Resource的区别？各自注入规则？</p>', '<p>答案解析：@Autowired是Spring注解，默认按类型（byType）注入，配合@Qualifier可指定名称。注入规则：先byType匹配容器中的Bean，同类型只有一个则直接注入；多个则按字段名/参数名匹配；找不到且required=true则抛异常（required=false则跳过）。@Resource是JDK注解（javax.annotation.Resource），默认按名称（byName）注入，名称匹配不上再按类型匹配。可指定name属性精确指定Bean名称。两者的核心区别：来源不同（Spring vs JDK）、默认匹配策略不同（类型优先 vs 名称优先）、@Autowired可配合@Qualifier精确指定而@Resource直接用name属性。Spring官方推荐构造器注入替代字段注入：`private final UserService userService; public UserController(UserService userService) { this.userService = userService; }`。好处：依赖不可变（final）、初始化完整性保证、易于单元测试（不需反射注入）、避免循环依赖问题。</p>', 1, 5, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q282. Spring Bean的作用域有哪些？单例Bean如何保证线程安全？</p>', '<p>答案解析：五种作用域：1、singleton（默认）——整个IoC容器只有一个实例，所有请求共享。<br/>2、prototype——每次获取都创建新实例。<br/>3、request——每个HTTP请求创建一个实例（仅Web应用）。<br/>4、session——每个HTTP会话创建一个实例。<br/>5、application——整个ServletContext一个实例。单例Bean线程安全问题：Spring不负责Bean的线程安全——单例Bean的成员变量被所有并发线程共享，如果成员变量有状态（写操作），就存在线程安全问题。解决方案：1、Bean设计为无状态——只有方法没有成员变量（最推荐，大多数Service/Dao都是无状态的）。<br/>2、使用ThreadLocal将状态隔离到线程级别。<br/>3、设置作用域为prototype（每次请求新实例，但有性能开销）。<br/>4、在方法内使用局部变量而非成员变量（局部变量在线程栈上，天然线程安全）。<br/>5、使用同步锁（synchronized/Lock，不推荐因为会降低并发）。实际项目中的Controller、Service、Dao都设计为无状态的（依赖注入的是同样无状态的Bean），天然线程安全。</p>', 1, 5, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q283. Spring的@Transactional注解原理及自调用失效原因？</p>', '<p>答案解析：@Transactional基于Spring AOP实现，底层通过TransactionInterceptor拦截标注了@Transactional的方法。执行流程：AOP代理对象拦截方法调用→TransactionInterceptor获取@Transactional注解属性→通过TransactionManager开启事务（从DataSource获取连接，设置autoCommit=false，绑定连接到当前线程）→执行目标方法→成功则提交事务，异常则回滚。自调用失效原因：当同类中方法A调用方法B（B有@Transactional），实际上是this.B()直接调用了目标对象的方法，绕过了AOP代理对象。Spring事务是通过代理对象实现的，直接this调用不会经过代理，事务拦截器不会执行。解决办法三种：1、把方法B移到另一个Service（推荐，也符合单一职责）；<br/>2、通过AopContext.currentProxy()获取当前代理对象调用：`((UserService)AopContext.currentProxy()).methodB()`（需配置@EnableAspectJAutoProxy(exposeProxy=true)）；<br/>3、通过@Autowired注入自身（会产生循环依赖，借助三级缓存解决）。</p>', 1, 5, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q284. @Component、@Service、@Repository、@Controller的区别？</p>', '<p>答案解析：这四个注解功能完全等价——都会将类注册为Spring Bean。区别仅在于语义化分类，帮助开发者和框架识别类的角色。@Component：通用组件，标记任何Spring管理的组件，是其他三个的父注解。@Service：业务逻辑层组件，标记Service实现类。@Repository：数据访问层组件，标记DAO类，Spring会对该注解标记的类做额外的持久层异常转换——将JDBC/Hibernate/JPA的数据库异常转换为Spring统一的DataAccessException。@Controller：控制层组件，标记Controller类，配合@RequestMapping等处理HTTP请求，Spring MVC的HandlerMapping会扫描@Controller注解的Bean。在组件扫描（@ComponentScan）时，这四个注解都会被自动检测并注册。区分使用的好处：代码按层清晰分类、@Repository的异常转换功能、AOP切点可以精确针对某一层（如只拦截@Repository的方法做数据库监控）。</p>', 1, 5, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q285. SpringBoot全局异常处理最佳实践？</p>', '<p>答案解析：三层异常处理架构：1、@RestControllerAdvice全局异常拦截器——捕获所有Controller抛出的异常，统一封装为规范格式的返回结果（code、message、data），避免前端收到Tomcat原生的404/500错误页面。核心方法：@ExceptionHandler(Exception.class)兜底捕获未知异常返回"系统繁忙"。<br/>2、自定义业务异常——定义BusinessException(code, message)，在业务代码中throw new BusinessException("用户不存在")，@ExceptionHandler(BusinessException.class)专门捕获并返回对应的业务友好提示。<br/>3、参数校验异常——配合@Valid+@RequestBody，参数校验失败抛出MethodArgumentNotValidException，全局捕获后统一解析校验错误信息返回。还可细化捕获HttpMessageNotReadableException（JSON格式错误）、HttpRequestMethodNotSupportedException（请求方式不支持）、MissingServletRequestParameterException（缺少参数）等。核心原则：永远不要让异常堆栈直接暴露给前端，所有异常都转为用户友好的提示信息，关键异常记录日志。</p>', 1, 5, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q286. SpringBoot启动流程是怎样的？@SpringBootApplication做了什么？</p>', '<p>答案解析：SpringBoot启动流程：1、执行main方法→调用SpringApplication.run()。<br/>2、创建SpringApplication实例——推断应用类型（Servlet/Reactive/非Web）。<br/>3、从spring.factories加载并执行ApplicationContextInitializer和ApplicationListener。<br/>4、准备Environment环境——加载application.yml/properties、系统属性、环境变量等。<br/>5、创建ApplicationContext（Servlet类型创建AnnotationConfigServletWebServerApplicationContext）。<br/>6、执行prepareContext——将启动类注册为配置类、加载beans。<br/>7、执行refreshContext——核心的IoC容器refresh()，扫描Bean、执行自动配置、初始化单例Bean。<br/>8、启动内嵌Web服务器（Tomcat/Jetty/Undertow），绑定端口，对外提供服务。<br/>9、执行所有CommandLineRunner和ApplicationRunner。整个启动过程最耗时的是Bean扫描和初始化阶段，可通过spring.main.lazy-initialization=true延迟初始化加速启动（但首次请求变慢）。</p>', 1, 5, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q287. SpringBoot热部署（DevTools）原理？与JRebel的区别？</p>', '<p>答案解析：Spring Boot DevTools通过两个ClassLoader实现快速重启——base ClassLoader加载不变的第三方jar包，restart ClassLoader加载项目自身的class。修改代码后，只丢弃并重建restart ClassLoader（无需重启base ClassLoader），所以比完全重启快（但项目大时仍需数秒）。默认监听classpath下文件变化，通过spring.devtools.restart.enabled控制。LiveReload配合浏览器插件实现页面自动刷新。DevTools与JRebel本质区别：DevTools是重启（重新加载类、重新初始化Bean、重新建立数据库连接等），只是比手动重启快；JRebel是真热部署——不重启JVM、不销毁ClassLoader，直接在运行时替换类的字节码并重新加载修改后的类，Bean状态保留。JRebel是商业收费工具，适合大型项目（重启需数分钟），DevTools免费适合小型项目。微服务时代每个服务启动很快，DevTools或完全不使用热部署（直接重启）也完全可接受。</p>', 1, 5, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q288. SpringBoot如何实现跨域（CORS）解决方案？</p>', '<p>答案解析：三种跨域方案：1、@CrossOrigin注解——直接标注在Controller类或方法上，精细到方法级别的跨域控制。适合少量接口需要跨域的简单场景。<br/>2、WebMvcConfigurer全局配置——实现addCorsMappings方法，`registry.addMapping("/api/**").allowedOrigins("http://localhost:8080").allowedMethods("GET","POST").allowCredentials(true).maxAge(3600)`，统一对/api/**路径配置跨域策略。适合后台管理系统等单一前端的场景。<br/>3、CorsFilter过滤器——注册一个CorsFilter Bean，优先级最高，在Filter层面处理跨域，早于Spring MVC。适合需要拦截所有请求（包括静态资源和非Controller请求）的场景。生产环境建议：开发阶段用方案2简单配置；生产用Nginx反向代理统一处理跨域，前端请求Nginx→转发后端，浏览器的同源限制对Nginx不生效（同一域名不同路径）。allowCredentials=true时allowedOrigins不能设为*，必须明确指定域名。</p>', 1, 5, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q289. SpringBoot项目中如何优雅地使用异步任务？</p>', '<p>答案解析：三步实现异步任务：1、启动类或配置类加@EnableAsync注解开启异步支持。<br/>2、在需要异步执行的方法上加@Async注解，Spring会将该方法的调用提交给线程池异步执行，调用方立即返回不阻塞。<br/>3、配置自定义线程池——实现AsyncConfigurer接口或直接定义ThreadPoolTaskExecutor Bean，设置核心线程数、最大线程数、队列容量、拒绝策略、线程名前缀等。重要注意事项：①@Async方法必须放在不同的Bean中调用才生效（同类内部调用绕过代理，与@Transactional同理）；<br/>②@Async方法返回值可以是void或Future/CompletableFuture；<br/>③线程池必须显式配置，默认使用的是SimpleAsyncTaskExecutor（每次新建一个线程，无复用，极其危险）；<br/>④异常处理需要配置AsyncUncaughtExceptionHandler处理异步任务中的未捕获异常（否则异常会被静默吞掉）；<br/>⑤注意ThreadLocal传递问题——异步线程中没有主线程的ThreadLocal值（如RequestContext），需要手动传递。</p>', 1, 5, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q290. Spring中用到的设计模式有哪些？</p>', '<p>答案解析：Spring框架中贯穿了多种设计模式：1、单例模式——Spring容器中的Bean默认是单例，通过ConcurrentHashMap（一级缓存singletonObjects）保存。<br/>2、工厂模式——BeanFactory和ApplicationContext是创建Bean的工厂。<br/>3、代理模式——AOP底层实现（JDK动态代理/CGLIB代理）。<br/>4、模板方法模式——JdbcTemplate、RestTemplate、RedisTemplate等*Template类，定义算法骨架，用户只需填充变化部分（SQL、回调等）。<br/>5、观察者模式——Spring事件机制（ApplicationEvent+@EventListener），Bean之间解耦通信。<br/>6、策略模式——Bean的实例化策略（InstantiationStrategy），资源访问策略（ResourceLoader对不同来源资源的加载策略）。<br/>7、适配器模式——HandlerAdapter适配不同类型的Controller。<br/>8、装饰器模式——ServerHttpRequestDecorator包装HttpServletRequest增强功能。<br/>9、责任链模式——拦截器链（HandlerInterceptor[]）和过滤器链（FilterChain）。<br/>10、建造者模式——SpringApplicationBuilder构建SpringApplication。</p>', 1, 5, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q291. Spring WebFlux响应式编程与Spring MVC的区别？</p>', '<p>答案解析：Spring MVC基于Servlet API，每个请求一个线程（同步阻塞），线程在IO等待时不释放，并发量受线程池大小限制。Spring WebFlux基于Reactive Streams规范，使用Mono（0或1个元素）和Flux（0到N个元素）作为响应式类型，底层基于Netty（非阻塞事件驱动模型），少量线程即可处理高并发（线程不会阻塞等待IO）。核心区别：编程模型——MVC是命令式（一步步告诉怎么做），WebFlux是声明式（描述数据流和转换规则）；并发模型——MVC线程池（200个线程支撑200个并发），WebFlux事件循环（几个线程支撑数万并发）；适用场景——MVC适合CPU密集和传统CRUD，WebFlux适合IO密集、高并发网关、实时推送、流式处理。选择建议：如果项目已有Spring MVC代码和大量基于ThreadLocal的组件（如Spring Security、事务），不建议迁移到WebFlux（ThreadLocal在响应式中不可用）。新项目IO密集型可考虑WebFlux，但不是银弹——简单CRUD用MVC开发效率更高。</p>', 1, 5, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q292. Spring Security的核心原理和JWT认证流程？</p>', '<p>答案解析：Spring Security基于过滤器链（FilterChain）实现安全控制。核心组件：SecurityContextHolder通过ThreadLocal存储当前登录用户信息（SecurityContext→Authentication→Principal/Credentials/Authorities）。认证流程：请求→UsernamePasswordAuthenticationFilter提取用户名密码→封装为AuthenticationToken→通过AuthenticationManager（实际委托给ProviderManager）调用AuthenticationProvider进行认证→UserDetailsService.loadUserByUsername()从数据库加载用户→密码比对→认证成功返回填充了权限信息的Authentication对象→存入SecurityContextHolder。JWT认证流程：用户登录成功→服务端生成JWT返回客户端→客户端每次请求在Header中携带`Authorization: Bearer <token>`→自定义JwtAuthenticationFilter从Header中解析JWT→验证签名和有效期→获取用户信息和权限→构造Authentication对象存入SecurityContextHolder。JWT优势：无状态（服务端不存session），天然支持分布式；缺点：无法主动失效（需配合黑名单或其他方案）。</p>', 1, 5, 0, 0, NULL, CURRENT_TIMESTAMP);-- Part 6: MyBatis与MyBatis-Plus (tag=6, 10条)
INSERT INTO `t_knowledge` (`question`, `answer`, `status`, `tag`, `del_flag`, `view_count`, `last_view_time`, `add_time`) VALUES
('<p>Q293. MyBatis中${}和#{}的本质区别及各自使用场景？</p>', '<p>答案解析：#{}是预编译占位符（PreparedStatement的?），执行流程：将SQL中的#{}替换为?→数据库对SQL进行预编译（解析、优化、生成执行计划）→传入参数值执行。优点：防止SQL注入（参数值作为数据而非SQL语法解析）、预编译缓存提高性能（SQL模板相同可复用执行计划）。${}是字符串直接拼接：将参数值直接拼入SQL语句，拼完后再发送给数据库。优点：可用于动态表名、字段名、排序字段（ORDER BY ${column}）。重大风险：SQL注入——如果参数来自用户输入，恶意值可拼入任意SQL代码。使用准则：除非动态表/字段/排序，其他一切场景用#{}。动态排序安全处理：后端白名单校验列名是否合法（如只允许"create_time"/"update_time"），校验通过再用${}拼接。</p>', 1, 6, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q294. MyBatis一级缓存和二级缓存有什么区别？各自失效条件？</p>', '<p>答案解析：一级缓存（SqlSession级别）：默认自动开启，SqlSession内的查询先检查缓存，命中则直接返回。同一个SqlSession中执行两次相同的查询只发一次SQL。失效条件：①执行增删改操作（不管是否影响缓存的数据，清空全部缓存）；<br/>②手动clearCache()；<br/>③commit()提交事务；<br/>④关闭SqlSession。生命周期很短（通常一次请求），一般不需要关心。二级缓存（Mapper Namespace级别）：跨SqlSession，多个SqlSession共享同一Mapper的缓存。需显式开启：①mybatis-config.xml中设置cacheEnabled=true；<br/>②Mapper XML中添加<cache/>标签；<br/>③查询结果实体类必须实现Serializable。失效条件：该namespace执行增删改操作时清空。适用场景：查询频率高、数据变化少（如字典、地区、配置等基础数据）。注意：多表关联查询不要用二级缓存（数据来自多个表，某个表更新了但另一个Mapper的缓存不知道）。</p>', 1, 6, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q295. MyBatis动态SQL常用标签有哪些？各自作用？</p>', '<p>答案解析：1、&lt;if&gt;——条件判断，test属性写OGNL表达式，最常用。<br/>2、&lt;where&gt;——包裹条件，自动去掉开头多余的AND/OR，所有条件都不满足时不生成WHERE关键字。<br/>3、&lt;set&gt;——用于UPDATE语句，自动去掉末尾逗号。<br/>4、&lt;foreach&gt;——遍历集合，collection指定集合参数名，item为遍历变量名，separator指定分隔符，open/close指定包围符。批量插入：`INSERT INTO t VALUES &lt;foreach collection="list" item="item" separator=","&gt;(#{item.id}, #{item.name})&lt;/foreach/&gt;`。IN查询：`WHERE id IN &lt;foreach collection="ids" item="id" open="(" close=")" separator=","&gt;#{id}&lt;/foreach&gt;`。注意：foreach参数超过1000时需分批（数据库IN限制超过1000性能差）。<br/>5、&lt;choose&gt;&lt;when&gt;&lt;otherwise&gt;——类似于Java的switch-case-default，多选一。<br/>6、&lt;trim&gt;——更灵活的去除/添加前缀后缀，&lt;where&gt;和&lt;set&gt;本质是&lt;trim&gt;的简化。<br/>7、&lt;bind&gt;——创建变量用于模糊查询：`&lt;bind name="pattern" value="''''%''''+keyword+''''%''''"/&gt;`，解决不同数据库模糊查询语法差异。</p>', 1, 6, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q296. MyBatis分页原理及PageHelper插件的实现机制？</p>', '<p>答案解析：MyBatis原生没有物理分页功能，RowBounds只是内存分页（查出全部数据再截取，数据量大时OOM）。PageHelper分页插件原理：基于MyBatis的拦截器（Interceptor），拦截Executor的query方法。执行流程：①调用PageHelper.startPage(pageNum, pageSize)，通过ThreadLocal保存分页参数（当前页、每页条数）；<br/>②执行Mapper查询方法时，拦截器的intercept方法被触发；<br/>③从ThreadLocal取出分页参数，如果存在则改写SQL——在原始SQL外层包裹`SELECT COUNT(*) FROM (原始SQL)`查询总数存储到Page对象中，同时在原始SQL末尾追加`LIMIT offset, pageSize`（MySQL）。本质上实现了物理分页和自动查总数。使用限制：startPage()后必须紧跟Mapper查询方法（中间不能有其他查询），只对第一个查询生效。分页后通过`((Page)list).getTotal()`获取总条数。PageHelper也支持排序（`PageHelper.orderBy("create_time desc")`），比SQL拼接更安全。</p>', 1, 6, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q297. MyBatis延迟加载原理？什么时候使用和避免？</p>', '<p>答案解析：延迟加载（懒加载Lazy Loading）：查询主对象时不立即查询关联对象，当真正访问关联对象属性时才执行子查询。配置：mybatis-config.xml中设置lazyLoadingEnabled=true（开启延迟加载）、aggressiveLazyLoading=false（按需加载而非全部加载）。原理：MyBatis使用CGLIB/Javassist对查询结果对象创建代理，代理对象拦截关联属性的getter方法，首次调用时触发子查询从数据库加载数据。适用场景：查询用户时不一定要看用户的所有订单——`select * from user`立即可用，只有调用user.getOrders()时才发SQL查询订单。避免使用的场景：1、已知一定会访问关联数据（反而多一次查询，N+1问题）；<br/>2、序列化场景（序列化时会访问所有getter，触发所有延迟加载，导致N+1）。注意：延迟加载依赖SqlSession，如果SqlSession已关闭（如Service层返回后controller层访问），会报LazyInitializationException。实践中一般禁用延迟加载（默认是关闭的），用JOIN一次查出或在需要时分两次查。</p>', 1, 6, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q298. MyBatis-Plus的条件构造器QueryWrapper和LambdaQueryWrapper区别？</p>', '<p>答案解析：QueryWrapper：基于字符串指定字段名，`eq("user_name", "张三").gt("age", 18).orderByDesc("create_time")`。优点：灵活，可动态拼接条件。缺点：字段名是硬编码字符串，拼写错误编译期不报错（运行时SQL报错），字段重命名时需全局搜索替换字符串。LambdaQueryWrapper：基于Lambda表达式指定字段，`eq(User::getUserName, "张三").gt(User::getAge, 18).orderByDesc(User::getCreateTime)`。优点：编译期类型安全（getter方法名写错编译不过）、IDE重构支持（重命名getter方法时同步更新）、代码提示。缺点：略冗长（需要写两次lambda）。LambdaQueryWrapper内部通过序列化Lambda解析方法名，从getUserName提取字段名user_name（驼峰转下划线）。企业开发强烈推荐LambdaQueryWrapper——杜绝字段名拼写错误的线上Bug。两者底层功能完全一致，LambdaQueryWrapper本质是QueryWrapper的子类，多了一层Lambda解析。</p>', 1, 6, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q299. MyBatis-Plus逻辑删除和自动填充的实现原理？</p>', '<p>答案解析：逻辑删除（@TableLogic）：标注逻辑删除字段（默认del_flag），执行deleteById时MP会自动将DELETE语句改写为UPDATE SET del_flag=1 WHERE id=? AND del_flag=0。查询时自动追加WHERE del_flag=0条件（MP的SQL注入拦截器会自动添加）。配置：全局配置logic-delete-field: delFlag，logic-delete-value: 1（已删除），logic-not-delete-value: 0（未删除）。如需物理删除，可自定义Mapper方法手动写DELETE语句。自动填充（@TableField(fill = ...)）：标注需要自动填充的字段，配合MetaObjectHandler接口实现insertFill和updateFill方法。典型场景：createTime/createUser在插入时自动填充当前时间和当前用户ID，updateTime/updateUser在更新时自动填充。MP在执行insert/update前会调用MetaObjectHandler，检查字段上@TableField的fill属性（INSERT/UPDATE/INSERT_UPDATE），匹配则自动设置值。当前用户信息通常从ThreadLocal（如RequestContextHolder）获取。</p>', 1, 6, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q300. MyBatis-Plus的分页插件内部实现及与PageHelper的对比？</p>', '<p>答案解析：MyBatis-Plus的分页插件（PaginationInnerInterceptor）也是基于MyBatis的拦截器（Interceptor）实现。区别：1、使用方式——PageHelper通过静态方法startPage()设置，MP通过传入Page对象：`IPage<User> page = userMapper.selectPage(new Page<>(1,10), queryWrapper);`。<br/>2、分页参数传递——PageHelper用ThreadLocal，MP直接用方法参数，MP方式更安全（不影响其他线程）。<br/>3、多查询支持——PageHelper的startPage()只对紧接着的下一条SQL生效，中途有别的查询会被分页；MP明确指定哪个查询要分页。<br/>4、SQL改写——两者都是在原始SQL外层包COUNT查总数，末尾加LIMIT，本质机制相同。<br/>5、生态——MP分页是内置功能，与MP的条件构造器、通用CRUD无缝合；PageHelper可配合原生MyBatis或MP使用。推荐：用MyBatis-Plus就用它自带的分页插件，生态统一。不用MP的纯MyBatis项目用PageHelper。</p>', 1, 6, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q301. MyBatis拦截器（Interceptor）的原理及可拦截哪些对象？</p>', '<p>答案解析：MyBatis拦截器通过动态代理（JDK代理）实现，可拦截以下四种对象：1、Executor——拦截SQL执行过程（update/query/commit/rollback），PageHelper和MP分页插件就是拦截Executor.query()。<br/>2、StatementHandler——拦截SQL构建和参数设置（prepare/parameterize/batch/update/query），最底层，可修改最终SQL。<br/>3、ParameterHandler——拦截参数设置过程（setParameters）。<br/>4、ResultSetHandler——拦截结果集处理（handleResultSets/handleOutputParameters），可对查询结果做统一加工。实现步骤：①实现Interceptor接口，覆写intercept()方法；<br/>②在intercept方法中通过Invocation.getTarget()获取被拦截对象，通过Invocation.proceed()执行原逻辑；<br/>③使用@Intercepts和@Signature注解指定拦截的目标对象、方法、参数类型；<br/>④注册拦截器（XML或@Bean）。典型应用：分页插件、SQL执行时间监控（慢SQL记录）、数据脱敏（对查询结果的手机号/身份证做脱敏处理）、读写分离（根据SQL类型选择数据源）。</p>', 1, 6, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q302. MyBatis如何处理枚举类型的映射？</p>', '<p>答案解析：默认情况下MyBatis用Enum.name()（枚举常量名如"MALE"）映射数据库字符串值，或用Enum.ordinal()（枚举次序如0、1）映射数值。两种默认方式都不理想：name无法反映中文含义；ordinal顺序改变会导致数据错乱。推荐自定义TypeHandler：继承BaseTypeHandler<枚举类型>，在setNonNullParameter中将Java枚举转为自定义code（如数据库存0/1或"男"/"女"），在getNullableResult中根据数据库值映射回枚举。配置方式：①全局mybatis-config.xml中注册typeHandler；<br/>②Mapper XML中resultMap的result标签指定typeHandler；<br/>③或者使用MP的@EnumValue注解——在枚举类中指定一个字段标记为实际存储的值，MP自动处理映射。通用最佳实践：枚举类定义code字段+静态方法getByCode(code)，数据库存code值，通过TypeHandler转换。避免直接用枚举的name或ordinal与数据库交互。</p>', 1, 6, 0, 0, NULL, CURRENT_TIMESTAMP);-- Part 7: 数据库与缓存 (tag=7, 26条)
INSERT INTO `t_knowledge` (`question`, `answer`, `status`, `tag`, `del_flag`, `view_count`, `last_view_time`, `add_time`) VALUES
('<p>Q303. MySQL事务ACID四大特性的实现机制分别是什么？</p>', '<p>答案解析：原子性（Atomicity）：事务不可分割，所有操作要么全成功要么全回滚。通过undo log（回滚日志）实现——每条修改前记录旧数据到undo log，回滚时根据undo log恢复。一致性（Consistency）：事务前后数据完整性约束不变。是事务的根本目标，由原子性+隔离性+持久性共同保障，辅以约束（主键、外键、唯一索引、NOT NULL等）。隔离性（Isolation）：多事务并发执行互不干扰。通过MVCC（多版本并发控制）+锁机制实现。持久性（Durability）：事务提交后数据永久保存。通过redo log（重做日志）实现——修改先写入redo log再写入磁盘，掉电后从redo log恢复。InnoDB的WAL（Write Ahead Logging先写日志）机制保证了持久性：每次修改先写redo log buffer→写redo log文件→再异步刷新数据页到磁盘。即使数据页没来得及写磁盘，崩溃后也能通过redo log恢复。</p>', 1, 7, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q304. MySQL中脏读、不可重复读、幻读的区别？各自如何解决？</p>', '<p>答案解析：脏读：事务A读到事务B已修改但尚未提交的数据。如果B回滚，A读到的是无效的"脏数据"。解决：将隔离级别提升到READ COMMITTED（读已提交）。不可重复读：事务A内两次查询同一行数据，结果不一致（期间被事务B修改并提交）。重点在"同一行数据的值变了"。解决：将隔离级别提升到REPEATABLE READ（可重复读，MySQL默认级别，通过MVCC快照读实现）。幻读：事务A内两次范围查询，第二次多出了一些行或少了一些行（事务B在此期间插入或删除了数据）。重点在"结果行数变了"。MySQL在REPEATABLE READ下通过Next-Key Lock（间隙锁+行锁）部分解决了幻读（当前读时），但快照读不受影响。完全解决需要SERIALIZABLE（串行化）。实际项目中REPEATABLE READ配合MVCC和间隙锁已足够应对绝大多数场景。</p>', 1, 7, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q305. InnoDB中B+树索引为什么比B树更适合做数据库索引？</p>', '<p>答案解析：B+树相对B树的四个关键优势：1、非叶子节点不存数据只存索引键——B+树内部节点只存key不存data，一个节点能存更多key，树更矮，磁盘IO次数更少。B树的非叶子节点也要存data，节点能存的key少。<br/>2、所有数据都在叶子节点且形成有序链表——B+树叶子节点串联为一个双向链表，范围查询（如WHERE id BETWEEN 10 AND 100）直接遍历链表，无需回溯非叶子节点。B树范围查询需要中序遍历整棵树来回跳跃。<br/>3、查询时间复杂度稳定为O(log n)——B+树所有查询都走到底（叶子节点），性能稳定。B树最好O(1)（根节点直接命中）、最差O(log n)，不稳定。<br/>4、全表扫描和排序查询高效——B+树叶子链表天然有序，ORDER BY走索引时直接遍历无需额外排序。MySQL InnoDB的聚簇索引使用B+树（非聚簇索引也是B+树，叶子存主键值），这也是MySQL默认引擎选择InnoDB+使用B+树的原因。</p>', 1, 7, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q306. 聚簇索引和非聚簇索引的区别？回表是什么？</p>', '<p>答案解析：聚簇索引（主键索引）：索引的叶子节点存储的是完整的行数据。InnoDB中表数据文件本身就是按B+树组织的聚簇索引结构——"索引即数据"。一张表只有一个聚簇索引（就是主键）。非聚簇索引（二级索引/辅助索引）：索引的叶子节点存储的是主键值，而非完整行数据。通过非聚簇索引查找完整行数据需要"回表"——先在二级索引的B+树中找到主键值，再拿着主键值去聚簇索引的B+树中查完整行数据。回表是额外的IO开销，所以要减少回表。覆盖索引就是利用这个原理——SELECT的字段全部包含在二级索引中（包括主键），查询不需要回表，直接从二级索引获取所有数据。InnoDB建表时必须指定主键：有显式主键用它；没有显式主建则选第一个唯一索引作为聚簇索引；都没有则自动生成一个隐藏的ROW_ID作为聚簇索引（6字节，对用户不可见）。</p>', 1, 7, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q307. 覆盖索引是什么？什么场景下使用？</p>', '<p>答案解析：覆盖索引是指查询的列恰好都在索引中包含（SELECT的字段+WHERE条件字段+ORDER BY字段+GROUP BY字段全部被某个索引覆盖），不需要回表查聚簇索引即可获得全部数据。效果：减少一次回表IO，查询效率大幅提升。EXPLAIN中Extra列显示Using index表示使用了覆盖索引。实现方式：建立合理的联合索引，让索引包含所有查询所需字段。注意：不是把表中所有列都建到一个索引，那会变成又大又慢的索引。只在高频查询的少数关键字段上建立覆盖索引。典型场景：`SELECT id, username FROM user WHERE email=?`——创建联合索引(email, username, id)即可实现覆盖查询（id在二级索引中天然存在）。注意：主键值自动存在于所有二级索引的叶子节点中，所以SELECT主键也就覆盖了。覆盖索引是日常SQL优化最有效、成本最低的手段之一。</p>', 1, 7, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q308. 联合索引的最左前缀原则详解？如何设计？</p>', '<p>答案解析：联合索引(a, b, c)的索引结构是——先按a排序，a相同则按b排序，b相同按c排序。最左前缀原则：查询条件必须从联合索引的最左列开始匹配，且不能跳过中间列。a生效→索引可用；(a,b)生效→索引可用；(a,b,c)生效→索引可用；b不生效（没匹配a）→索引失效；c不生效（跳过a和b）→索引失效；(a,c)中只有a生效（跳过了b，c用不上）。ORDER BY / GROUP BY同样遵循此规则。设计原则：1、区分度高的列放左边（过滤性强的字段前置，最大限度缩小扫描范围）。<br/>2、常用单列查询的字段放左边（如多个查询分别查(a)和(a,b)，则索引(a,b)两者都能覆盖）。<br/>3、范围查询的列放最后——a=1 AND b>2 AND c=3，最左匹配到b（b是范围查询），c的等值查询无法使用索引（范围列之后的索引列失效）。实际优化中，把=和IN放在前面、范围查询放在末尾即可。</p>', 1, 7, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q309. MySQL索引失效的常见场景有哪些？</p>', '<p>答案解析：最常见八种失效场景：1、LIKE以%开头——`LIKE ''''%xxx''''`无法使用索引（B+树有序，前缀模糊无法定位）。反向LIKE `''''xxx%''''`可用索引。<br/>2、索引列参与运算或函数——`WHERE YEAR(create_time)=2024`、`WHERE age+1=20`都不会走索引。应改为`WHERE create_time BETWEEN ''''2024-01-01'''' AND ''''2024-12-31''''`。<br/>3、隐式类型转换——varchar字段用数字匹配，`WHERE phone=13800138000`（phone是varchar，查询用数字，MySQL会把索引字段隐式转换导致索引失效）。必须用引号。<br/>4、OR连接非索引列——`WHERE a=1 OR b=2`，如果b没有索引，整个WHERE都不会走索引。改为UNION ALL两个有索引的单列查询。<br/>5、NOT IN / <> / NOT EXISTS——不等于操作通常不走索引（优化器可能认为全表更快）。<br/>6、联合索引不满足最左前缀。<br/>7、IS NULL / IS NOT NULL——视数据分布而定，大部分行非空时走索引无意义。<br/>8、使用!=、<>比较。总体原则：让索引列保持"干净"（不运算、不函数）、WHERE条件类型匹配联合索引的最左列即可。</p>', 1, 7, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q310. MVCC多版本并发控制的实现原理？ReadView是什么？</p>', '<p>答案解析：MVCC是InnoDB实现"读不加锁、读写不冲突"的核心机制。每条行记录都隐藏三个列：DB_TRX_ID（最后修改该行的事务ID）、DB_ROLL_PTR（回滚指针，指向undo log中的旧版本）、DB_ROW_ID（隐藏主键）。undo log保存了每条数据修改前的历史版本，并通过DB_ROLL_PTR形成版本链。ReadView是快照读时生成的"视图"，核心字段包括：m_ids（当前活跃事务ID列表）、min_trx_id（活跃事务最小ID）、max_trx_id（下一个将分配的事务ID）、creator_trx_id（创建ReadView的事务ID）。判断规则：行记录的DB_TRX_ID < min_trx_id→可见（修改该行的事务已提交）；DB_TRX_ID >= max_trx_id→不可见（未来的事务）；在m_ids中→不可见（活跃事务）。REPEATABLE READ下ReadView在事务第一个快照读时生成且整个事务复用（保证可重复读）；READ COMMITTED下每次快照读都重新生成ReadView（可读到已提交的修改）。</p>', 1, 7, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q311. MySQL InnoDB的行级锁有哪些类型？</p>', '<p>答案解析：InnoDB实现了三种行级锁算法：1、Record Lock（记录锁）——锁定单行索引记录，SELECT ... FOR UPDATE / UPDATE / DELETE对匹配的行加Record Lock。锁的是索引记录而非数据行本身（没有索引的行直接升级为表锁）。<br/>2、Gap Lock（间隙锁）——锁定索引记录之间的间隙（左开右开区间），防止其他事务在这些间隙中插入数据。只在REPEATABLE READ隔离级别下生效。<br/>3、Next-Key Lock（临键锁）——Record Lock + Gap Lock的组合（左开右闭区间），锁定一条索引记录及其前面的间隙。InnoDB默认的加锁策略。作用：防止幻读——范围查询时，间隙锁阻止其他事务插入符合范围条件的新行，保证再次范围查询得到相同的行数。共享锁（S锁）：允许其他事务读，禁止其他事务获取X锁。排他锁（X锁）：禁止其他事务获取任何锁。SELECT默认不加锁（快照读MVCC），加锁读需用SELECT ... FOR UPDATE（X锁）或SELECT ... LOCK IN SHARE MODE（S锁）。</p>', 1, 7, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q312. MySQL explain执行计划如何解读？重点关注哪些字段？</p>', '<p>答案解析：EXPLAIN的九个关键字段：1、type（访问类型，最重要）——性能从好到差：system>const（主键等值）>eq_ref（关联查询唯一匹配）>ref（索引等值）>range（索引范围）>index（全索引扫描）>ALL（全表扫描，最差）。优化目标至少到range，最好到ref。<br/>2、key——实际使用的索引名，NULL表示没用到索引。<br/>3、key_len——索引使用的字节数，可判断联合索引用了哪几列。<br/>4、rows——MySQL估算需要扫描的行数，越小越好。<br/>5、Extra（额外信息）——Using index（覆盖索引，最佳）、Using where（用WHERE过滤，一般）、Using temporary（用了临时表，需要优化，如GROUP BY没走索引）、Using filesort（文件排序，需要优化，如ORDER BY没走索引）、Using join buffer（join的关联字段没索引）。<br/>6、possible_keys——可能用到的索引。<br/>7、ref——索引等值匹配的列或常量。<br/>8、filtered——按表条件过滤后剩余行数的百分比。<br/>9、partitions——命中的分区。调优口诀：type最好在range及以上、key不为NULL、Extra避免filesort和temporary、rows越小越好。</p>', 1, 7, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q313. MySQL主从复制的原理？如何解决主从延迟？</p>', '<p>答案解析：主从复制三步流程：1、Master的binlog dump线程——主库将所有数据变更写入binlog（二进制日志），当从库连接时，dump线程读取binlog并发送给从库。<br/>2、Slave的I/O线程——从库启动后创建I/O线程，连接主库，接收主库发送的binlog更新，写入从库本地的relay log（中继日志）。<br/>3、Slave的SQL线程——读取relay log中的更新事件，在从库上重放执行，完成数据同步。主从延迟原因：从库单SQL线程串行执行（MySQL 5.6及之前）、从库机器性能弱于主库、大事务阻塞、网络延迟。解决方案：1、MySQL 5.7并行复制——按库级别并行执行（不同库的事务可并行回放）；<br/>2、MySQL 8.0基于WriteSet的并行复制（更细粒度）；<br/>3、拆分大事务为小事务；<br/>4、从库使用更强硬件；<br/>5、强制读主库——对实时性要求极高的操作走主库查询；<br/>6、读写分离中间件（Sharding-JDBC）配置"主从同步后才可读"。</p>', 1, 7, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q314. 分库分表有哪些策略？各自如何实现？</p>', '<p>答案解析：垂直分库：按业务模块将不同表拆到不同库（用户库、订单库、商品库），每个库的表结构不同。解决单库连接数压力和部分热点表的CPU压力。垂直分表：将一张宽表按列拆分（主表存常用字段，扩展表存大字段和不常用字段），用主键关联。减少单行数据大小，提高缓存命中。水平分库：将同一张表的数据按分片键散列到多个库（每个库存一部分数据）。用于单库容量不足的场景。水平分表：同库内将大表按分片键拆为多个子表（user_0、user_1、user_2）。四种分片算法：1、取模（key%N）——范围均匀但扩容需迁移数据；<br/>2、范围分片（1~1000、1001~2000）——扩容简单但可能有热点；<br/>3、一致性哈希——扩缩容影响数据少（只影响相邻节点）；<br/>4、基于日期（按月/年分表）——适合日志、流水等按时间查询的数据。常用Sharding-JDBC实现代码层分库分表（无侵入中间件），或MyCat实现代理层分库分表。分片键选择是核心——选访问频率最高的查询条件作为分片键。</p>', 1, 7, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q315. Redis五种基础数据类型及各自使用场景？</p>', '<p>答案解析：1、String——最基本类型，可存字符串、数字、序列化JSON。场景：分布式缓存（对象JSON）、计数器（INCR）、分布式锁（SETNX）、分布式ID生成、限流（INCR+EXPIRE）。<br/>2、Hash——键值对集合（field-value），适合存储对象。场景：用户信息缓存（`HSET user:1001 name "张三" age 25`），比String存JSON的好处是可按字段更新而无需序列化整个对象。<br/>3、List——双向链表，支持两端操作。场景：消息队列（LPUSH+RPOP或BRPOP阻塞消费）、最新消息列表、分页列表。<br/>4、Set——无序不重复集合。场景：标签系统、好友关系（SINTER交集求共同好友）、抽奖去重（SADD+SRANDMEMBER）、UV统计。<br/>5、ZSet——有序集合，每个元素有score排序。场景：排行榜（ZADD+ZREVRANGE实时排行）、延迟队列（score=执行时间戳）、带权重的集合、分页排序。选择原则：对象用Hash、去重用Set、排序用ZSet、简单KV用String、队列用List。</p>', 1, 7, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q316. Redis缓存穿透、击穿、雪崩分别是什么？如何解决？</p>', '<p>答案解析：缓存穿透：查询一个一定不存在的数据（如id=-1），因为缓存查不到就去查数据库，数据库也查不到所以不写缓存。大量恶意请求直接打到数据库。解决方案：1、布隆过滤器——将所有可能存在的数据hash到一个bitmap中，查询前先在布隆过滤器中判断（不存在直接返回，不查缓存和DB）；<br/>2、缓存空值——查不到的key也缓存空值（过期时间设短如5分钟）；<br/>3、接口层做参数校验（id必须>0）。缓存击穿：热点key过期瞬间，大量并发请求穿透缓存直击数据库。解决方案：1、互斥锁——第一个未命中缓存的请求获取分布式锁去查DB，其他请求等待；<br/>2、热点key永不过期——逻辑过期（异步线程定期刷新缓存）；<br/>3、提前预热——在活动开始前预加载热点数据到缓存。缓存雪崩：大量key在同一时间过期或Redis集群宕机。解决方案：1、过期时间随机打散（基础TTL+随机值）；<br/>2、Redis集群高可用（主从+哨兵）；<br/>3、多级缓存（本地缓存+Redis）；<br/>4、熔断降级（缓存不可用时直接返回兜底数据或限流保护DB）。</p>', 1, 7, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q317. Redis的过期删除策略和内存淘汰机制？</p>', '<p>答案解析：过期键删除策略（三种结合）：1、惰性删除——每次访问key时检查是否过期，过期则删除。节省CPU，但如果key一直没人访问会一直占用内存。<br/>2、定期删除——每隔100ms随机抽取一批key检查并删除过期key（不是全量扫描，每次抽20个）。平衡CPU和内存。<br/>3、内存淘汰策略（maxmemory-policy）——内存达到maxmemory上限时触发，共8种。核心4种：volatile-lru（从设置了过期时间的key中淘汰最近最少使用的）、allkeys-lru（从所有key中淘汰LRU，推荐）、volatile-ttl（淘汰即将过期的key）、noeviction（默认，不淘汰，写入直接报错，一般不用）。LRU算法（近似版）：Redis不实现精确LRU（开销大），而是随机采样5个key淘汰其中最不常访问的（样本越大越接近精确LRU）。LFU（Least Frequently Used，Redis 4.0+）：按访问频率淘汰（allkeys-lfu/volatile-lfu），适合有冷热数据区分的场景。</p>', 1, 7, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q318. Redis分布式锁的实现及Redisson的看门狗机制？</p>', '<p>答案解析：基于Redis的分布式锁核心命令：`SET key value NX EX 30`，NX保证互斥（key不存在才设置成功），EX设置过期时间防止死锁。解锁时用Lua脚本保证原子性（先GET比较value是否自己的，再DEL）。简单实现有两大问题：1、锁过期时间不好定——业务执行时间可能超过过期时间导致锁自动释放，其他线程获取锁引起并发安全问题。<br/>2、主从切换时锁丢失——主节点宕机，从节点未同步锁信息就晋升为主，其他线程可获取同一把锁。Redisson的解决方案：看门狗（Watchdog）机制——加锁后启动后台线程，每隔10秒（internalLockLeaseTime/3）检查锁是否还被当前线程持有，是则自动续期（重置为30秒），业务执行多久锁就持有多久。Redisson基于Lua脚本和Hash结构实现可重入锁（hash的field是线程ID，value是重入次数）。生产级分布式锁方案：单机Redis用Redisson（性能好、易用），金融级强一致性用ZooKeeper（顺序节点+Watch，CP模型），或使用RedLock算法（多Redis节点过半加锁，但较复杂）。</p>', 1, 7, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q319. Redis持久化RDB和AOF有什么区别？如何选择？</p>', '<p>答案解析：RDB（快照持久化）：在指定的时间间隔生成内存数据的全量快照，保存到dump.rdb二进制文件。触发方式：SAVE（主线程阻塞，不推荐）、BGSAVE（fork子进程异步保存）。优点：文件紧凑（压缩二进制）、恢复速度快、对性能影响小（子进程写入）。缺点：两次快照之间的数据可能丢失（无法做到秒级持久化）、fork子进程在大数据量时耗时长可能阻塞主线程。AOF（追加日志）：记录每一次写操作命令，追加到AOF文件末尾。同步策略：always（每次写同步，最安全最慢）、everysec（每秒同步，推荐，折中）、no（由操作系统决定）。优点：数据安全（最多丢失1秒数据）、AOF文件内容是可读的Redis命令。缺点：AOF文件体积大于RDB、恢复速度慢、QPS可能受fsync影响。最佳实践：两者结合——RDB做冷备份（如每天一次全量备份），AOF做增量持久化（确保最多丢秒级数据）。Redis 4.0+支持混合持久化——AOF重写时子进程以RDB格式写入当前数据，后续增量以AOF格式追加，兼顾恢复速度和数据安全。</p>', 1, 7, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q320. Redis集群模式对比？哨兵模式原理？</p>', '<p>答案解析：四种模式：1、单机——简单无高可用，适合开发/测试。<br/>2、主从复制——主节点读写，从节点只读异步复制主库数据。读写分离分担读压力，但主节点宕机需手动切换，无自动故障转移。<br/>3、哨兵（Sentinel）模式——在主从基础上增加了哨兵集群，哨兵通过PING监控主从节点，当主节点主观下线（1个哨兵判定）+客观下线（半数以上哨兵同意）后，哨兵集群投票选出leader哨兵执行故障转移（把某个从节点提升为新主节点，其他从节点切换到新主节点，通知客户端新地址）。哨兵至少3个节点保证选举有效性。<br/>4、集群（Cluster）模式——将数据按hash slot分片（CRC16%16384分配到不同主节点），每个主节点负责一部分槽位，支持横向扩展（增加节点重新分配槽位）。自带故障转移（主节点挂后从节点自动提升）。选型：数据量不大+高可用→哨兵模式；数据量大（百GB+）或高吞吐→集群模式；读写分离→主从+哨兵。</p>', 1, 7, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q321. 缓存一致性如何保证？双写模式的问题？</p>', '<p>答案解析：缓存一致性是分布式系统最难的问题之一——数据库和Redis的数据如何保持一致。常用策略：1、Cache Aside Pattern（旁路缓存，最常用）——读：先查缓存，未命中查DB并回写缓存；写：先更新DB，然后删除缓存（不是更新缓存，因为更新缓存可能产生并发写覆盖）。延迟双删策略：先删缓存→更新DB→延迟几百毫秒再删一次缓存（消除并发读写的脏数据）。<br/>2、Read/Write Through——缓存层代理读写，读写都经过缓存统一操作（较少用）。<br/>3、Write Behind（异步写入）——先写缓存，异步批量写DB（性能高但有丢失风险）。为什么是删缓存而非更新缓存：更新缓存需要复杂计算；并发更新可能产生脏数据（线程A更新DB→线程B更新DB→线程B更新缓存→线程A更新缓存，最终缓存是A的旧值）。删缓存则不存在顺序问题（下一个请求查缓存miss<>查DB写最新数据）。兜底方案：设置合理的过期时间（最终一致性兜底）+ 通过Canal监听MySQL binlog异步更新缓存（更可靠）。</p>', 1, 7, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q322. Redis为什么这么快？单线程模型如何支持高并发？</p>', '<p>答案解析：Redis快的六大原因：1、纯内存操作——数据存在内存中，读写速度是纳秒级（磁盘是毫秒级）。<br/>2、单线程模型——避免了多线程的上下文切换、锁竞争、死锁等开销，CPU不用耗费在线程调度上。<br/>3、IO多路复用——单线程通过epoll/kqueue同时监听多个客户端连接（类似NIO），哪个连接有数据到达就处理哪个，一套线程处理数万并发连接。<br/>4、高效的数据结构——每种数据结构都经过专门优化（SDS简单动态字符串、ziplist压缩列表、quicklist快速列表、skiplist跳表等），紧密存储减少内存碎片。<br/>5、RESP协议简单——Redis序列化协议简洁高效，解析快。<br/>6、避免额外开销——不提供通用的查询语言，功能限定明确。单线程注意点：Redis使用单线程处理网络IO和命令执行，但耗时命令（KEYS *、FLUSHALL、大集合的交并集运算）会阻塞所有其他请求。因此生产禁掉KEYS，用SCAN替代；大集合运算放在从节点执行。Redis 6.0+引入多线程IO（网络读写多线程，命令执行仍是单线程），进一步提升吞吐。</p>', 1, 7, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q323. 数据库慢SQL优化的通用流程和方法？</p>', '<p>答案解析：通用优化流程：1、开启慢查询日志（`SET GLOBAL slow_query_log=ON`，设置long_query_time=1s），或用性能监控工具（Prometheus+MySQL Exporter、Druid连接池的慢SQL监控）定位Top慢SQL。<br/>2、EXPLAIN分析执行计划，重点关注type（避免ALL/index）、key（是否使用索引）、rows（扫描行数）、Extra（避免filesort/temporary）。<br/>3、优化方向：加索引（WHERE/JOIN/ORDER BY/GROUP BY字段）、消除索引失效场景（函数、类型转换、左模糊）、减少回表（覆盖索引）、改写SQL（拆分大JOIN为简单查询、用UNION ALL代替OR、用LIMIT限制结果集）、数据库层优化（调整innodb_buffer_pool_size缓冲池大小使热数据在内存中）。<br/>4、压测验证：用相同数据量和SQL在生产从库上压测对比优化前后耗时。<br/>5、定期Review——慢查询日志定期分析，新功能上线后观察是否有新慢SQL。日常开发习惯：Select只查需要的字段、大表查询必须走索引、避免在循环中查询DB、批量操作代替循环单条操作。</p>', 1, 7, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q324. MySQL redo log和undo log的作用与区别？</p>', '<p>答案解析：redo log（重做日志）：物理日志，记录数据页的物理修改（"对表空间X、页Y、偏移量Z写入数据W"）。作用：保证事务持久性——提交时先写redo log再异步刷数据页到磁盘。如果MySQL崩溃，重启时读取redo log重做已提交未刷盘的修改。redo log是InnoDB引擎独有的，循环写入（固定大小如4GB），写满后触发checkpoint强制刷脏页到磁盘。undo log（回滚日志）：逻辑日志，记录数据的逻辑变化（"把某行的某列从值A改为值B"），用于回滚。作用：保证原子性——回滚时根据undo log执行逆操作恢复数据；支撑MVCC——undo log保存数据的历史版本链，快照读通过undo log获取历史版本。undo log是逻辑日志，记录在共享表空间中，也会产生redo log（undo log的修改也需要持久化，所以undo操作也会写redo log）。两者配合：修改数据时→先写undo log（用于回滚）→修改内存数据页→写redo log（用于恢复）。提交时redo log刷盘，undo log不需要立即清理（MVCC需要）。</p>', 1, 7, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q325. 数据库乐观锁和悲观锁的SQL实现及业务选择？</p>', '<p>答案解析：悲观锁实现：`SELECT stock FROM product WHERE id=1 FOR UPDATE`——在事务中使用SELECT ... FOR UPDATE对查到的行加排他锁，其他事务必须等待当前事务提交后才能读取或修改。注意：必须在事务中，否则FOR UPDATE不生效；查询必须走索引，否则行锁升级为表锁；锁定后尽快提交（事务不宜过长）。适用场景：冲突率高（如秒杀核心扣库存），写多读少。乐观锁实现：表中加version字段（INT类型），更新时校验版本号——`UPDATE product SET stock=stock-1, version=version+1 WHERE id=1 AND version=旧版本号`。更新影响行数为0说明版本号变了（被其他事务修改），业务层捕获后重试或提示用户。适用场景：冲突率低，读多写少。选择标准：冲突概率低（<20%）用乐观锁（无锁阻塞、并发高）；冲突概率高用悲观锁（避免大量重试浪费资源）。实际项目建议：先用乐观锁（代码简单、性能好），压测发现重试太多再考虑悲观锁。</p>', 1, 7, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q326. InnoDB和MyISAM引擎的核心区别？为什么InnoDB成为默认？</p>', '<p>答案解析：九大核心区别：1、事务——InnoDB支持（ACID），MyISAM不支持。<br/>2、锁粒度——InnoDB支持行锁（并发高），MyISAM只有表锁（并发低）。<br/>3、外键——InnoDB支持，MyISAM不支持。<br/>4、MVCC——InnoDB支持多版本并发控制，读不加锁；MyISAM读也加共享锁。<br/>5、崩溃恢复——InnoDB通过redo log崩溃后自动恢复，MyISAM崩溃后数据损坏概率高、恢复慢（需repair table）。<br/>6、索引结构——InnoDB聚簇索引（数据即索引），MyISAM非聚簇索引（索引和数据分开存储，索引叶子存数据文件地址）。<br/>7、全文索引——MyISAM原生支持，InnoDB 5.6+支持。<br/>8、COUNT(*)——MyISAM直接读元数据（快），InnoDB需要扫描索引统计（慢，但8.0+有优化）。<br/>9、压缩——MyISAM支持压缩只读表，InnoDB支持页压缩。InnoDB成为默认（MySQL 5.5+）的原因：事务支持是数据库核心需求、行锁支撑高并发读写、崩溃后自动恢复保障数据安全。仅少数场景MyISAM略好（只读压缩表、日志归档），但也已被TokuDB/Archive等替代。</p>', 1, 7, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q327. MySQL死锁产生的原因、排查和预防？</p>', '<p>答案解析：死锁产生：两个事务互相持有对方需要的锁并等待对方释放，形成循环等待。典型场景：事务A先锁记录1再锁记录2，事务B先锁记录2再锁记录1——同时执行时，A持有1等待2，B持有2等待1，死锁成环。排查：执行`SHOW ENGINE INNODB STATUS`查看LATEST DETECTED DEADLOCK部分，包含死锁涉及的事务、锁类型（X锁/S锁）、执行的SQL语句、被回滚的事务。也可通过`SELECT * FROM information_schema.INNODB_TRX`查看当前活跃事务。预防方案：1、统一加锁顺序——所有事务都按相同顺序访问资源（如先锁主表再锁从表，按ID升序加锁）。<br/>2、缩短事务——事务内只做必要操作，减少锁持有时间。<br/>3、使用索引——无索引会导致行锁升级为表锁，锁范围变大冲突概率增加。<br/>4、大事务拆分——将大事务拆为多个小事务（确保业务原子性）。<br/>5、降低隔离级别——READ COMMITTED下间隙锁不生效（减少锁范围）。InnoDB的死锁检测机制默认开启（innodb_deadlock_detect=ON），检测到死锁会自动回滚持有最少行锁的事务。</p>', 1, 7, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q328. 数据库读写分离的实现及数据延迟问题的处理？</p>', '<p>答案解析：读写分离架构：主库处理INSERT/UPDATE/DELETE写操作，多个从库处理SELECT读操作（通过主从复制保持数据同步）。实现方式：1、Sharding-JDBC代码层——配置主从数据源，框架根据SQL类型自动路由（写走主库、读走从库）。<br/>2、MyCat中间件代理层——应用连接MyCat，MyCat解析SQL后路由到对应库。<br/>3、Spring AbstractRoutingDataSource——通过ThreadLocal存放数据源类型，AOP拦截Service方法切换数据源。主从延迟问题处理：1、强制读主库——刚写入的数据立即查询走主库（如订单创建后立即跳转详情页）。<br/>2、延迟阈值——从库延迟超过N秒时自动切回主库查询。<br/>3、等待同步——写入后等待N ms再查询（不可靠）。<br/>4、缓存兜底——写入时同步更新Redis缓存，查询走缓存不走从库。Sharding-JDBC的HintManager可强制指定本次操作走主库：`HintManager.getInstance().setMasterRouteOnly()`。</p>', 1, 7, 0, 0, NULL, CURRENT_TIMESTAMP);-- Part 8: 微服务架构 (tag=8, 17条)
INSERT INTO `t_knowledge` (`question`, `answer`, `status`, `tag`, `del_flag`, `view_count`, `last_view_time`, `add_time`) VALUES
('<p>Q329. 微服务架构的优缺点及何时应该使用？</p>', '<p>答案解析：优点：1、服务解耦——按业务域拆分，每个服务独立开发、部署、扩容，不同服务可用不同技术栈。<br/>2、独立部署——修改一个服务不影响其他服务，发布速度快。<br/>3、故障隔离——某个服务宕机不会导致整个系统崩溃（配合熔断降级）。<br/>4、弹性扩容——可针对热点服务（如秒杀服务）单独扩容，而非整体扩容。<br/>5、团队自治——每个小团队负责一个或多个微服务，减少协调成本。缺点：1、分布式复杂度——分布式事务、网络延迟、服务间调用失败处理。<br/>2、运维成本高——需要注册中心、配置中心、网关、链路追踪、日志收集等基础设施。<br/>3、调试困难——一个请求跨多个服务，排查问题需要链路追踪。<br/>4、数据一致性——拆库后需要处理分布式事务。使用判断：团队少于10人→单体；业务逻辑复杂且多模块独立→微服务；用户量和并发快速增长→微服务；初创期快速验证→单体先行，规模大了再拆分。</p>', 1, 8, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q330. Nacos作为注册中心和配置中心的原理？</p>', '<p>答案解析：Nacos（Dynamic Naming and Configuration Service）是阿里开源的注册中心+配置中心。注册中心原理（AP模型）：服务提供者启动时向Nacos Server发送注册请求（包含IP、端口、服务名、元数据），Nacos存储服务实例信息。服务消费者启动时订阅所需服务，Nacos推送服务实例列表并定时同步（每5秒拉取变化）。服务提供者每5秒发送心跳续约，15秒无心跳标记不健康，30秒无心跳剔除。临时实例（默认）宕机自动剔除，持久实例需手动上下线。配置中心原理：应用启动时从Nacos拉取配置并缓存到本地，同时订阅配置变更。配置发布后Nacos通知所有订阅者（基于长轮询或gRPC），应用收到通知后刷新配置（@RefreshScope/@Value）。Nacos使用Raft协议保证配置一致性（CP模型，配置是强一致的），服务注册发现是AP模型（最终一致，可用性优先）。</p>', 1, 8, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q331. Spring Cloud Gateway网关的核心工作流程？</p>', '<p>答案解析：Gateway基于Netty+WebFlux实现响应式网关，异步非阻塞，核心流程：客户端请求到达→Gateway HandlerMapping根据配置的路由规则匹配（Route Predicate），决定将请求转发到哪个后端服务→请求经过一系列全局过滤器（GlobalFilter）和局部过滤器（GatewayFilter）处理→转发请求到目标微服务→响应回来再经过过滤器后置处理→返回客户端。路由规则核心三要素：id（路由标识）、uri（目标服务地址，lb://表示走负载均衡）、predicates（断言，匹配条件如Path=/api/user/**、Host、Method、Header等）、filters（过滤器，如StripPrefix去掉路径前缀、AddRequestHeader添加请求头、RequestRateLimiter限流）。常用场景：统一鉴权（Gateway全局过滤器校验JWT，放行登录接口）、跨域统一处理、请求日志、限流（令牌桶算法）、灰度路由（根据Header中的版本号路由到不同服务版本）、请求重写。</p>', 1, 8, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q332. OpenFeign的原理及如何配置超时和重试？</p>', '<p>答案解析：OpenFeign是声明式HTTP客户端，通过接口+注解的方式调用远程服务，无需手动拼URL和参数。原理：Spring在启动时为@FeignClient注解的接口创建JDK动态代理对象；调用接口方法时，代理对象根据方法上的@GetMapping/@PostMapping注解，将方法参数封装为HTTP请求（通过Ribbon获取服务实例地址，拼接完整URL），发送HTTP请求，将响应结果反序列化为方法返回值。超时配置：Feign的底层HTTP客户端默认是JDK的HttpURLConnection（无连接池），推荐替换为Apache HttpClient或OkHttp。配置`feign.client.config.default.connectTimeout=5000`和`readTimeout=10000`。如果集成了Ribbon，Ribbon的超时也会影响Feign（建议两者都配，取较小值生效）。重试：默认不重试GET请求，要开启需配置`spring.cloud.loadbalancer.retry.enabled=true`。注意：非幂等的POST请求不可重试（可能导致重复创建）。实际项目建议全局配置统一超时，关键接口可单独覆盖。</p>', 1, 8, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q333. Sentinel的限流、熔断、降级三大功能详解？</p>', '<p>答案解析：限流：控制单位时间内通过的请求数，保护系统不被流量冲垮。支持QPS限流（每秒请求数）和并发线程数限流（同时处理的线程数）。流量控制效果：直接拒绝（抛出FlowException）、Warm Up预热（系统刚启动时慢慢放开流量，避免冷系统被冲垮）、排队等待（匀速通过，请求排队不丢弃）。熔断：当服务的异常比例或慢调用比例超过阈值时，自动熔断该服务调用（快速失败不再调用，避免级联故障）。熔断状态：关闭（正常调用）→开启（熔断，直接失败）→半开（过一段时间尝试放一个请求试探，成功则关闭熔断，失败则继续保持开启）。降级：当某个服务不可用或被限流时，执行备选逻辑（fallback方法）返回兜底数据，保证核心流程不受影响。例如库存查询失败→降级返回默认库存为0。Sentinel控制台提供可视化规则配置、实时监控QPS/RT/异常，支持动态规则生效。</p>', 1, 8, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q334. 分布式事务的几种解决方案及优缺点？</p>', '<p>答案解析：1、2PC（两阶段提交）：XA协议，协调者先询问所有参与者是否可提交（prepare），都同意后再发commit。优点：强一致性。缺点：同步阻塞、单点故障（协调者挂了事务卡死）、性能差。主流方案：Seata AT模式（改良2PC）。<br/>2、TCC（Try-Confirm-Cancel）：Try阶段预留资源并检查，Confirm阶段确认执行业务，Cancel阶段释放预留资源。优点：无锁、性能好、最终一致性。缺点：代码侵入性强（每个接口都要实现Try/Confirm/Cancel三方法），开发复杂。<br/>3、可靠消息最终一致性：本地事务+消息表+MQ——执行业务的同时在本地事务中写一条消息记录到消息表，然后异步发送MQ，消费端做幂等处理。优点：无侵入、高可用。缺点：消息延迟、实现复杂（需定时任务扫描未成功发送的消息重试）。<br/>4、SAGA模式：将长事务分解为多个本地事务+T1、T2...Tn正向操作+C1、C2...Cn补偿操作。适合长流程业务。选型：大部分场景用Seata AT（无侵入）或可靠消息（异步解耦）；高一致性要求用TCC（如资金交易）。</p>', 1, 8, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q335. Seata AT模式的原理及优缺点？</p>', '<p>答案解析：Seata AT模式是基于两阶段提交的改良方案，最大优势：对业务代码无侵入（只需加@GlobalTransactional注解）。一阶段：执行各服务本地事务的SQL，Seata通过数据源代理（DataSourceProxy）拦截SQL，在执行前后分别记录镜像——before image（SQL执行前数据快照，用于全局回滚）和after image（SQL执行后数据快照，用于提交对比）。本地事务提交时，将undo_log（包含前后镜像）写入本地数据库的undo_log表，然后提交本地事务。二阶段：全局提交——TC（事务协调者）发送提交请求，各RM（资源管理器）删除对应的undo_log记录（异步批量）。全局回滚——TC发送回滚请求，各RM根据undo_log中的before image生成反向SQL（UPDATE回原始值、DELETE补偿INSERT等），回滚数据后删除undo_log。优缺点：对业务零侵入是最大优势；但性能开销大（额外写undo_log），依赖数据库（undo_log表），不适合高频写场景。与TCC互补：一般业务用AT，资金/高频场景用TCC。</p>', 1, 8, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q336. 接口幂等性如何保证？有哪些方案？</p>', '<p>答案解析：幂等性：同一个操作执行一次和执行多次的结果相同。需要幂等的场景：网络超时导致的重复请求、消息队列的重复消费、用户误操作多次点击提交按钮。核心方案：1、唯一标识+状态机——每次请求生成唯一ID（如订单号），处理前检查该ID是否已处理过。数据库加唯一索引（订单号），重复插入报唯一索引异常（业务捕获后返回成功）。<br/>2、Token令牌机制——提交前先获取Token（存Redis），提交时校验并删除Token（Redis的Lua脚本保证原子性：GET+DEL），删除成功才执行业务。Token只能被消费一次。<br/>3、乐观锁（版本号）——UPDATE时用版本号做条件，影响行数为0则说明被修改过，返回"请勿重复操作"。<br/>4、状态机判定——将业务状态定义为有限状态机，只允许特定状态的前进（如待支付→已支付→已发货），重复请求的同状态转换直接返回成功。<br/>5、数据库唯一约束——对业务唯一字段（如订单号、流水号）建唯一索引，重复插入时catch DuplicateKeyException返成功。推荐组合方案：唯一ID+数据库唯一索引或Redis校验做第一层防御，状态机做第二层业务逻辑防御。</p>', 1, 8, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q337. 微服务链路追踪的原理和SkyWalking的使用？</p>', '<p>答案解析：链路追踪解决的核心问题：一个前端请求在微服务内部可能跨多个服务，如何追踪完整调用链路、定位慢调用和异常。核心概念：Trace（一次完整请求的全局唯一ID，贯穿所有服务）、Span（一次服务调用的基本单元，包含调用开始时间、结束时间、操作名、状态）、Parent Span/Child Span（父调用/子调用关系）。SkyWalking原理：通过Java Agent字节码增强，在应用启动时植入探针，对HTTP、RPC、数据库、MQ等调用自动采集Trace和指标数据（无需代码埋点）。数据通过gRPC上报到SkyWalking OAP（后端分析引擎），存储到ElasticSearch/H2，最后通过SkyWalking UI可视化展示调用拓扑图、调用链详情、服务性能指标（平均响应时间、QPS、错误率）、慢SQL等。使用：启动脚本加`-javaagent:skywalking-agent.jar -DSW_AGENT_NAME=xxx-service`指定服务名，SkyWalking自动采集所有跨服务调用。排查实战：UI查看拓扑图找到红色（错误）或黄色（慢）的调用，点击钻取查看完整链路和每段耗时，定位是哪个服务的哪个方法慢。</p>', 1, 8, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q338. 配置中心解决什么问题？Nacos配置中心的用法？</p>', '<p>答案解析：配置中心解决传统配置文件管理的痛点：1、配置分散——每个服务有自己的application.yml，修改需要逐个服务改。<br/>2、修改需重启——应用内配置文件修改后必须重启服务才能生效。<br/>3、环境配置混乱——开发/测试/生产环境配置管理困难，容易混用。<br/>4、安全风险——数据库密码等敏感信息明文存在配置文件中，所有开发都能看到。Nacos配置中心用法：1、在Nacos控制台创建配置（Data ID=服务名-profile.yaml，Group=DEFAULT_GROUP）。<br/>2、应用配置bootstrap.yml中配置nacos.config.server-addr和namespace。<br/>3、获取配置：@Value配合@RefreshScope实现动态刷新（配置变更后自动更新变量值）；或通过@NacosValue注解。<br/>4、多环境隔离：通过namespace区分dev/test/prod（不同命名空间完全隔离）。<br/>5、敏感信息加密：使用配置加密插件（如jasypt），Nacos中存密文，应用启动时解密。配置优先级：Nacos配置 > 本地application.yml（Nacos优先）。灰度发布：通过配置中心逐步推送新配置到部分实例验证，确认无问题后全量发布。</p>', 1, 8, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q339. 微服务雪崩效应如何产生？如何预防？</p>', '<p>答案解析：雪崩效应——微服务A依赖B，B依赖C，假设C出现故障响应变慢或宕机，B调用C超时，B的线程资源被大量积压的请求占满，最终B也变得不可用；调用B的A也发生同样问题，故障逐级向上传递，最终整个系统瘫痪（如同滚雪球）。预防方案（层层防御）：1、服务熔断——当下游服务错误率/慢调用超过阈值，直接熔断停止调用（快速失败），避免无效请求堆积。Sentinel/Hystrix实现。<br/>2、服务降级——当服务被熔断或限流时，提供fallback兜底逻辑（如返回默认值、空列表、缓存数据）。<br/>3、接口限流——对入口请求做QPS限制，超过阈值的请求直接拒绝。<br/>4、超时控制——所有远程调用必须设置合理的超时时间（如连接超时2秒、读超时5秒），避免长时间阻塞。<br/>5、线程池隔离——为不同下游服务分配独立的线程池，某个下游慢不会占满全局线程。<br/>6、集群容错——多实例部署，单实例故障不影响整体。核心思想：假定依赖一定会出问题（墨菲定律），提前做好降级方案，不依赖"服务一直正常"的假设。</p>', 1, 8, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q340. Ribbon的负载均衡策略有哪些？工作原理？</p>', '<p>答案解析：Ribbon是客户端负载均衡器（运行在服务消费者进程中），从注册中心获取服务实例列表，调用时从列表中选一个实例发起请求。内置策略：1、轮询（RoundRobinRule）——依次轮询所有实例，默认策略。<br/>2、随机（RandomRule）——随机选一个实例。<br/>3、加权响应时间（WeightedResponseTimeRule）——根据每个实例的响应时间动态计算权重，响应快的权重高（类似Nginx的least_conn）。<br/>4、最佳可用（BestAvailableRule）——过滤掉处于断路器打开状态的实例，选并发请求最小的实例。<br/>5、可用性过滤（AvailabilityFilteringRule）——过滤掉不可用实例。<br/>6、区域感知（ZoneAvoidanceRule）——基于服务所在区域和可用性选择。工作原理：通过ILoadBalancer维护服务实例列表，定时从注册中心同步最新实例列表（每30秒），通过IPing检测实例存活。Spring Cloud在RestTemplate上添加@LoadBalanced注解即可自动集成Ribbon（自动通过服务名替换IP+端口）。注意：Spring Cloud 2020+中Ribbon已进入维护模式，官方推荐使用Spring Cloud LoadBalancer替代，但Ribbon在企业项目中仍大量使用。</p>', 1, 8, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q341. 单体架构拆分为微服务的拆分原则和步骤？</p>', '<p>答案解析：拆分原则：1、单一职责——一个服务只做一件事，按业务能力而非技术层拆分（订单服务、用户服务、支付服务，而非Controller层/Servic层/DAO层）。<br/>2、高内聚低耦合——服务内部功能高度相关，服务之间依赖尽量少，通过接口（API/MQ）解耦。<br/>3、数据独立——每个微服务有自己的数据库（独立schema或独立实例），禁止直接访问其他服务的数据库，只能通过API调用。<br/>4、边界上下文——参考DDD（领域驱动设计）划分服务边界，一个限界上下文对应一个微服务。<br/>5、先粗后细——先拆分为几个核心服务，运行稳定后再细拆，避免过度拆分。拆分步骤：①识别业务边界（订单域、用户域、商品域、支付域等）；<br/>②梳理依赖关系（哪些功能强依赖哪些）；<br/>③优先拆分边缘业务（无核心依赖、独立性强）；<br/>④灰度迁移逐步切流量（流量按比例从单体切到微服务）；<br/>⑤单体逐步退化为组合层或逐步废弃。注意避免的陷阱：微服务数量过多（管理复杂度爆炸）、拆得太细导致分布式事务泛滥、团队能力跟不上。</p>', 1, 8, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q342. 微服务服务间通信方式有哪些？各适用什么场景？</p>', '<p>答案解析：同步通信（RPC/REST）：请求-响应模式，调用方等待响应结果。1、OpenFeign+HTTP——声明式REST调用，简单通用，适合查询类（获取用户信息）和简单命令类（创建订单）。<br/>2、Dubbo+gRPC——高性能RPC框架，二进制协议，性能优于HTTP+JSON，适合高并发内部调用。<br/>3、缺点：双方必须同时在线，调用链路过长时延迟累积，服务强依赖。异步通信（消息队列）：发送消息后不等待结果，解耦服务。1、RabbitMQ/RocketMQ/Kafka——适合：异步处理（下单后异步扣库存、发短信）、削峰（秒杀请求先进MQ慢慢消费）、事件通知（用户注册后通知积分服务发放新人积分）、数据同步（Canal监听binlog同步到ES）。<br/>2、缺点：消息延迟、需要处理消息丢失和重复消费。选择标准：需要即时响应→同步通信；不需要即时响应或下游可能处理慢→异步通信；需要广播给多个服务→MQ发布订阅（Topic）；跨语言调用→HTTP REST（通用性最好）。</p>', 1, 8, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q343. 微服务网关的限流实现原理？常见限流算法有哪些？</p>', '<p>答案解析：三种常用限流算法：1、计数器（固定窗口）：一个时间窗口（如1分钟）内计数，超阈值拒绝。缺点：时间窗口临界点会出现流量突刺（前一个窗口最后一秒和下一个窗口第一秒集中通过两倍流量）。<br/>2、滑动窗口：把时间窗口细分为多个子窗口（如1分钟分为6个10秒窗口），窗口随时间滑动，统计所有子窗口的计数之和。比固定窗口更平滑，解决临界问题。<br/>3、令牌桶（最常用）：以一个恒定的速率向桶中放入令牌，请求到达时需要获取令牌才能被处理，无令牌时拒绝或排队。桶有容量上限（允许一定突发流量）。Guava RateLimiter实现单机令牌桶限流，Redis+Lua实现分布式令牌桶限流。Gateway的RequestRateLimiter过滤器默认使用Redis+Lua实现令牌桶。配置示例：`redis-rate-limiter.replenishRate: 10`（每秒生成10个令牌）、`redis-rate-limiter.burstCapacity: 20`（桶容量20，允许突发20个请求）。实际项目：网关层全局限流（防止整体流量过大）+ 单个服务限流（保护关键服务）组合使用。</p>', 1, 8, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q344. 微服务高可用架构设计应包含哪些方面？</p>', '<p>答案解析：高可用架构六大维度：1、服务冗余——所有服务至少双实例部署（不同物理机/可用区），无状态服务水平扩展。<br/>2、注册中心集群——Nacos/Eureka集群部署（至少3节点），确保注册中心本身高可用。<br/>3、网关高可用——Gateway多实例+Nginx负载均衡（Nginx本身做Keepalived主备）。<br/>4、熔断降级限流——Sentinel全链路防护，故障服务快速熔断，非核心功能降级兜底。<br/>5、数据层高可用——MySQL主从/集群+Redis哨兵/集群+MQ集群。<br/>6、监控告警——Prometheus+Grafana监控CPU/内存/QPS/RT/错误率，超过阈值钉钉/邮件告警，7×24值班。额外保障：多活/容灾——异地多活或冷备（极端情况下切流量到备用数据中心）；灰度发布——新版本先发布一台实例验证10分钟无异常再全量；系统降级预案——定义降级开关（关闭非核心功能如推荐、积分、统计），核心交易链路不受影响。核心原则：任何组件都可能挂，架构要能容忍单点故障。</p>', 1, 8, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q345. Nacos的AP和CP模式分别是什么？如何选择？</p>', '<p>答案解析：Nacos同时支持AP和CP两种一致性协议，且能动态切换。AP模式（最终一致，可用性优先）：基于自研的Distro协议，适合服务注册发现场景。临时实例注册走AP模式——Nacos节点之间异步复制数据，网络分区时所有节点仍可对外提供服务（允许短暂数据不一致）。CP模式（强一致，一致性优先）：基于Raft协议，适合配置中心场景。持久实例注册和配置数据走CP模式——写入时需集群半数以上节点确认，网络分区时少数派节点拒绝写入。为何服务注册用AP：服务注册发现场景要求服务永远可用（不能因为Nacos集群部分故障导致服务无法调用），允许短暂的服务列表不一致（最终一致即可）。为何配置用CP：配置数据变更频率低但要求绝对准确，不能出现"改了配置但部分节点读到旧值"的情况。切换方式：配置spring.cloud.nacos.discovery.ephemeral=false时实例注册走CP模式。</p>', 1, 8, 0, 0, NULL, CURRENT_TIMESTAMP);-- Part 9: 消息队列 (tag=9, 10条)
INSERT INTO `t_knowledge` (`question`, `answer`, `status`, `tag`, `del_flag`, `view_count`, `last_view_time`, `add_time`) VALUES
('<p>Q346. RabbitMQ、Kafka、RocketMQ三者选型对比？</p>', '<p>答案解析：RabbitMQ：Erlang开发，AMQP协议，功能完善（路由、死信、延迟队列等），消息可靠性高（消息确认+持久化+镜像集群）。吞吐量几万/秒（偏低的量级）。适合：中小规模业务系统、金融类对可靠性和功能要求高的场景、需要灵活路由的场景。Kafka：Scala+Java开发，自定义协议，超高吞吐量（百万/秒），通过顺序写磁盘+零拷贝+分区并行实现极致性能，支持消息回溯（基于offset重新消费）。缺点：功能相对简单（无延迟队列、无死信队列原生支持），消息可能会丢失（异步刷盘）。适合：大数据日志收集、流式计算、实时数据管道、用户行为埋点。RocketMQ：Java开发（阿里开源），兼顾高吞吐（十万/秒）+高可靠性（同步刷盘+主从同步），功能完整（事务消息、延迟消息、死信队列），业务友好。缺点：社区活跃度不如Kafka。适合：电商、金融等对消息可靠性和吞吐量都要求较高的业务系统。简单总结：追求可靠性用RabbitMQ，追求超高吞吐用Kafka，平衡兼顾用RocketMQ。</p>', 1, 9, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q347. 消息队列如何保证消息不丢失？端到端的保障机制？</p>', '<p>答案解析：从消息产生到消费完成的全链路保障，分三阶段：1、生产阶段——开启生产者确认机制。RocketMQ发送消息时设置同步发送（send(msg, timeout)），等待Broker返回确认ACK才认为发送成功；RabbitMQ开启publisher confirm模式（confirmCallback），发送失败时重试或记录到数据库后续补偿。<br/>2、Broker存储阶段——消息持久化。RocketMQ设置为同步刷盘（flushDiskType=SYNC_FLUSH，消息写入磁盘才返回）和同步主从复制（BrokerRole=SYNC_MASTER，从节点同步完成才返回）。RabbitMQ设置队列和消息都持久化（durable=true+deliveryMode=2）。持久化和异步刷盘是性能和可靠性的权衡——异步刷盘性能高但断电可能丢消息。<br/>3、消费阶段——手动ACK确认。消费者处理完业务逻辑后再ACK签收（而非自动ACK），如果业务处理失败不签收，消息会重新投递给其他消费者。RocketMQ的CLUSTERING集群消费模式下，消息消费失败后返回RECONSUME_LATER，MQ会重试最多16次。关键：ACK必须在业务处理成功后发送，不能先ACK再处理业务（如果业务失败消息就丢了）。</p>', 1, 9, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q348. 消息重复消费的原因及幂等解决方案？</p>', '<p>答案解析：重复消费的原因：1、网络超时——消费者处理成功但ACK因网络问题未到达Broker，Broker认为消费失败重新投递。<br/>2、消费者宕机——消费者在处理消息过程中宕机，Broker未收到ACK，将消息投递给其他消费者。<br/>3、重平衡（Rebalance）——消费者组内成员变化触发重平衡，已分配但未ACK的消息重新分配。解决方案：消费者必须做幂等处理。1、数据库唯一索引——消费的业务数据有唯一标识（如订单号、交易流水号），数据库建唯一索引，重复写入时捕获DuplicateKeyException。<br/>2、Redis记录消费ID——消费前在Redis用SETNX记录消息ID（设置过期时间如7天），成功设置说明是首次消费才处理业务，否则跳过。需用Lua脚本保证原子性。<br/>3、业务状态机判断——根据业务状态表判断：如订单状态已经是"已支付"，收到重复的支付成功消息直接返回成功不做处理。最佳实践：消息ID+业务唯一ID双重判断。RocketMQ的消息有messageId（全局唯一），可作为幂等键的一部分。消息队列只保证至少一次成功（at-least-once），保证恰好一次（exactly-once）需要消费端业务幂等。</p>', 1, 9, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q349. 消息积压的原因及如何处理？</p>', '<p>答案解析：消息积压是指消费速度跟不上生产速度，消息在MQ中大量堆积。常见原因：1、消费者处理逻辑慢（SQL慢、调外部接口超时、代码bug死循环等）。<br/>2、消费者宕机/重启。<br/>3、消息量突然暴涨（秒杀、促销）。<br/>4、消费者线程数不够。排查与处理流程：第一步——检查消费者状态（是否在线、线程数、处理耗时）。第二步——如果是消费逻辑慢，紧急方案：临时增加消费者实例数量（横向扩容），注意不能超过MQ的分区/队列数（RocketMQ消费组内消费者数<=队列数，多的消费者分不到队列空闲）；调整消费者线程数（consumeThreadMin/Max）。第三步——如果是消息量暴涨，可以临时新写一个消费者程序，不做业务处理仅将消息快速消费后存储到数据库/文件中，事后补偿处理。第四步——业务高峰期过后，对积压的处理完的消息做好幂等确认。预防措施：1、建立积压监控告警（积压量超阈值钉钉通知）。<br/>2、设置消息过期时间，超时转入死信队列避免无线积压。<br/>3、异步处理中核心链路和次要链路分离（核心消息优先消费）。</p>', 1, 9, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q350. 死信队列的作用？什么情况消息会进入死信？</p>', '<p>答案解析：死信队列（DLQ）是MQ中处理无法正常消费的消息的兜底机制。以下情况消息会转入死信队列：1、消息被消费者拒绝（Reject/Nack），且requeue=false（不再放回原队列）。<br/>2、消息过期（TTL超时）——设置了过期时间的消息，超时后未消费自动转入死信。<br/>3、队列已满——队列达到最大长度限制，新消息无法入队时，最早的消息转入死信。<br/>4、消费重试次数超限——RocketMQ消息消费失败后最多重试16次，仍失败则转入死信队列（%DLQ%消费者组名）。作用：1、兜底保护——防止无法处理的消息在正常队列中无限重试，阻塞正常消息消费。<br/>2、故障定位——死信队列中的消息保留原始消息+重试记录+失败原因，便于人工排查问题。<br/>3、事后补偿——运维人员定期检查死信队列，分析失败原因，修复后重新投递或手动处理。实际项目：配置死信队列的监控告警（死信队列中出现消息说明业务有异常），定期Review死信中的消息，找到根本原因修复（是消息内容错误还是消费逻辑bug还是下游服务不稳定）。</p>', 1, 9, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q351. 延迟队列的实现原理和业务场景？</p>', '<p>答案解析：延迟队列——消息发送后不会立即被消费，而是在指定的延迟时间后才被消费者获取。RocketMQ实现：发送消息时设置delayLevel（支持18个级别：1s/5s/10s/30s/1m/2m/3m/4m/5m/6m/7m/8m/9m/10m/20m/30m/1h/2h），Broker将消息存入内部延迟队列SCHEDULE_TOPIC_XXXX中，定时任务扫描到期消息重新投递到原始Topic。RabbitMQ实现：利用消息TTL+死信队列——设置消息过期时间和死信交换机，消息过期后自动路由到目标队列。或者安装rabbitmq_delayed_message_exchange插件直接支持延迟队列。典型业务场景：1、订单超时自动取消——下单后30分钟未支付，自动取消订单释放库存（优于定时任务轮询，精确到秒级且省资源）。<br/>2、支付超时关单。<br/>3、延时发送通知（下单15分钟后发送评价提醒）。<br/>4、分布式定时任务。与定时任务对比：延迟队列更精确、更轻量、更适合大量不同延迟时间的任务；定时任务适合固定时间点执行的批量任务。</p>', 1, 9, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q352. 事务消息的实现原理？半消息是什么？</p>', '<p>答案解析：事务消息解决本地事务和消息发送一致性的问题——确保本地事务执行成功消息才能被消费者消费，本地事务回滚则消息不会被消费。RocketMQ事务消息流程：1、生产者发送半消息（half message）到Broker——此时消息对消费者不可见（消费者无法拉取）。<br/>2、Broker返回半消息发送成功。<br/>3、生产者执行本地事务（如创建订单、扣减库存）。<br/>4、生产者将本地事务执行结果（commit或rollback）通知Broker：commit→半消息变为可投递的普通消息，消费者可以消费；rollback→Broker删除半消息。<br/>5、如果Broker没有收到生产者的二次确认（网络超时或生产者宕机），Broker会主动回查（check）生产者的本地事务状态——生产者需要实现checkLocalTransaction接口，根据本地数据（如订单表）返回事务是commit还是rollback。半消息的本质是在本地事务提交之前"预占"一个位置，只有本地事务成功才把消息"激活"。使用场景：下单同时要发送消息给积分服务（不能出现下单成功但消息没发、或消息发了但下单失败的情况）。</p>', 1, 9, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q353. MQ如何保证消息有序性？什么场景需要有序？</p>', '<p>答案解析：消息有序需求场景：1、订单状态流转（创建→支付→发货→完成），必须按顺序处理，不能先处理"发货"再处理"创建"。<br/>2、增量数据同步（binlog同步到ES），主键相同的记录必须按先后顺序执行。保证有序的方案：1、全局有序——整个队列只有一个分区（一个Topic一个Queue），所有消息进入同一个队列，单消费者串行处理。缺点是性能极差（无法并发），基本不用。<br/>2、分区有序（推荐）——将同一业务维度的消息路由到同一个队列。RocketMQ中，发送消息时指定MessageQueueSelector，通过业务ID（如订单号）取模哈希到固定队列：`select(queues, msg, orderId) -> queues.get(orderId.hashCode() % queues.size())`。同一个订单号的所有消息始终进入同一个队列，该队列由单个消费者串行处理（队列内有序）。不同订单号可能在不同队列，并发处理（全局部分有序）。Kafka类似——同一个key（订单号）的消息进入同一Partition，单Partition内有序。注意：消费者端必须使用顺序消费模式（MessageListenerOrderly），一个队列同时只有一个线程消费，不要手动开多线程。</p>', 1, 9, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q354. 消息队列在削峰填谷中的应用？限流和MQ削峰的区别？</p>', '<p>答案解析：削峰填谷原理：将瞬时高峰流量转存到MQ中缓冲，后端消费者按自己能够承受的速度匀速处理，避免数据库和后端服务被冲击。典型场景——秒杀：前端秒杀请求如每秒10万写请求，如果直接同步写数据库+扣Redis（数据库连接池、锁竞争、IO直接打满），服务器瞬间宕机。使用MQ削峰：秒杀请求到达后端后，快速将用户ID+商品ID封装为消息发送到MQ然后立即返回"排队中"，MQ平滑处理每秒10万入队，后端消费者以每秒2千的速度从容消费（校验库存+创建订单+扣Redis），平稳处理1分钟后完成所有请求。限流 vs 削峰：限流在入口就拒绝超过阈值的请求（如超出1万QPS的直接返回"系统繁忙，请稍后再试"），是直接丢弃；MQ削峰是暂存请求、延迟处理，请求不丢失但响应变慢。两者互补——网关层先限流（拒绝一部分，保护系统），剩余请求进入MQ削峰排队处理。</p>', 1, 9, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q355. 消息队列的推（push）模式和拉（pull）模式的区别？</p>', '<p>答案解析：Push模式（Broker主动推送给消费者）：RocketMQ和RabbitMQ默认使用Push模式，Broker有消息就主动推送给消费者。优点：消息实时性好，消费者代码简单（注册MessageListener等待回调）。缺点：如果消费者处理能力跟不上推送速度，消息会在消费者端堆积，内存压力大；需要设置消费并发数来控制速度。Pull模式（消费者主动去Broker拉取）：Kafka默认使用Pull模式，消费者按自己的节奏拉消息（可以控制拉取的条数和间隔）。优点：消费者完全掌控消费速度，不会被打垮；可以批量拉取提升吞吐。缺点：如果没有消息，消费者需要不断轮询（空拉取）浪费资源，可以通过长轮询（Long Polling）优化——拉取请求到达时如果没有消息，Broker暂时挂起请求一段时间，有消息再响应。RocketMQ同时支持Push（底层是封装的长轮询Pull）和Pull两种模式。业务系统推荐使用Push模式（简单、实时性好），大数据场景使用Pull模式（批量高效）。理解核心：Push模式逼着消费者消费到饱和，Pull模式消费者自我调节消费速度。</p>', 1, 9, 0, 0, NULL, CURRENT_TIMESTAMP);-- Part 10: ES搜索引擎 (tag=10, 10条)
INSERT INTO `t_knowledge` (`question`, `answer`, `status`, `tag`, `del_flag`, `view_count`, `last_view_time`, `add_time`) VALUES
('<p>Q356. Elasticsearch的核心概念：索引、文档、分片、副本？</p>', '<p>答案解析：索引（Index）——类比关系型数据库的Database或Table，是具有相同结构的文档集合。文档（Document）——ES的基本数据单元，JSON格式，类比关系型数据库的一行数据。每个文档有唯一的_id标识。分片（Shard）——索引被水平切分为多个分片（创建时指定，后续不可改），每个分片是一个完整的Lucene实例。分片分布在集群不同节点上，实现分布式存储和并行查询。默认每个索引5个主分片。副本（Replica）——主分片的拷贝，提供高可用和扩展读能力。主分片故障时，副本提升为新主分片。副本分片可以分担查询负载（副本可读不可写）。创建索引后副本数量可动态修改。映射（Mapping）——定义文档字段的类型（text/keyword/long/date等），类似建表时的DDL。dynamic mapping可自动推断字段类型但推荐显式定义Mapping。对比关系型数据库：Index=Table、Document=Row、Field=Column、Mapping=Schema。</p>', 1, 10, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q357. ES倒排索引的基本原理？为什么快？</p>', '<p>答案解析：倒排索引（Inverted Index）是ES高效全文检索的核心数据结构。正向索引：文档ID→文档中的词汇列表（适合按ID查文档，但无法搜索包含某词的文档）。倒排索引：词汇→包含该词汇的文档ID列表。构建过程：①对每个文档的内容进行分词（如"ES全文检索"→["ES","全文","检索"]）；<br/>②为每个词条建立倒排记录，记录该词出现在哪些文档中（文档ID、出现位置、词频等）。查询"全文"时→直接查找倒排索引中"全文"→获取文档ID列表[doc1, doc3, doc7]→返回结果，无需扫描所有文档。为什么快：①不需要全表扫描，类似书的目录索引；<br/>②倒排索引以Term Dictionary（词条字典，排序存储）+Term Index（词条索引，类似B树）组织，定位词条是O(log n)；<br/>③Posting List（倒排列表）使用高效的压缩和跳表（Skip List）结构，多词查询（交集/并集）计算极快。对比MySQL模糊查询LIKE ''%%''：MySQL需要全表扫描逐行匹配，百万级数据可能几十秒；ES倒排索引毫秒级返回。</p>', 1, 10, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q358. ES分词器的作用？常用中文分词器有哪些？</p>', '<p>答案解析：分词器（Analyzer）是ES全文检索的基础组件，将文本拆分为独立的词条（Term）用于建立倒排索引和检索匹配。分词器三部分：Character Filter（字符过滤器，预处理如去除HTML标签）→Tokenizer（分词器核心，将文本拆分为词条流）→Token Filter（词条过滤器，如转小写、去停用词、同义词）。中文分词的挑战：英文天然空格分隔单词，中文词与词之间没有分隔符，需要理解语义进行分词。常用中文分词器：1、IK分词器（最流行）：ik_max_word（细粒度，尽量多拆，"中华人民共和国"→["中华人民共和国","中华人民","中华","华人","人民","共和国"]）、ik_smart（粗粒度，"中华人民共和国"→["中华人民共和国"]）。支持自定义词典扩展新词。<br/>2、jieba分词器：基于前缀词典实现高效词图扫描，支持词性标注。<br/>3、pinyin分词器（拼音检索辅助）。分词策略影响搜索结果：粗粒度分词（ik_smart）精度高但召回少，适合精确匹配；细粒度分词（ik_max_word）召回多但可能返回不相关结果。实际项目：搜索时用ik_smart匹配用户意图，索引时根据场景选择粒度，并维护行业词典。</p>', 1, 10, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q359. ES中term查询和match查询的根本区别？</p>', '<p>答案解析：term查询（精确查询）：不对搜索词做分词处理，直接将搜索词作为一个完整的词条去倒排索引中精确匹配。适合keyword类型字段（如订单号、手机号、状态码、枚举值等），要求完全匹配。示例：`{"term":{"status":"PAID"}}`只匹配status字段精确等于"PAID"的文档。match查询（全文模糊查询）：对搜索词进行分词，用分词后的词条去倒排索引匹配，多个词条做布尔运算（默认OR语义）。适合text类型字段（如商品名称、文章内容等需要模糊搜索的场景）。示例：搜索"手机壳"→分词为["手机","壳"]→匹配包含"手机"或"壳"的文档→按相关度评分排序。phrasc完整匹配：match_phrase——搜索词分词后要求所有词条按顺序连续出现（类似MySQL的LIKE ''%X%''但更高效）。精确ID搜索应使用term（直接定位到倒排列的精确key，O(1)级别），而不是match（先分词再匹配，多一次分词开销且可能误匹配）。keyword vs text：keyword存原值不做分词（适合精确匹配+聚合+排序），text做分词+倒排索引（适合全文搜索）。</p>', 1, 10, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q360. ES深分页问题及scroll和search_after解决方案？</p>', '<p>答案解析：深分页问题：from+size方式（如from=10000,size=10），ES会先从每个分片获取10010条数据，在协调节点合并排序后取第10000-10010条。随着from增大，需要处理的数据量和内存消耗线性增长。ES默认限制from+size<=10000（max_result_window）。解决方案：1、Scroll——适合批量导出、全量数据拉取场景。创建Scroll时ES生成数据快照，后续通过_scroll_id遍历，保证一致性。类似数据库游标，Scroll上下文有时间限制（默认1分钟）。缺点：不能用于实时搜索（不会包含后续新增数据）、占用大量资源。<br/>2、search_after——适合实时搜索的深分页（如用户持续下拉翻页）。使用上一页最后一条数据的排序值作为搜索起点，ES只取之后的N条。效率远高于from+size（不跳过前面数据，直接定位）。要求排序字段有索引且值唯一（推荐用id作为最终的排序字段保证唯一性）。与游标区别：search_after不需要保持Scroll上下文，实时反映数据变化（适合C端实时翻页）。业务系统列表查询建议：前几页用from+size（简单），翻到后面自动切换search_after。</p>', 1, 10, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q361. ES数据如何与MySQL保持同步？</p>', '<p>答案解析：主流四方案：1、业务双写——业务代码中同时写MySQL和ES。问题：双写非原子（一个成功一个失败导致不一致）、耦合严重（散落在各个Service中）、维护困难。不推荐。<br/>2、Logstash（官方工具）——通过定时查询MySQL将数据导入ES。优点：配置简单、无需代码改动。缺点：定时轮询有延迟（分钟级）、无法感知DELETE（逻辑删除字段可处理）、全量拉取对DB有压力。<br/>3、Canal（阿里开源，推荐）——伪装成MySQL的Slave，监听并解析binlog，将数据变更推送到ES。优点：实时性高（秒级）、无侵入（不需要改业务代码）、增量同步对DB几乎无压力。缺点：需要额外部署Canal Server、需要处理DDL变更。<br/>4、MQ异步同步——业务代码写MySQL后发送MQ消息，ES同步服务消费MQ更新ES。优点：实时、解耦。缺点：需要在业务代码中嵌入MQ发送逻辑。推荐组合方案：全量同步用Logstash（一次性拉取历史数据）、增量同步用Canal（实时同步binlog变更）。同步注意事项：保证幂等、处理失败重试、监控同步延迟。</p>', 1, 10, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q362. ES集群的高可用是如何实现的？</p>', '<p>答案解析：1、数据冗余——每个索引的每个主分片都有1-N个副本分片，分布在不同的节点上。主分片故障时，集群自动投票将副本提升为新主分片（毫秒级）。副本分片越多可用性越高但存储成本越大（N副本=N倍存储）。<br/>2、节点角色分离——Master节点负责集群管理（索引创建删除、分片分配），Data节点负责数据存储和查询。大集群配置专用Master候选节点（不存数据），避免Master因数据处理压力大而心跳超时导致集群脑裂。<br/>3、故障检测——Master节点定时Ping所有节点，节点无响应超时（默认30秒）后判定节点丢失，重新分配其上的分片到其他节点。<br/>4、脑裂预防——使用过半选举原则（discovery.zen.minimum_master_nodes=N/2+1），防止网络分区时出现多个Master。ES 7.0+用新集群协调子系统替代。<br/>5、跨机房/可用区——分片分布在不同的物理机或可用区（通过allocation awareness配置），单个机架或交换机故障不影响整体。实际部署：至少3个Master候选节点+至少2个Data节点（每个索引1主1副），小集群可混合部署。</p>', 1, 10, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q363. ES写入（索引）数据的流程是怎样的？</p>', '<p>答案解析：写入请求到达协调节点（任意节点都可做协调节点，负责路由和转发）→协调节点根据routing计算目标分片（默认routing=文档_id，分片号=hash(routing)%主分片数）→将请求转发到主分片所在的节点。主分片处理写入流程：①写入内存缓冲区（buffer）+同时写入事务日志（translog，用于故障恢复）；<br/>②默认每1秒（refresh_interval）将buffer中的数据刷新为新的Segment（段）并打开，使数据可搜索（ES的近实时性就是1秒延迟的原因）；<br/>③translog达到一定大小（默认512MB）或每30分钟触发flush操作——执行fsync将buffer中的Segment刷入磁盘、清除translog。副本写入：主分片写入成功后，将写入同步到所有副本分片，所有副本写入成功后才返回客户端确认（可配置为等待指定数量副本确认）。写入优化：调大refresh_interval减少Segment刷新频率（如30秒，降低IO、提升写入吞吐，牺牲实时性）；调大translog flush阈值（减少磁盘fsync次数）；使用bulk批量写入（减少网络往返和IO）；设置合理的副本数（多副本写入变慢但提高可用性）。</p>', 1, 10, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q364. ES聚合查询（Aggregation）原理和常用类型？</p>', '<p>答案解析：聚合是ES的数据统计分析能力，对搜索结果进行实时分组和计算。常用分类：1、桶聚合（Bucket Aggregation）——按条件将文档分组到不同的桶中，类似SQL的GROUP BY。<br/>①terms：按字段值分组（如按品类统计商品数量）；<br/>②range：按数值区间分组（如价格0-100、100-500、500+）；<br/>③date_histogram：按时间区间分组（如按天/小时统计订单量）。<br/>2、指标聚合（Metric Aggregation）——对桶内文档进行计算统计值。<br/>①avg/sum/max/min/count：求平均值、总和、计数等（类似SQL的聚合函数）；<br/>②stats：一次性返回count/min/max/avg/sum多个统计值；<br/>③percentiles：百分位统计。<br/>3、管道聚合（Pipeline Aggregation）——对其他聚合结果进行二次计算，如按日期分组统计销售额后计算环比增长。聚合性能注意：聚合在内存中计算，大聚合（如terms+大量分组）可能导致OOM；text字段需设置fielddata=true才能聚合（但不推荐，应用keyword子字段聚合）；聚合查询可设置size限制返回桶的数量。</p>', 1, 10, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q365. ES的评分（_score）机制和BM25算法简述？</p>', '<p>答案解析：ES的评分决定搜索结果的排序——分越高的文档越排在前面（越"相关"）。BM25算法（ES 5.0+默认）：比老版TF/IDF更先进。评分受三大因素影响：1、词频（TF，Term Frequency）——搜索词在文档中出现的次数越多，分越高。但非线性增长（出现3次是1次的约1.5分而非3倍），防止长文档靠重复词霸占排名。<br/>2、逆文档频率（IDF，Inverse Document Frequency）——搜索词在所有文档中出现得越少（越稀有），权重越高。如搜索"Elasticsearch"比搜索"的"更能区分文档相关性（"的"几乎每个文档都有，IDF极低）。<br/>3、字段长度归一化——搜索词在短文档中出现比在长文档中出现更重要（匹配比例高）。BM25核心公式可简化为：Score = IDF × TF/(TF + k1×(1-b+b×字段长度/平均长度))。影响评分的因素：boost权重（索引时可以给标题/正文不同权重）、字段类型、分析器。查看评分：在查询中加`"explain": true`可看到每个文档详细的评分计算过程（调试评分用）。</p>', 1, 10, 0, 0, NULL, CURRENT_TIMESTAMP);-- Part 11: Vue前端知识 (tag=11, 18条)
INSERT INTO `t_knowledge` (`question`, `answer`, `status`, `tag`, `del_flag`, `view_count`, `last_view_time`, `add_time`) VALUES
('<p>Q366. Vue2和Vue3响应式原理的区别？Proxy相比defineProperty的优势？</p>', '<p>答案解析：Vue2响应式：通过Object.defineProperty()劫持对象属性的getter/setter，在get时收集依赖（Watcher），在set时通知依赖更新。三大缺陷：1、无法检测对象属性的新增和删除——初始化后新增的属性不是响应式的（需用Vue.set()补救）。<br/>2、无法检测数组索引修改和数组长度修改——arr[0]=newVal不触发更新、arr.length=0不触发。重写了数组的7个变异方法（push/pop/splice/shift/unshift/sort/reverse）进行拦截处理。<br/>3、需要深度遍历所有属性——初始化时递归遍历对象的每个属性做劫持，性能差。Vue3响应式：通过ES6的Proxy代理整个对象（而非每个属性），可拦截13种操作（get/set/has/deleteProperty/ownKeys等）。四大优势：1、天然检测属性增删（deleteProperty可拦截）。<br/>2、天然支持数组索引修改和length修改。<br/>3、惰性响应——只在get时递归代理子对象（嵌套对象用到时才变为响应式），初始化性能大幅提升。<br/>4、Proxy代理的是对象本身而非属性，代码更简洁。Vue3的ref()用getter/setter实现基本类型响应式（基本类型需要对象包裹），reactive()用Proxy实现对象类型响应式。</p>', 1, 11, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q367. Vue生命周期各阶段的钩子函数及适用场景？</p>', '<p>答案解析：Vue组件从创建到销毁经历一系列生命周期阶段。创建阶段：beforeCreate——数据观测和事件初始化之前，无法访问data/computed/methods。created——实例创建完成，data/methods已可用，但DOM未挂载。常在此阶段发起异步请求获取数据（此时不能操作DOM）。挂载阶段：beforeMount——模板编译完成，即将挂载到DOM。mounted——组件DOM已渲染完成，可以操作DOM（如初始化图表库、获取DOM元素尺寸）。常在此阶段做DOM操作、第三方库初始化。更新阶段：beforeUpdate——数据变化DOM更新前，可获取旧的DOM状态。updated——DOM更新完成，避免在此阶段改数据（会触发循环更新）。常在此阶段做更新后的DOM操作。销毁阶段（Vue3为unmount）：beforeUnmount——组件销毁前，常在此清除定时器、取消网络请求、移除事件监听。unmounted——组件已销毁。Vue3组合式API中：setup()替代了beforeCreate和created（最早执行，此时组件实例还未创建），onMounted/onUpdated/onUnmounted在setup中按需导入使用。KeepAlive组件有activated和deactivated两个额外钩子。</p>', 1, 11, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q368. Vue中computed和watch的使用场景及核心区别？</p>', '<p>答案解析：computed（计算属性）：依赖其他数据通过计算得出新值的属性。有缓存——依赖数据没有变化时，多次访问返回缓存值而不重新计算。必须是同步的（不能有异步操作），必须有返回值。典型场景：购物车总价（依赖商品列表和数量计算总金额）、列表过滤（根据搜索关键词过滤列表）、格式化显示（时间戳转日期格式）。watch（侦听器）：监听数据变化后执行副作用的逻辑。无缓存——数据变化就执行回调。支持异步操作（调用API、设置定时器）。典型场景：搜索关键词变化后发请求查后端、路由参数变化后重新请求数据、表单字段变化后做校验。选择标准：有依赖数据的派生状态（总价=商品的单价×数量）→computed；数据变化后要执行操作（发请求、操作DOM、存储localStorage）→watch。不要用watch监听多个依赖然后拼出新值——这是computed的活。Vue3中computed返回的是一个只读的ref对象，通过.value访问。watch支持监听多个数据源、深度监听、立即执行（immediate:true）。</p>', 1, 11, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q369. Vue组件通信的八种方式及适用场景？</p>', '<p>答案解析：1、props + $emit（父子通信最基础）：父组件通过props向子组件传递数据（单向数据流），子组件通过$emit触发事件通知父组件。适合简单的父子数据传递。<br/>2、v-model（父子双向绑定）：本质是props:value + $emit(''''input'''')的语法糖，Vue3中改为props:modelValue + emit(''''update:modelValue'''')，并支持多个v-model绑定。<br/>3、$refs（父访问子）：父组件通过ref直接访问子组件实例的方法和数据。适合父组件需要调用子组件方法的场景。<br/>4、$parent / $children（子访问父/祖先）：子组件访问父组件实例。不推荐（耦合度高，破坏了组件独立性）。<br/>5、provide / inject（跨层级传递）：祖先组件provide数据，任意后代通过inject获取，无需层层传递props。适合全局配置（如主题、语言）、深层嵌套组件传递。Vue3中provide/inject配合ref可实现响应式。<br/>6、EventBus（全局事件总线，Vue2）：通过空的Vue实例作为中央事件总线，$emit发事件、$on监听。组件之间完全解耦。缺点：事件名可能冲突、难以追踪维护。Vue3已移除，推荐用mitt等库替代。<br/>7、Vuex / Pinia（全局状态管理）：适合多组件共享的全局状态（用户信息、购物车、全局配置）。<br/>8、$attrs / $listeners（透传）：将父组件传过来的属性和事件透传给更深层的子组件，减少中间组件写props的冗余代码。</p>', 1, 11, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q370. Vue Router的路由守卫分类及作用？</p>', '<p>答案解析：路由守卫用于在路由跳转前后进行拦截和控制，最常用于权限验证和登录检查。三大类：1、全局守卫——beforeEach（每次路由跳转前触发，最常用）：在这里校验token——没登录且目标页不是登录页则重定向到登录页，有token但无用户信息则先获取用户信息再放行。afterEach（跳转完成后触发）：设置页面标题、记录页面访问埋点。<br/>2、路由独享守卫——beforeEnter：在路由配置中定义，只针对特定路由生效。适合某个页面的特殊校验。<br/>3、组件内守卫——beforeRouteEnter（组件创建前触发，此时无法访问this，但可通过next的回调访问实例）、beforeRouteUpdate（同一组件不同参数跳转时触发，如/report/1跳/report/2）、beforeRouteLeave（离开当前页面时触发，如"有未保存的更改，确定离开吗？"）。守卫执行顺序：beforeRouteLeave→全局beforeEach→路由beforeEnter→组件beforeRouteEnter→全局afterEach。回调参数：to（目标路由）、from（来源路由）、next（放行函数，Vue3推荐return true/false或返回重定向路径替代next()）。</p>', 1, 11, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q371. Vue Router的路由懒加载如何实现？有什么好处？</p>', '<p>答案解析：路由懒加载通过动态导入（dynamic import）语法实现：`const Foo = () => import(''''@/views/Foo.vue'''')`替代直接import。Webpack/Vite构建时会将动态导入的组件拆分为独立的chunk文件（异步块），用户访问该路由时才加载对应的JS文件（按需加载），而非打包到一个巨大的app.js中。好处：1、首屏加载快——初始只加载核心代码（首页、公共组件），其他页面暂不加载。<br/>2、减少初始带宽消耗——用户可能不会访问所有页面，按需加载避免了不必要的下载。<br/>3、缓存友好——每个chunk独立，页面变更只影响对应chunk的缓存。优化实践：chunk命名——通过魔法注释`import(/* webpackChunkName: "user" */ ''''@/views/User.vue'''')`给chunk命名，便于分析。相同业务模块的页面可打包到同一chunk。加载状态：路由懒加载可配合Suspense组件（Vue3）展示加载中的骨架屏或loading效果，提升用户体验。网络较慢时通过loading动画告知用户页面正在加载。</p>', 1, 11, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q372. Vue中v-if和v-show的使用场景和性能对比？</p>', '<p>答案解析：v-if：条件为假时，元素完全不渲染（not render at all），不会被添加到DOM树中，组件的生命周期不会执行。切换开销大——每次切换都涉及元素/组件的销毁和重新创建（需要重新执行created/mounted等生命周期，重新请求数据）。初始渲染开销小——条件为假时不渲染任何东西。v-show：条件为假时，元素仍被渲染并保留在DOM中，只是CSS `display:none` 切换。切换开销小——只是改CSS display属性，DOM元素始终存在，组件不会被销毁。初始渲染开销大——不管条件真假都先渲染DOM元素。选择标准：频繁切换（如Tab切换、折叠面板、显隐弹窗）→v-show（DOM常驻，切换只是display切换，避免反复创建销毁）；几乎不变或只切换一次（如用户权限判断显示不同菜单、页面初始化加载中vs加载完成）→v-if（不需要时就省掉DOM，减少DOM节点）。注意：v-if和v-show不要同时用在同一个元素上（v-if优先级更高，先判断v-if）。</p>', 1, 11, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q373. Vue中key的作用？为什么不能推荐用index做key？</p>', '<p>答案解析：key是Vue识别虚拟DOM节点的唯一标识，在diff算法中用于判断两个节点是否相同。当数据变化引起列表重新渲染时，Vue通过key来复用和重排已有节点，而非销毁重建所有节点，以减少DOM操作、提升渲染性能。diff算法中：新旧节点的key和标签类型都相同→判定为同一节点（直接复用DOM，只更新变化的属性）；key不同→替换为新节点（销毁旧DOM、创建新DOM）。为什么不能用index做key：当列表发生插入/删除/排序操作时，index会重新分配——本来index=1对应数据A，插入新数据B在最前面后，index=1变成了A，index=2变成了B……所有元素的key全变了，Vue无法复用任何旧DOM节点（因为key全变了），相当于全部销毁重建，性能骤降。且如果列表项中有未受控的子组件状态（如输入框内容、展开状态），会出现状态错乱（用户输入的内容跑到了别的行）。正确做法：使用数据中稳定唯一的ID作为key（如数据的ID、userId等）。简单静态列表无增删排序操作时用index也可以（但建议养成不用index的习惯）。</p>', 1, 11, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q374. Vue3组合式API（Composition API）相比选项式API的优势？</p>', '<p>答案解析：Vue3组合式API通过setup()函数组织逻辑，替代了Vue2的data/methods/computed/watch等选项。五大优势：1、更好的逻辑复用——Vue2的mixin有命名冲突、来源不清晰、无法传参等缺陷；Vue3通过composables（可组合函数）实现逻辑复用，如`const {loading, data, error} = useFetch(''''/api/users'''')`，功能独立、命名清晰、可传参。<br/>2、更好的代码组织——Vue2选项式API将同一功能的逻辑分散在data、methods、computed等不同选项中（如搜索功能的数据、方法、计算属性散落在四处）；组合式API将同一功能的逻辑聚合在一起（搜索相关的数据、方法、watch都在一个函数中）。<br/>3、更好的TypeScript支持——组合式API天然适合TS的类型推导（普通函数参数和返回值），而选项式API需要用装饰器或Vue.extend()。<br/>4、更小的打包体积——组合式API的函数可按需引入（tree-shaking），未使用的函数不会被打包。<br/>5、更灵活的响应式——ref/reactive独立于组件实例使用，可在组件外创建响应式状态。注意：组合式API是选项式API的超集，可混合使用；简单组件用选项式API更直观，复杂组件用组合式API组织更清晰。</p>', 1, 11, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q375. Vue3中ref和reactive的区别和使用场景？</p>', '<p>答案解析：ref：将任意类型的值包装为响应式引用，通过.value访问和修改。可包装基本类型（ref(0)、ref(true)、ref(''''hello'''')）和引用类型（ref({name:''''张三''''})，内部自动调用reactive处理对象）。在模板中自动解包（模板中不需要.value，直接使用）。reactive：将对象包装为深度响应式代理（基于Proxy），直接通过属性名访问，不需要.value。只能用于对象类型（Object/Array/Map/Set），不能用于基本类型（基本类型不可被代理）。核心区别：1、ref用.value访问，reactive直接访问属性。<br/>2、ref可包装任意类型，reactive只能包装对象。<br/>3、ref整体替换不丢失响应式（`ref.value = newObj`），reactive整体替换会丢失（需要用Object.assign(obj, newObj)）。<br/>4、reactive解构后会丢失响应式（需要用toRefs()保留响应式连接）。<br/>5、ref的value重新赋值为同一个对象时不会触发更新。选择建议：基本类型→ref；单个对象→reactive（代码更简洁少写.value）或ref（更灵活如替换整个对象）；暴露给模板→两者都可以，模板中ref自动解包。从composable返回时，建议用ref确保解构后仍响应式。</p>', 1, 11, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q376. Pinia相比Vuex有哪些优势？Pinia的核心概念？</p>', '<p>答案解析：Pinia是Vue3官方推荐的状态管理工具。相比Vuex的优势：1、无需mutations——Vuex中修改state需要通过mutations（同步）或actions（异步），开发繁琐；Pinia直接在actions或组件中修改state。<br/>2、完整的TypeScript支持——Vuex对TS支持很差（需额外类型推导），Pinia天然支持TS推断。<br/>3、无模块嵌套——Vuex的module是嵌套树形结构（state合并在一起容易命名冲突）；Pinia的store是扁平的（每个store独立管理自己的state）。<br/>4、无需命名空间——Vuex的getters/actions调用需要模块前缀，Pinia直接通过useXxxStore()调用。<br/>5、体积更小——约1KB。核心概念：defineStore定义store，包含state（数据）、getters（计算属性）、actions（方法，支持异步）。actions内直接通过this访问state。组件使用：`const store = useUserStore(); store.name; store.login(params);`。支持插件（如持久化插件pinia-plugin-persistedstate自动存localStorage）、支持$patch批量更新、支持$reset重置状态。Vue2项目也可用Pinia（向下兼容）。</p>', 1, 11, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q377. Vue项目中跨域问题的原因及解决方案？</p>', '<p>答案解析：跨域（CORS）是由浏览器的同源策略引起的——协议、域名、端口三者任一不同即为跨域，浏览器阻止跨域请求的响应。Vue开发时前端localhost:8080，后端localhost:8081，端口不同即触发跨域。解决方案：开发环境：vue.config.js配置devServer.proxy代理——`proxy: { ''''/api'''': { target: ''''http://localhost:8081'''', changeOrigin: true } }`。原理：浏览器请求同源的开发服务器（localhost:8080）→开发服务器作为代理转发请求到后端（服务器间无跨域限制）→收到响应返回浏览器。路径重写：`pathRewrite: { ''''^/api'''': '''''''' }`将/api前缀去除（后端实际路径不需要/api）。生产环境：1、Nginx反向代理——前端静态资源和后端API部署在同一Nginx域名下，Nginx根据路径转发。`location /api/ { proxy_pass http://backend:8081/; }`（同样是服务端转发绕过跨域）。<br/>2、后端配置CORS——通过@CrossOrigin注解或全局WebMvcConfigurer配置允许跨域（Access-Control-Allow-Origin等响应头）。生产环境推荐Nginx方案（更安全，后端不需要关注跨域配置）。</p>', 1, 11, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q378. Vue项目的性能优化有哪些常用手段？</p>', '<p>答案解析：六大方向优化：1、代码层面——路由懒加载（按需加载页面）、组件异步加载（defineAsyncComponent）、合理使用v-if vs v-show（少切换用v-if省DOM，频繁切换用v-show避免重建）、避免v-for和v-if同时使用（v-for优先级更高，每轮循环都要判断v-if，应先computed过滤列表再v-for）。<br/>2、渲染优化——列表用稳定的key（不用index）、避免过多响应式数据（不需要响应式的数据用Object.freeze或shallowRef）、计算属性缓存（computed替代模板中的复杂计算）、KeepAlive缓存组件（避免频繁创建销毁）。<br/>3、数据加载——防抖节流（输入框搜索用debounce 300ms、滚动加载用throttle）、分页加载（虚拟列表处理长列表如vxe-table/vue-virtual-scroller）、图片懒加载（Intersection Observer API）。<br/>4、打包优化——代码分割（splitChunks提取公共库如Vue/Element Plus为独立chunk）、Tree Shaking（按需引入Element Plus/Ant Design组件）、Gzip压缩（Nginx开启，JS/CSS体积减少60-70%）。<br/>5、网络优化——CDN加速静态资源、HTTP缓存策略、预加载关键资源。<br/>6、监控分析——Lighthouse评分、Vue DevTools性能面板分析组件渲染耗时。</p>', 1, 11, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q379. Vue前端常见安全问题和防护方案？</p>', '<p>答案解析：1、XSS跨站脚本攻击——用户输入恶意脚本，在页面渲染时执行盗取Cookie。Vue默认对{{}}插值做HTML转义（防XSS），但v-html指令直接渲染HTML不安全。防护：避免用v-html渲染用户输入内容；对用户输入的富文本做DOMPurify清洗（过滤script标签和事件处理器onclick等）。<br/>2、CSRF跨站请求伪造——攻击者诱导用户点击恶意链接，以用户身份发起请求。防护：后端验证Referer/Origin请求头；使用CSRF Token（每次请求携带后端生成的token）；SameSite Cookie（Set-Cookie设置SameSite=Strict或Lax）。<br/>3、敏感信息暴露——前端代码中不存放密钥、密码等敏感信息（打包后的JS代码可见，稍微格式化就能读取）。密钥必须放后端管理。<br/>4、路由权限——前端路由守卫只能做UI拦截（隐藏按钮、拦截页面跳转），真正的权限控制必须在后端接口做校验。<br/>5、点击劫持——通过iframe嵌入你的网站并诱导点击。防护：后端设置X-Frame-Options: DENY响应头。<br/>6、HTTPS——生产环境必须HTTPS（防止中间人攻击篡改前端JS文件注入恶意代码）。</p>', 1, 11, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q380. Vue的虚拟DOM和diff算法原理是怎样的？</p>', '<p>答案解析：虚拟DOM是真实DOM的JS对象抽象描述（树形结构）。当数据变化时，Vue先生成新的虚拟DOM树，与旧虚拟DOM树做比较（diff算法/补丁算法），找出最小差异化，最终只更新真实DOM中变化的部分（而非整体刷新）。diff算法优化策略：1、同层对比（不跨层级比较）——只比较同一层级的节点，如果发现节点引用变了（类型不同或key不同），直接替换整棵子树而不深入比较。<br/>2、双端比较（头对头、尾对尾、头对尾、尾对头）——对于同一层级的子节点列表，Vue2使用四指针从两端向中间收缩比较（oldStart/oldEnd、newStart/newEnd），尽量复用移动而非删除重建。Vue3优化为最长递增子序列算法（求最少的移动步数），进一步减少DOM移动。<br/>3、key优化——通过key快速判断节点是否为同一节点，避免无谓的深入比较。diff的时间复杂度：O(n)（n=虚拟DOM节点数），远小于精确树编辑距离O(n^3)。虚拟DOM也非完美：创建JS对象的开销和diff计算本身也有性能成本，Vue3的编译时优化（静态标记、Block Tree）减少了diff开销。</p>', 1, 11, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q381. Vue自定义指令的使用场景和实现？</p>', '<p>答案解析：自定义指令用于封装可复用的DOM操作逻辑。全局注册：`app.directive(''''focus'''', { mounted(el) { el.focus(); } })`。局部注册：组件options中的directives选项。指令钩子函数（Vue3）：created、beforeMount、mounted、beforeUpdate、updated、beforeUnmount、unmounted。常用场景：1、自动聚焦——v-focus（页面加载后自动聚焦输入框）。<br/>2、权限控制——v-permission="''''admin''''"（根据角色权限，没有权限的移除DOM元素）。<br/>3、防抖——v-debounce="300"（配合事件监听，输入框输入抖动后执行）。<br/>4、点击外部关闭——v-click-outside="closeMenu"（点击元素外部时触发回调）。<br/>5、长按指令——v-longpress="handleLongPress"（长按多久触发）。<br/>6、复制到剪贴板——v-copy="text"（点击复制文本到剪贴板）。<br/>7、图片懒加载——v-lazy（元素进入可视区域后再加载图片src）。自定义指令只应在纯DOM操作场景使用（需要直接操作DOM元素），业务逻辑应放在组件中而非指令中。封装前先判断是否有现有的UI库组件或composable能替代。</p>', 1, 11, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q382. Vue中nextTick的作用及实现原理？</p>', '<p>答案解析：nextTick的作用：在下次DOM更新循环结束后执行回调。Vue中数据变化后，DOM的更新是异步批量的——同一个"事件循环"中的多次数据变更会被收集到一个更新队列中，在下一个tick统一执行DOM更新。如果数据修改后想立即操作更新后的DOM，直接用会拿到旧DOM（因为还没更新）。此时需要nextTick：`data.value = newVal; await nextTick(); console.log(domRef.value.textContent)`——此时打印出的是更新后的值。实现原理（Vue3）：nextTick本质上将回调推迟到当前宏/微任务之后执行。优先使用Promise.then（微任务），降级方案为MutationObserver→setImmediate→setTimeout。之所以能用微任务：微任务在宏任务之前执行（DOM更新在当前宏任务结束后、下一个宏任务开始前），所以nextTick能确保拿到已更新的DOM。使用场景：1、数据变化后操作DOM；<br/>2、在created中操作DOM（因为created阶段DOM未挂载，需要用nextTick推迟到mounted之后）；<br/>3、子组件挂载后在父组件中获取子组件ref。</p>', 1, 11, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q383. Vue3 Teleport和Suspense组件的用途？</p>', '<p>答案解析：Teleport（传送门）：将组件内部的DOM节点渲染到组件DOM树之外的指定位置。典型场景：Modal弹窗、Toast提示、Dropdown下拉菜单——这些UI元素在逻辑上属于当前组件，但视觉上需要渲染在body层（避免被父元素的overflow:hidden/z-index/position限制裁剪）。用法：`<Teleport to="body"><div class="modal">弹窗内容</div></Teleport>`将弹窗渲染到body标签下。多个Teleport渲染到同一目标时按先后顺序追加。Suspense：处理异步组件的加载状态。当组件树中存在异步依赖（如setup中用async/await加载数据），Suspense可以统一展示loading状态直到所有异步子组件解析完成。用法：`<Suspense><template #default><AsyncComponent/></template><template #fallback><Loading/></template></Suspense>`。两个插槽：default放异步组件，fallback放在加载期间展示的loading组件。体验改进：统一的loading状态管理、避免每个异步组件各自维护loading（减少布局抖动）、支持嵌套Suspense。注意：Suspense目前仍是实验性功能（Vue3.3+已稳定），主要用于异步组件（defineAsyncComponent）或setup中返回Promise的组件。</p>', 1, 11, 0, 0, NULL, CURRENT_TIMESTAMP);-- Part 12: 项目实战 (tag=12, 17条)
INSERT INTO `t_knowledge` (`question`, `answer`, `status`, `tag`, `del_flag`, `view_count`, `last_view_time`, `add_time`) VALUES
('<p>Q384. 高并发秒杀系统的核心设计思路和架构？</p>', '<p>答案解析：秒杀系统的核心挑战是超高并发下的超卖、性能、稳定性问题。整体架构分层：1、前端层——秒杀按钮点击后置灰+防抖（防止用户重复点击）+验证码（分散请求流量）。<br/>2、网关层——Sentinel限流（设置QPS阈值，超出直接返回"活动太火爆"），过滤掉大部分无效请求。<br/>3、应用层——Redis预减库存（Lua脚本原子扣减：`if redis.call(''''get'''', KEYS[1])>0 then redis.call(''''decr'''', KEYS[1]) return 1 else return 0 end`），扣减成功才放入MQ异步下单，失败直接返回"已售罄"。<br/>4、消息队列层——RocketMQ削峰，平滑异步下单（下单是最耗时的环节——校验资格、计算价格、生成订单、扣实际库存）。<br/>5、数据库层——最终扣减数据库库存（乐观锁version防超卖）、生成订单记录。关键防护：接口防刷（同一用户ID+商品ID限制N秒内只能请求一次，Redis SETNX实现）、地址隐藏（秒杀开始前URL不可见，动态生成md5 URL）、热点数据预热（活动开始前将商品库存缓存到Redis）。核心原则：尽量将请求阻挡在上游（能拦在网关不拦在应用，能拦在Redis不拦在DB）、异步化（下单异步化，避免同步阻塞和超卖）。</p>', 1, 12, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q385. 分布式ID生成方案的选型和雪花算法原理？</p>', '<p>答案解析：需求：全局唯一、趋势递增（便于数据库索引）、高性能、高可用。常见方案：1、UUID——本地生成、无性能瓶颈，但字符串无序（聚簇索引插入时InnoDB频繁分裂页、占用空间大）。不适合做主键。<br/>2、数据库自增ID——简单但单点瓶颈（高并发下数据库压力大）、不适用分库分表。<br/>3、Redis自增（INCRBY）——性能高、ID递增。缺点：需Redis持久化（AOF），Redis宕机恢复后ID可能重复（需设置大于数据表中最大ID的起始值）。<br/>4、号段模式（Leaf-segment）——从数据库批量取一段ID号段（如1~1000）缓存在内存中，用完再取下一段。高性能（内存分发ID），美团Leaf基于此方案。<br/>5、雪花算法（Snowflake，最常用）：64位long型ID = 1位符号位（始终0）+41位毫秒时间戳（约69年）+10位机器ID（5位机房+5位机器，最多1024台机器）+12位序列号（同毫秒内自增，每台机器每毫秒4096个ID）。优点：本地生成无网络开销、趋势递增（时间高位在前）、高并发（每台机器TFS可达409万/秒）。注意：时钟回拨会生成重复ID，处理方式——短时间回拨等待追上、长时间回拨抛异常。分布式部署需分配不同的机器ID（通过ZooKeeper/Redis分配或配置文件指定）。</p>', 1, 12, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q386. 线上OOM内存泄漏如何排查和定位？</p>', '<p>答案解析：排查流程（五步法）：1、发现——通过监控告警发现应用频繁Full GC、内存使用率持续上升、应用响应变慢、最终OOM崩溃。<br/>2、保留现场——JVM启动时添加参数：`-XX:+HeapDumpOnOutOfMemoryError -XX:HeapDumpPath=/opt/dump/`，OOM时自动导出heap dump文件（快照）。如果未配置，可使用`jmap -dump:format=b,file=heap.hprof <pid>`手动导出（注意此操作会触发STW）。<br/>3、分析dump——使用MAT（Memory Analyzer Tool）或JProfiler打开dump文件。分析方法：①Histogram查看内存中各类的对象实例数量和占用大小（找出数量/体积异常大的类）；<br/>②Dominator Tree查看"谁持有这些对象不释放"（找出GC Root引用链）；<br/>③Leak Suspects让MAT自动分析内存泄漏嫌疑（给出可能泄漏的对象和持有者引用链）。<br/>4、定位代码——根据dump分析结果找到是哪个类、哪个集合、哪段代码导致了对象无法回收。常见元凶：ThreadLocal未remove、static集合无限增长、数据库/网络连接未关闭、缓存容量无上限。<br/>5、修复验证——代码修复+压测验证内存不再增长。定期在测试环境做内存压测+dump分析，提前发现潜在泄漏。</p>', 1, 12, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q387. 接口限流的几种实现方式及使用选择？</p>', '<p>答案解析：限流维度：1、网关层全局限流——Spring Cloud Gateway的RequestRateLimiter（基于Redis令牌桶），对所有API做总量级限流（如整站最大5万QPS）。<br/>2、服务层接口限流——Sentinel定义QPS阈值，可精细到每个Controller方法（如下单接口限流1000QPS，查询接口3000QPS）。<br/>3、用户维度限流——同一用户/同一IP在N秒内只能请求M次（防刷）。Redis实现：`String key = "rate:limit:"+userId; long count = redis.incr(key); if(count==1) redis.expire(key, n); if(count>m) return "请求过于频繁"`。<br/>4、热点参数限流——Sentinel热点参数限流，对同一个商品ID的请求做限制（防止单一商品被打爆）。实现层次：单机限流——Guava RateLimiter（令牌桶，适合粗粒度，但不支持分布式）；分布式限流——Redis+Lua脚本（令牌桶或滑动窗口），支持全局限流。最佳实践：多层限流组合——网关层统一限流（保护整体）+业务层针对性限流（保护核心接口）+用户/维度精细限流（防恶意刷接口）+Sentinel控制台可视化监控。限流后处理：被限流的请求返回统一错误码（如429 Too Many Requests）或执行降级逻辑（返回缓存数据）。</p>', 1, 12, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q388. 项目中的RBAC权限模型是如何设计的？</p>', '<p>答案解析：RBAC（Role-Based Access Control）五张核心表：用户表（user）、角色表（role）、权限表（permission/menu）、用户-角色关联表（user_role）、角色-权限关联表（role_permission）。用户→角色→权限的三层模型，不直接给用户分配权限，通过角色间接授权（便于管理）。权限细分两个层面：菜单权限——控制前端路由和侧边栏菜单的显示（用户登录后从后端获取菜单树，前端根据返回的菜单树动态注册路由addRoute）。按钮权限——控制页面内按钮的显示（后端返回用户拥有的权限标识列表如["user:add","user:edit","user:delete"]，前端通过自定义指令v-permission="''''user:delete''''"控制按钮是否显示）。后端接口权限——Spring Security或拦截器校验每个Controller方法所需的权限（@PreAuthorize("hasAuthority(''''user:add'''')")），前端隐藏按钮只是友好处理，真正安全校验在后端。数据权限——按部门、区域等维度控制用户只能操作自己管辖范围的数据（如销售人员只能看自己的订单，区域经理看本区域订单），通过在SQL中追加数据过滤条件实现。权限设计的核心原则：永远在后端做权限校验（前端只是增强体验），权限要细粒度到接口和数据级。</p>', 1, 12, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q389. JWT+Redis的登录认证方案如何设计？</p>', '<p>答案解析：认证流程：1、用户提交用户名+密码→后端校验→生成JWT Token（payload存放用户ID+用户名，设置过期时间如2小时）→同时将Token存入Redis（key=token，value=用户信息+权限列表，过期时间同JWT）。<br/>2、返回Token给前端，前端存入localStorage或cookie。<br/>3、前端每次请求在Header中携带`Authorization: Bearer <token>`。<br/>4、后端网关/拦截器校验：解析JWT获取用户ID→查询Redis确认Token存在且未过期→刷新Redis过期时间（如果快到期自动续期）→将用户信息存入ThreadLocal。<br/>5、退出登录：删除Redis中的token记录+前端清除本地token。为什么JWT+Redis组合而非纯JWT：JWT本身是无状态的，签发后无法主动失效（不能强制踢人下线、不能修改权限立即生效）。加Redis后变为有状态——通过删除/修改Redis中的Token记录即可实现主动失效、权限实时更新。续期策略：当用户Token还剩不到一半时间时，生成新Token返回前端（通过响应头或特定接口），前端无感更新。安全加固：Token设置合理的过期时间（不宜太长）、HTTPS传输、敏感接口二次验证（如修改支付密码需短信验证码）。</p>', 1, 12, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q390. 项目中如何做好日志规范及线上问题排查？</p>', '<p>答案解析：日志规范：1、统一使用SLF4J+Logback（日志门面+实现），避免各组件使用不同日志框架。<br/>2、使用占位符而非字符串拼接：`log.info("用户{}登录成功", userId)`（字符串拼接会有额外创建开销且即使日志级别不输出也会执行拼接）。<br/>3、打印规范——关键操作（用户登录、订单创建、支付成功/失败）必须打INFO日志；异常必须打ERROR日志并打印完整堆栈（`log.error("订单创建失败", e)`，第二个参数是异常对象）；禁止打印敏感信息（密码、token、身份证号，如果必要需脱敏如手机号中间4位变****）。<br/>4、链路追踪——MDC（Mapped Diagnostic Context）中put traceId（在网关或拦截器中生成UUID存入MDC），logback配置中`%X{traceId}`打印traceId，一个请求的全链路日志串联可追踪。线上排查技巧：1、ELK/SkyWalking集中收集日志，按traceId搜索完整链路。<br/>2、异常告警——统计5分钟内ERROR日志数量，超出阈值（如>10条）自动告警通知。<br/>3、关键方法论——从监控大盘发现问题→查看链路追踪找到异常服务→按traceId搜索日志→定位异常代码。<br/>4、保留现场——JVM参数配置-XX:+PrintGCDateStamps记录GC日志、配置dump路径备OOM分析。</p>', 1, 12, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q391. XXL-JOB分布式定时任务如何避免集群重复执行？</p>', '<p>答案解析：XXL-JOB是分布式定时任务调度平台，解决传统@Scheduled在集群环境下的核心问题。架构：调度中心（admin）负责管理任务和调度触发，执行器（executor）负责执行具体任务逻辑，两者通过HTTP通信。避免重复执行机制：调度中心通过数据库行锁（`select ... for update`）锁定一条任务调度记录，保证同一任务同一时刻只有一次调度请求被触发。调度中心从已注册的执行器列表中选一台（路由策略：第一个/轮询/随机/一致性哈希/最不经常使用/故障转移/分片广播等）发送调度请求，只有收到请求的那台执行器执行。分片广播模式（特殊）：调度中心同时向所有执行器发送请求，执行器通过分片参数（shardIndex/shardTotal）各处理一部分数据（如3台执行器各处理1/3的数据），实现并行处理大数据量。任务失败重试：调度中心检测任务执行失败，自动重试（可配置重试次数）。监控告警：任务执行失败/超时可通过邮件告警，调度中心页面可以查看任务执行日志。与@Scheduled对比：@Scheduled基于JVM本地锁（单机保证单次），集群多节点都会执行；XXL-JOB基于调度中心统一调度，保证集群中只有一台执行。</p>', 1, 12, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q392. 项目安全防护需要从哪些层面考虑？</p>', '<p>答案解析：六层安全防护体系：1、传输安全——强制HTTPS，防止数据传输过程中被窃听或篡改；API签名（请求参数签防止被篡改后重发）。<br/>2、认证授权——JWT+Redis统一认证，RBAC角色权限模型，网关统一鉴权+敏感接口二次认证。<br/>3、注入防护——SQL注入：MyBatis用#{}不用${}（预编译防注入），动态排序字段白名单校验；XSS：后端对用户输入做HTML转义，前端避免v-html渲染不受信任的内容；CSRF：SameSite Cookie+校验Referer；命令注入：禁止拼接用户输入执行Runtime.getRuntime().exec()或ProcessBuilder。<br/>4、敏感数据保护——密码使用BCrypt（Spring Security默认）加密存储（不可逆、加盐防彩虹表）；敏感信息脱敏（日志、接口返回时对身份证/手机号/银行卡脱敏）；配置文件敏感信息加密（jasypt加密数据库密码）。<br/>5、接口安全——接口幂等防重复提交、接口限流防刷、参数校验防恶意输入（@Valid+白名单校验）、文件上传限制类型和大小。<br/>6、运维安全——数据库不对外暴露端口（仅内网访问）、服务器最小权限原则、定期安全扫描（dependency-check检查依赖漏洞）、日志审计。核心理念：永远不信任任何用户输入，在后端对一切做校验和过滤。</p>', 1, 12, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q393. 项目中大文件、大数据量导出如何优化？</p>', '<p>答案解析：核心原则：杜绝一次性加载所有数据到内存。分步优化方案：1、分页流式查询——使用MyBatis游标查询（Cursor/ResultHandler）或分页查询，每次只加载一批数据（如5000条）到内存，处理完一批释放再加载下一批，避免内存撑爆。<br/>2、流式写入Excel——使用EasyExcel或Apache POI的SXSSFWorkbook（流式模式），内存中只保留最近的N行，其余写入磁盘临时文件。EasyExcel基于事件解析和流式写入，内存占用极低（几十MB即可导出百万行）。<br/>3、异步导出——用户点击导出按钮后立即返回"导出任务已提交，稍后在下载中心查看"（不阻塞用户）。后台异步线程执行导出任务，完成后将文件上传到OSS/MinIO，生成下载链接通知用户。<br/>4、分批导出——如果数据量级巨大（百万级），可按时间段分批导出（如每天导出一个月的数据），分多个文件压缩打包下载。<br/>5、数据压缩——导出的CSV/Excel文件使用ZIP压缩后再供下载（文件大小可减少80%以上）。<br/>6、超时处理——导出任务设置合理的超时时间，超时则提示用户缩小数据范围导出。优化对比：传统方式导出10万条可能导致OOM+30s超时；流式查询+流式写入+异步导出可在2分钟内完成50万行导出，内存占用仅50MB。</p>', 1, 12, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q394. 分库分表在项目中的落地实践和注意事项？</p>', '<p>答案解析：实施步骤：1、确定分片键——选最频繁的查询条件作为分片键（如用户ID、订单号），使大部分查询都能路由到单个库表。选错分片键会导致查询需跨所有库广播（如按用户ID分片但要按订单状态查询）。<br/>2、选择分片算法——取模（简单均匀但扩容需全量迁移）、一致性哈希（扩缩容只影响部分数据）、日期范围（按月/年，适合历史数据和按时间查询场景）。<br/>3、中间件选型——Sharding-JDBC（代码层无侵入，性能好）或MyCat（代理层，支持多种数据库）。<br/>4、数据迁移——存量数据通过定时任务分批迁移（如每次1000条，不影响线上），增量数据通过Canal监听binlog双写（同时写旧表和分片表），灰度切流量。<br/>5、验证一致性——双写一段时间后全量对账，确保新旧数据完全一致再切流。落地注意事项：①跨库JOIN/聚合无法实现——业务层拆分查询+内存聚合；<br/>②分布式事务——用Seata或可靠消息保证跨库一致性；<br/>③全局唯一ID——用雪花算法替代数据库自增ID（分库后自增ID会冲突）；<br/>④扩容方案——避免用简单取模（扩容需全量数据迁移），考虑使用一致性哈希或预先分多片（如分32个库，初期部署在4台服务器上，后续扩到8/16/32台只需迁移部分数据）。</p>', 1, 12, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q395. 线上故障的定位思路、应急处理和复盘流程？</p>', '<p>答案解析：故障处理三步法：一、止血（最高优先级<1分钟）——发现问题（监控告警/用户反馈）→快速评估影响面（是否核心业务、影响多少用户）→决策：重启回滚还是降级。优先恢复服务而非找根因（先止血后治病）。回滚：新发布的版本立即回滚到上一个稳定版本。降级：关闭非核心功能，保核心链路。扩容：流量激增导致容量不足时紧急扩容服务实例。二、定位故障根因——查看监控大盘（QPS突增？RT暴涨？错误率飙升？CPU/内存异常？）→查看链路追踪定位是哪个服务、哪个方法出问题→查看对应服务的日志（按traceId搜索）→找到具体异常堆栈→排查近期的变更（代码发布/配置变更/数据库变更/外部依赖变动）。常见根因：慢SQL导致数据库连接池耗尽、下游服务宕机、Redis缓存雪崩、代码bug（空指针/死循环）、网络故障（跨机房延迟）。三、修复验证——代码修复→压测验证→灰度发布→全量上线→观察监控数据恢复正常。复盘文档：故障标题、发生时间、持续时长、影响范围、根因分析（5 Why法深挖）、应急处理过程、永久性改进措施（不只是改代码还要加监控/限流/降级开关/自动化测试等防重犯措施）。</p>', 1, 12, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q396. 如何设计一个通用的接口幂等方案？</p>', '<p>答案解析：通用幂等方案核心是"唯一请求ID + 状态记录"。架构设计：1、请求ID生成——客户端每次操作生成全局唯一的请求ID（UUID或雪花算法），放在请求头或参数中。<br/>2、幂等拦截器——定义@Idempotent注解标记需要幂等的接口，编写AOP切面拦截。切面逻辑：①从请求中获取requestId；<br/>②判断：Redis中`SETNX requestId 处理中 EX 600`（设置成功说明是首次请求，继续执行业务；设置失败说明请求已处理或正在处理）；<br/>③正在处理中返回"请勿重复提交"；<br/>④已处理完成返回上次处理的结果（从Redis获取缓存的处理结果）。<br/>3、业务执行成功后——将处理结果存入Redis（`SET requestId result EX 1800`），同时将状态标记为已完成。<br/>4、数据库兜底——对关键业务字段建唯一索引（如订单号），即使Redis的SETNX因极端情况失效，数据库的唯一索引也能拦截重复写入（捕获DuplicateKeyException返回成功或幂等结果）。关键设计：①区分"处理中"和"已完成"两种状态——处理中拒绝请求，已完成返回缓存结果；<br/>②设置合理的过期时间——处理中超时需自动释放（避免因为死锁导致用户永远无法重试）；<br/>③数据库中业务表需要有计划号字段（unique key），与幂等requestId关联核实。适用范围：支付、下单、扣款、领券等所有权变更操作必须做幂等。</p>', 1, 12, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q397. 微服务间跨服务调用异常如何排查？</p>', '<p>答案解析：排查流程：1、看链路追踪——SkyWalking/Zipkin查看调用链拓扑图，找到哪个服务调用哪个服务时出问题（红色Span标注的异常点）。点击异常Span查看详情：请求参数、响应内容、异常堆栈、耗时。<br/>2、判断是超时还是报错——超时（耗时>超时阈值）：可能是下游服务处理慢、网络延迟、下游负载高。报错（异常堆栈明确）：可能是下游代码bug、参数错误、下游依赖故障。<br/>3、排查下游服务——查看下游服务的日志，按traceId搜索，找到对应时间点的错误日志。<br/>4、检查注册中心——Nacos查看服务实例是否在线、有几个实例（可能全部宕机只剩一个实例扛不住流量）。<br/>5、检查网络——从消费者机器telnet/TCP ping提供者的IP+端口，检查网络是否连通、是否有防火墙拦截。<br/>6、检查配置——Feign超时时间是否配得太短、是否调用了错误的提供者（服务名写错、namespace不对）。常见原因与解决方案：超时→增加超时时间或优化下游处理速度；服务不可用→检查部署状态、熔断后降级返回兜底；参数传递错误→检查DTO序列化、字段类型匹配；线程池满→增加消费者线程数或扩容。预防措施：所有Feign调用配置fallback降级逻辑、合理超时时间、监控服务间调用成功率。</p>', 1, 12, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q398. 项目高并发场景的整体优化思路？</p>', '<p>答案解析：高并发优化遵循"漏斗模型"——从上到下逐层削减流量，只有少部分请求到达数据库。架构层级和优化策略：1、CDN+静态化——静态资源（图片、JS、CSS）走CDN缓存，不经过应用服务器。页面数据能静态化的尽量静态化或加本地缓存。<br/>2、前端优化——按钮防抖（防止重复点击）、页面缓存、减少不必要的请求。<br/>3、网关层——全局限流、IP黑名单、统一鉴权后放行合法请求。<br/>4、缓存层（Redis）——热点数据预热到Redis，读写分离（Redis集群分片），多级缓存（本地Caffeine+Redis），布隆过滤器拦截无效请求。设置合理的过期策略（随机打散防雪崩）。数据库的压力80%可被正确缓存消解。<br/>5、应用层——无状态服务水平扩容、线程池合理配置、代码优化（避免循环查库、避免大事务、异步处理非核心逻辑）、接口限流+降级兜底。<br/>6、消息队列层——异步解耦、削峰填谷（将同步调用改为异步消息，平滑处理流量洪峰）。<br/>7、数据库层——读写分离（主库写、从库读）、分库分表（水平拆分降低单表压力）、SQL优化（索引+慢SQL治理）、连接池优化（合理设置最大连接数）。核心理念：让请求尽可能在越上层被处理（越下层成本越高），减少到达数据库的QPS。</p>', 1, 12, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q399. 项目中的分布式事务实际是如何处理的？</p>', '<p>答案解析：实际项目中不对所有跨服务操作都用强分布式事务（Seata AT性价比不高）。分场景选择方案：1、核心交易链路（订单创建+扣库存+扣优惠券）——使用Seata AT模式，加@GlobalTransactional注解，确保强一致性。但注意该模式适合低并发场景，高并发秒杀场景不适合（锁竞争大）。<br/>2、非核心异步链路（下单成功→发短信+送积分+发优惠券）——使用RocketMQ可靠消息最终一致性。本地事务中同时写消息表（status=待发送），定时任务扫描消息表发送MQ，消费端做幂等处理。优点：异步解耦，不阻塞主流程。<br/>3、跨系统对接（调用外部支付通道、第三方物流）——使用本地消息表+TCC补偿。核心原则：能异步的不同步、能最终一致的不追求强一致、尽量通过业务设计避免分布式事务（如将需要事务的操作放在同一个服务同一个库中）。频繁修改同一行数据的场景（如库存扣减）用乐观锁+CAS循环重试（自旋更新库存，无分布式事务开销）。实际落地的关注点：异常数据监控（定时扫描中间状态订单上报告警）、人工后台补偿（客服手动修正数据）。分布式事务不是银弹，非必要不引入，业务设计优于技术方案。</p>', 1, 12, 0, 0, NULL, CURRENT_TIMESTAMP),
('<p>Q400. 项目中缓存一致性问题的实际解决方案？</p>', '<p>答案解析：实战中不追求缓存和数据库的强一致性（代价太高），而是确保最终一致性。分场景方案：1、简单业务（对一致性要求不高的查询，如商品详情、用户信息）——采用Cache Aside模式：读（先查缓存，miss查DB并回写缓存）、写（先更新DB，后删除缓存）。删除缓存失败时通过异步重试（MQ延时重试或Canal补偿）。设置合理的缓存过期时间作为最终一致性的兜底（缓存过期后自动从DB加载最新数据）。<br/>2、高一致性场景（库存、余额等）——不使用Redis缓存，直接查数据库（配合乐观锁保证精确扣减）。如果一定要用Redis，需用Lua脚本保证读写原子性（扣减库存前先检查，Redis操作失败回退）。<br/>3、双写一致性（Canal方案）——通过Canal监听MySQL binlog，binlog变更→Canal解析→推送到MQ→缓存同步服务消费→更新/删除Redis数据。优点：业务代码无感知、增量同步延迟低（百毫秒到秒级）。<br/>4、多级缓存一致性——本地Caffeine缓存设置极短过期时间（如5秒），Redis缓存设较长过期时间（如30分钟）。数据更新时：先更新DB→通过MQ广播通知所有服务实例清空本地缓存+Redis缓存，各实例收到消息后重新从DB加载。核心取舍：绝对一致性=放弃高可用（加分布式锁每次查DB），业务需权衡后选择最适合的一致性级别。</p>', 1, 12, 0, 0, NULL, CURRENT_TIMESTAMP);
